window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s6-416","number":416,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"لماذا نُكّرت ﴿ورقة﴾ وزيدت ﴿من﴾ قبلها؟","answer":"دخلت ﴿من﴾ الزائدة بعد النفي لتأكيد الاستغراق، ونُكرت ﴿ورقة﴾ لتشمل أي ورقة مهما دقت وبعد مكانها؛ فلا تسقط واحدة إلا بعلمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص16، تحت «دلالة (من) في ﴿من ورقة﴾ وفائدة التنكير»","url":""}]},{"id":"s6-417","number":417,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"لم قيل ﴿إلا يعلمها﴾ ولم يقيد العلم بسقوط الورقة؟","answer":"ليعم العلم جميع أحوالها؛ فيعلمها قبل السقوط وبعده، وفي ثباتها وسقوطها، ويعلم مكانها وهيئتها وسائر تفاصيلها. فإطلاق العلم أوسع من قصره على حادثة السقوط وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص16–17، تحت «فائدة إطلاق العلم بالورقة دون تقييده»","url":""}]},{"id":"s6-418","number":418,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا حبة في ظلمات الأرض﴾، فجعل الحبة في ظلمات جمع؟","answer":"جُمعت ﴿ظلمات﴾ للمبالغة في دقة علم الله وسعته؛ فباطن الأرض ظلمة متكاثفة متكاثرة بالنسبة إلى الإنسان لجهله بما يجري فيه حتى يظهر، ومع ذلك لا تخفى الحبة على علم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص18، تحت «سر جمع ﴿ظلمات﴾»","url":""}]},{"id":"s6-419","number":419,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"لماذا قابل بين ﴿رطب﴾ و﴿يابس﴾؟","answer":"جُمع الرطب واليابس، وهما وصفان متقابلان، لإفادة العموم والشمول؛ فكل شيء اتصف بالرطوبة أو اليبوسة داخل في علم الله تعالى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص18، تحت «فائدة تنكير الرطب واليابس».","url":""}]},{"id":"s6-420","number":420,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا رطب ولا يابس﴾، وكرر ﴿لا﴾؟","answer":"كُررت ﴿لا﴾ مع الرطب واليابس لتوكيد النفي والمبالغة في شمول علم الله؛ فلا يخرج عنه شيء اتصف بالرطوبة أو اليبوسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص18، تحت «نكتة تعديد المستثنى منه في قوله تعالى: ﴿ولا رطب ولا يابس﴾».","url":""}]},{"id":"s6-421","number":421,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"ما نكتة تعدد المستثنى منه في قوله تعالى: ﴿ولا رطب ولا يابس إلا في كتاب مبين﴾؟","answer":"جُمع الرطب واليابس وهما طرفان متقابلان ليستوعب التعبير الموجودات على اختلاف أحوالها، فيقرر أن شيئًا منها لا يخرج عن العلم والكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص18–19، تحت عنوان «نكتة تعدد المستثنى منه في قوله تعالى: ﴿ولا رطب ولا يابس﴾»","url":""}]},{"id":"s6-422","number":422,"surah":6,"verses":[59],"references":[{"surah":6,"verses":[59]}],"verseLabel":"الأنعام: 59","question":"ما الذي يضيفه وصف الكتاب بـ﴿مبين﴾ في مقام إحاطة علم الله؟","answer":"يدل على صحة ما أثبت فيه؛ فالأشياء تقع موافقة لما رسم في الكتاب من أعدادها وأوقاتها وأحوالها. فالوصف يؤكد أن هذا الإثبات حق يظهر صدقه بوقوع المقدور على وفقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص10–12، تحت «شرح المفردات: ﴿كتاب مبين﴾»","url":""}]},{"id":"s6-423","number":423,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"لماذا عبّر عن النوم بقوله: ﴿يتوفاكم بالليل﴾؟","answer":"التوفي استيفاء الشيء وقبضه؛ والنوم قبض مؤقت لإدراك الإنسان وحركته، فشبه بالموت وسمي وفاة صغرى، ثم يكون الاستيقاظ بعثًا مصغرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص23–24، تحت «دلالة الاستعارة التبعية في قوله تعالى: ﴿يتوفاكم بالليل﴾»","url":""}]},{"id":"s6-424","number":424,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"ما دلالة الباء في قوله تعالى: ﴿يتوفاكم بالليل﴾؟","answer":"جاءت الباء بمعنى الظرفية، أي يتوفاكم في الليل؛ فحدد التركيب الزمن الغالب للنوم مع إيجاز العبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص24، تحت عنوان «دلالة الباء في قوله تعالى: ﴿بالليل﴾ على معنى (في) الظرفية»","url":""}]},{"id":"s6-1189","number":1189,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"ما المراد بالليل والنهار في قوله تعالى: ﴿يتوفاكم بالليل ويعلم ما جرحتم بالنهار﴾؟","answer":"ذُكر الليل زمنًا غالبًا للنوم والسكون، والنهار زمنًا غالبًا للكسب والحركة؛ فالكلام جارٍ على المعتاد ولا ينفي نوم النهار أو العمل ليلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص25–26، تحت عنوان «المراد بالليل والنهار في قوله تعالى: ﴿يتوفاكم بالليل ويعلم ما جرحتم بالنهار﴾»","url":""}]},{"id":"s6-425","number":425,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"لماذا عُدّيت الوفاة بالباء: ﴿يتوفاكم بالليل﴾، لا: في الليل؟","answer":"الباء في ﴿بالليل﴾ بمعنى ﴿في﴾؛ وأفادت الظرفية من أصل معنى الملابسة، لأن الفعل الملاصق للزمان واقع فيه. فالمعنى: يتوفاكم في الليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص24–25، تحت «دلالة الباء في قوله تعالى: ﴿بالليل﴾ على معنى (في) الظرفية»","url":""}]},{"id":"s6-426","number":426,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"لماذا قابل النوم بقوله: ﴿ويعلم ما جرحتم بالنهار﴾؟","answer":"قوبل توفي الليل بكسب النهار لتصوير دورة الإنسان كاملة: يسكن فتقبض حواسه، ثم يبعث للعمل مع كون أعماله كلها معلومة لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص26–27، تحت «دلالة تخصيص التوفي بالليل والجرح بالنهار»","url":""}]},{"id":"s6-427","number":427,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"لماذا عبّر عن الأعمال بـ﴿ما جرحتم﴾؟","answer":"عُبر عن الأعمال بـ﴿جرحتم﴾ لأن الجرح والاجتراح يدلان على الكسب والعمل بالجوارح، وأصلهما مستعار من تأثير الجارح؛ واختير الجرح هنا بدل الكسب، وهو أعم، لما فيه من الإيحاء بمباشرة العمل المكروه وتقوية التهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص33–34، تحت «الجرح والكسب»","url":""}]},{"id":"s6-428","number":428,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم يبعثكم فيه﴾، فجعل الاستيقاظ بعثًا؟","answer":"الاستيقاظ إعادة للحس والحركة بعد قبضهما في النوم، فسمي بعثًا لتمثيله البعث الأكبر وتقريب إمكانه بتجربة تتكرر كل يوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص30، تحت «أثر الاستعارة المرشحة في تجلية المعنى في قوله تعالى: ﴿ثم يبعثكم فيه﴾»","url":""}]},{"id":"s6-429","number":429,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"إلى ماذا يعود الضمير في ﴿فيه﴾: إلى النهار أم إلى الزمن؟","answer":"على تفسير البعث بالإيقاظ من النوم يعود الضمير إلى النهار؛ أي يوقظكم فيه بعد توفي الليل، فتكتمل المقابلة بين النوم واليقظة. ويذكر المصدر وجهًا آخر يحمل البعث على البعث بعد الموت، فلا يصح إغفال اختلاف التفسير.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص29–30، تحت «دلالة عطف جملة: ﴿ثم يبعثكم فيه﴾»","url":""}]},{"id":"s6-430","number":430,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"لم جعل تعاقب النوم واليقظة سبيلًا إلى ﴿ليقضى أجل مسمى﴾؟","answer":"تربط لام التعليل هذا النظام باستيفاء العمر المقدر؛ فكل نوم ويقظة يمضيان بالإنسان إلى تمام أجله. وبذلك ينتقل النظر من دورة اليوم والليلة إلى نهاية الحياة والرجوع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص31، تحت «أثر لام التعليل في بيان المعنى في قوله تعالى: ﴿ليقضى أجل مسمى﴾»","url":""}]},{"id":"s6-431","number":431,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"لماذا وصف الأجل بـ﴿مسمى﴾؟","answer":"المسمى هو المحدد المقدر الذي لا يتقدم ولا يتأخر؛ فالوصف ينفي العبث والجهالة عن أعمارهم ويقرر أن لكل حياة نهاية معلومة عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص31، تحت «أثر لام التعليل في بيان المعنى في قوله تعالى: ﴿ليقضى أجل مسمى﴾»","url":""}]},{"id":"s6-432","number":432,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"ما دلالة الحصر بتقديم ﴿إليه﴾ في قوله تعالى: ﴿ثم إليه مرجعكم﴾؟","answer":"قدم الجار والمجرور فقصر المرجع على الله، ونفى أن يكون للخلق مآل أو ملجأ يستقلون به عن حكمه وحسابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص31، تحت عنوان «دلالة الحصر بتقديم المسند ﴿إليه﴾»","url":""}]},{"id":"s6-1190","number":1190,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم ينبئكم بما كنتم تعملون﴾؟","answer":"تدل على المهلة والترتيب؛ فالإنباء بالأعمال والحساب يأتي بعد الرجوع والحشر، لا في لحظة الموت نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص32، تحت عنوان «دلالة (ثم) على المهلة في قوله تعالى: ﴿ثم ينبئكم بما كنتم تعملون﴾»","url":""}]},{"id":"s6-433","number":433,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"ما سرّ تقديم ﴿إليه﴾ في ﴿ثم إليه مرجعكم﴾؟","answer":"قُدم ﴿إليه﴾ لقصر المرجع على الله وتأكيده؛ فلا تنتهي الخلائق إلى غير حكمه، كما لم تكن حياتهم وموتهم إلا بتدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص31، تحت «دلالة الحصر بتقديم المسند ﴿إليه﴾».","url":""}]},{"id":"s6-434","number":434,"surah":6,"verses":[60],"references":[{"surah":6,"verses":[60]}],"verseLabel":"الأنعام: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿ينبئكم بما كنتم تعملون﴾، والله يعلم أعمالهم وهم يعرفونها؟","answer":"الإنباء ليس لإعلامهم بشيء مجهول، بل لمواجهتهم بأعمالهم مفصلة وإقامة الحجة والجزاء عليها؛ لذلك علق بما كانوا يعملون.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص32–33، تحت «ذكر بعض عناصر الحدث للكناية عن الكل في آخر الآية»","url":""}]},{"id":"s6-435","number":435,"surah":6,"verses":[61],"references":[{"surah":6,"verses":[61]}],"verseLabel":"الأنعام: 61","question":"كيف يتصل ﴿وهو القاهر فوق عباده﴾ بذكر النوم واليقظة ثم الموت؟","answer":"ينقل السياق من التصرف في نوم الإنسان ويقظته إلى بيان السلطان الذي تخضع له حياته ونهايته. فكما لا يستقل بالاستيقاظ من نومه، لا يمتنع عن الموت إذا جاء أجله؛ وكل ذلك من آثار قهر الله وتدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص38–39، تحت «العطف يبين قدرة الله على عباده في الحياة وعند الممات»","url":""}]},{"id":"s6-436","number":436,"surah":6,"verses":[61],"references":[{"surah":6,"verses":[61]}],"verseLabel":"الأنعام: 61","question":"لماذا عطف على القهر قوله: ﴿ويرسل عليكم حفظة﴾؟","answer":"إرسال الحفظة أثر من آثار قهره وتدبيره؛ فهم يراقبون أعمال العباد ويحفظون ما وُكل إليهم، فلا يخرج أحد عن سلطانه مع أن الحفظ نفسه عناية ورحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص40–41، تحت «عطف القصر على سابقه في قوله تعالى: ﴿ويرسل عليكم حفظة﴾»","url":""}]},{"id":"s6-437","number":437,"surah":6,"verses":[61],"references":[{"surah":6,"verses":[61]}],"verseLabel":"الأنعام: 61","question":"لماذا عُدّي إرسال الحفظة بـ﴿عليكم﴾، لا: إليكم؟","answer":"﴿عليكم﴾ تفيد الاستعلاء والرقابة والملازمة؛ فالحفظة موكلون بالعباد ومهيمنون على تسجيل أعمالهم، لا مجرد رسل يصلون إليهم ثم ينصرفون.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص41، تحت «دلالة حرف الاستعلاء (على) في قوله تعالى: ﴿ويرسل عليكم حفظة﴾».","url":""}]},{"id":"s6-438","number":438,"surah":6,"verses":[61],"references":[{"surah":6,"verses":[61]}],"verseLabel":"الأنعام: 61","question":"لم يذكر إرسال الحفظة مع أن الله يعلم أعمال العباد؟","answer":"في ذكرهم إشعار بالمراقبة وإقامة للشهادة على الأعمال، فيستحيي العبد أن تسجل عليه معصيته ويعرض بها يوم القيامة. فالحفظ زاجر وتنبيه له، وليس لأن علم الله يحتاج إلى من يكمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص40، تحت «عطف القصر على سابقه في قوله تعالى: ﴿ويرسل عليكم حفظة﴾»","url":""}]},{"id":"s6-439","number":439,"surah":6,"verses":[61],"references":[{"surah":6,"verses":[61]}],"verseLabel":"الأنعام: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى إذا جاء أحدكم الموت﴾، فجعل الموت آتيًا؟","answer":"صُور الموت كآت يقصد كل إنسان ويصل إليه في موعده، فيجعل حتميته وقربه مشهدًا حيًا لا يستطيع أحد الهرب منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص43، تحت «تعلق الفعل بالضمير، في قوله تعالى: ﴿جاء أحدكم الموت توفته﴾».","url":""}]},{"id":"s6-440","number":440,"surah":6,"verses":[61],"references":[{"surah":6,"verses":[61]}],"verseLabel":"الأنعام: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿أحدكم﴾، لا: الإنسان أو أحدهم؟","answer":"﴿أحدكم﴾ تفرد كل مخاطب بالموت وتجعله معنيًا بالإنذار، فلا يضيع الفرد في لفظ عام؛ وإضافته إلى ضميرهم تقرب المشهد منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص43، تحت «تعلق الفعل بالضمير في قوله تعالى: ﴿جاء أحدكم الموت توفته﴾»","url":""}]},{"id":"s6-441","number":441,"surah":6,"verses":[61],"references":[{"surah":6,"verses":[61]}],"verseLabel":"الأنعام: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿توفته رسلنا﴾ بالجمع، مع قوله في موضع آخر: ﴿يتوفاكم ملك الموت﴾؟","answer":"لملك الموت أعوان من الملائكة؛ فيصح إسناد التوفي إليه باعتباره الموكل بقبض الأرواح، وإلى الرسل باعتبار أعوانه المشاركين في ذلك. فلا تعارض بين الإفراد والجمع، إذ ينظر كل تعبير إلى جهة من تنفيذ الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص43، تحت «دلالة ورود المضاف المشتق ﴿رسلنا﴾ في قوة النكرة»","url":""}]},{"id":"s6-442","number":442,"surah":6,"verses":[61],"references":[{"surah":6,"verses":[61]}],"verseLabel":"الأنعام: 61","question":"ما دلالة ﴿حتى﴾ في قوله تعالى: ﴿حتى إذا جاء أحدكم الموت﴾؟","answer":"جعلت مجيء الموت غاية لمدة حفظ الملائكة للإنسان في حياته، فإذا بلغ أجله انتقل السياق إلى مهمة قبض روحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص42، تحت عنوان «دلالة ﴿حتى﴾ على الغاية في قوله تعالى: ﴿حتى إذا جاء أحدكم الموت﴾»","url":""}]},{"id":"s6-1191","number":1191,"surah":6,"verses":[61],"references":[{"surah":6,"verses":[61]}],"verseLabel":"الأنعام: 61","question":"ما دلالة ورود المضاف المشتق ﴿رسلنا﴾ في قوة النكرة؟","answer":"أفاد أن المتوفين رسل من رسل الله موكلون بهذه المهمة، من غير لزوم أن يكونوا الحفظة المذكورين قبلها أو رسولًا واحدًا بعينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص43، تحت عنوان «دلالة ورود المضاف المشتق ﴿رسلنا﴾ في قوة النكرة»","url":""}]},{"id":"s6-443","number":443,"surah":6,"verses":[61],"references":[{"surah":6,"verses":[61]}],"verseLabel":"الأنعام: 61","question":"لماذا خُتمت الآية بـ﴿وهم لا يفرطون﴾؟","answer":"الخاتمة تنفي عن رسل الموت أي تقصير أو تأخير أو تجاوز؛ فتوفي كل نفس يقع على وفق الأمر والأجل المقدرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص44، تحت «بلاغة القيد بالحال في الإبانة في قوله تعالى: ﴿وهم لا يفرطون﴾»","url":""}]},{"id":"s6-444","number":444,"surah":6,"verses":[61],"references":[{"surah":6,"verses":[61]}],"verseLabel":"الأنعام: 61","question":"لم أُنث الفعل في ﴿توفته رسلنا﴾ مع أن الفاعل جمع رسل؟","answer":"روعي معنى الجماعة في جمع التكسير، فصح تأنيث الفعل. وجاءت قراءة ﴿توفاه﴾ بالتذكير مراعاةً لمعنى الجمع أيضًا؛ فتتنوع الصياغة مع بقاء المعنى: تتولى الرسل قبض الروح.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص44، تحت «توجيه المعنى وفقًا لاختلاف القراءة القرآنية في قوله تعالى: ﴿توفته﴾»","url":""}]},{"id":"s6-445","number":445,"surah":6,"verses":[62],"references":[{"surah":6,"verses":[62]}],"verseLabel":"الأنعام: 62","question":"لم انتقل من ﴿أحدكم﴾ إلى صيغة الغائب الجمع في ﴿ثم ردوا إلى الله﴾؟","answer":"جرى الرد على المعنى العام لأحدكم، إذ كل فرد من المخاطبين مردود إلى الله. والانتقال من الخطاب إلى الغيبة، ومن إفراد اللفظ إلى معنى الجمع، يوقظ السامع ويجدد انتباهه إلى مصير يشمل الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص49، تحت «دلالة أسلوب الالتفات في سياق الجمل المعطوفات»","url":""}]},{"id":"s6-446","number":446,"surah":6,"verses":[62],"references":[{"surah":6,"verses":[62]}],"verseLabel":"الأنعام: 62","question":"لماذا اختير فعل ﴿ردوا﴾، لا: رجعوا؟","answer":"اختير ﴿رُدّوا﴾ لأن الرد يتضمن معنى الغلبة والقوة، ولأنه هنا رد إلى الحياة بذوات الأشخاص؛ فكان أليق بمشهد بعث العباد وإعادتهم إلى الله من ﴿رجعوا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص54، تحت «الرجوع والعودة والرد»","url":""}]},{"id":"s6-447","number":447,"surah":6,"verses":[62],"references":[{"surah":6,"verses":[62]}],"verseLabel":"الأنعام: 62","question":"لماذا وصف الله بعد الرد إليه بقوله: ﴿مولاهم الحق﴾؟","answer":"وصف الله عند ردهم إليه بأنه ﴿مولاهم﴾ لأن سلطان الملك والحكم يظهر يومئذ بلا منازع، وتسقط كل ولاية ادعوها لغيره؛ فهو الذي يتولى حسابهم ومصيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص50، تحت «الصفة وأثرها في دقة المعنى في قوله تعالى: ﴿مولاهم الحق﴾»","url":""}]},{"id":"s6-448","number":448,"surah":6,"verses":[62],"references":[{"surah":6,"verses":[62]}],"verseLabel":"الأنعام: 62","question":"ما أثر وصف ﴿مولاهم﴾ بـ﴿الحق﴾ في دقة المعنى؟","answer":"قرر أن ولاية الله هي الولاية الثابتة الحقيقية، وأن ما اتخذوه من أولياء باطل زائل؛ فهو مولاهم خلقًا وملكًا وحكمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص50، تحت عنوان «الصفة وأثرها في دقة المعنى في قوله تعالى: ﴿مولاهم الحق﴾»","url":""}]},{"id":"s6-449","number":449,"surah":6,"verses":[62],"references":[{"surah":6,"verses":[62]}],"verseLabel":"الأنعام: 62","question":"لماذا وُصف المولى بـ﴿الحق﴾؟","answer":"﴿الحق﴾ يثبت أن ولايته وحدها ثابتة نافذة، ويكشف بطلان ما اتخذوه من أولياء؛ فلا ناصر ولا حاكم يومئذ إلا المولى الحقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص50، تحت «الصفة وأثرها في دقة المعنى في قوله تعالى: ﴿مولاهم الحق﴾»","url":""}]},{"id":"s6-450","number":450,"surah":6,"verses":[62],"references":[{"surah":6,"verses":[62]}],"verseLabel":"الأنعام: 62","question":"لماذا افتتح التذييل بـ﴿ألا﴾ في قوله: ﴿ألا له الحكم﴾؟","answer":"﴿ألا﴾ أداة استفتاح وتنبيه تستدعي السمع لما بعدها من حقيقة جليلة: الحكم كله لله وحده؛ وجاءت بعد مشهد الرد إليه لتؤكد انفراده بالحكم وترد أوهام المشركين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص51، تحت «دلالة أداة الاستفتاح في قوله تعالى: ﴿ألا له الحكم وهو أسرع الحاسبين﴾»","url":""}]},{"id":"s6-451","number":451,"surah":6,"verses":[62],"references":[{"surah":6,"verses":[62]}],"verseLabel":"الأنعام: 62","question":"ما دلالة الاختصاص بتقديم ﴿له﴾ في قوله تعالى: ﴿ألا له الحكم﴾؟","answer":"تقديم الجار والمجرور يقصر الحكم على الله وحده، وينفي أن يشاركه فيه ولي مزعوم أو معبود باطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص51، تحت عنوان «دلالة الاختصاص بالقصر في تقديم ﴿له﴾ في قوله تعالى: ﴿ألا له الحكم﴾»","url":""}]},{"id":"s6-452","number":452,"surah":6,"verses":[62],"references":[{"surah":6,"verses":[62]}],"verseLabel":"الأنعام: 62","question":"ما أثر عطف قوله تعالى: ﴿وهو أسرع الحاسبين﴾ على جملة التذييل قبلها؟","answer":"وصل سرعة الحساب برد الخلق إلى مولاهم الحق وانفراد الله بالحكم؛ فبين أن حكمه يعقبه حساب لا إبطاء فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص52، تحت عنوان «العطف على جملة التذييل وأثره في المعنى في قوله تعالى: ﴿وهو أسرع الحاسبين﴾»","url":""}]},{"id":"s6-1192","number":1192,"surah":6,"verses":[62],"references":[{"surah":6,"verses":[62]}],"verseLabel":"الأنعام: 62","question":"ما بلاغة التعبير بالجملة الاسمية في قوله تعالى: ﴿وهو أسرع الحاسبين﴾؟","answer":"تفيد ثبوت هذا الوصف لله ودوامه؛ فهو يحاسب الخلق جميعًا بلا انشغال بحساب عن حساب ولا عجز أو تأخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص53، تحت عنوان «بلاغة التعبير بالجملة الاسمية في قوله تعالى: ﴿وهو أسرع الحاسبين﴾»","url":""}]},{"id":"s6-453","number":453,"surah":6,"verses":[63],"references":[{"surah":6,"verses":[63]}],"verseLabel":"الأنعام: 63","question":"ما سرّ التعبير في قوله تعالى: ﴿من ينجيكم من ظلمات البر والبحر﴾، فجمع الظلمات؟","answer":"جُمعت ﴿الظلمات﴾ لتشمل ظلمات البر والبحر ومخاوفهما حقيقةً، كالليل والعدو والتيه والغرق، ومجازًا في الشدائد الهائلة التي تبطل الحواس وتدهش العقول؛ فالجمع بين المعنيين أبلغ في استيعاب صور الكرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص60، تحت «دلالة الحقيقة والمجاز في قوله تعالى: ﴿من ظلمات البر والبحر﴾».","url":""}]},{"id":"s6-454","number":454,"surah":6,"verses":[63],"references":[{"surah":6,"verses":[63]}],"verseLabel":"الأنعام: 63","question":"كيف تكون في البر ظلمات مع انكشافه واتساعه؟","answer":"تكون في البر ظلمات الليل، وما يصاحب السير فيه من مخاوف العدو والآفات والتيه والخسف؛ وتستعار الظلمات كذلك للشدائد الهائلة التي تبطل الحواس وتدهش العقول، فلا يمنع انكشاف البر نهارًا من صدق الظلمات عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص60–61، تحت «دلالة الحقيقة والمجاز في قوله تعالى: ﴿من ظلمات البر والبحر﴾»","url":""}]},{"id":"s6-456","number":456,"surah":6,"verses":[63],"references":[{"surah":6,"verses":[63]}],"verseLabel":"الأنعام: 63","question":"ما سرّ التعبير في قوله تعالى: ﴿تدعونه تضرعًا وخفية﴾، فجمع بين التضرع والخفية؟","answer":"التضرع إظهار الضعف والذلة، والخفية إسرار الدعاء وإبطان التذلل؛ فجمعهما لاستيعاب دعائهم جهرًا وسرًا، وبيان تنوع أحوالهم عند الشدائد وانقطاع الأسباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص61، تحت «دلالة العطف للألفاظ في قوله تعالى: ﴿تضرعًا وخفية﴾».","url":""}]},{"id":"s6-457","number":457,"surah":6,"verses":[63],"references":[{"surah":6,"verses":[63]}],"verseLabel":"الأنعام: 63","question":"لم عبر بـ﴿خفية﴾ عن دعائهم المستتر دون النجوى؟","answer":"الخفية أعم؛ فهي تشمل إسرار الدعاء في النفس أو خفض الصوت به من غير حديث مع شخص آخر. أما النجوى فحديث يناجي به المرء غيره، فكان لفظ الخفية أنسب بإقبالهم المستتر على الله وقت الشدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص67–68، تحت «الخفية والنجوى والسر»","url":""}]},{"id":"s6-458","number":458,"surah":6,"verses":[63],"references":[{"surah":6,"verses":[63]}],"verseLabel":"الأنعام: 63","question":"لماذا انتقل من خطاب الجمع إلى حكاية قولهم: ﴿لئن أنجانا من هذه﴾؟","answer":"جاءت ﴿لئن أنجانا من هذه﴾ حكايةً لقولهم حال الدعاء، أي: تدعونه قائلين ذلك؛ وحُذفت ألفاظ القول لوضوح من قال ومن حكى، فصُوّر فحوى وعدهم في موقف الكرب الشديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص62، تحت «دلالة النصب بإرادة القول: ﴿لئن أنجانا من هذه لنكونن من الشاكرين﴾».","url":""}]},{"id":"s6-459","number":459,"surah":6,"verses":[63],"references":[{"surah":6,"verses":[63]}],"verseLabel":"الأنعام: 63","question":"إلى ماذا تشير ﴿هذه﴾ في ﴿لئن أنجانا من هذه﴾؟","answer":"تشير ﴿هذه﴾ إلى الظلمات أو الشدة الحاضرة التي أحاطت بهم؛ واسم الإشارة يستحضرها كأنها ماثلة أمامهم ويبرز قربها وهولها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص63–64، تحت «اعتبارات فهم اسم الإشارة في قوله: ﴿لئن أنجانا من هذه﴾»","url":""}]},{"id":"s6-460","number":460,"surah":6,"verses":[63],"references":[{"surah":6,"verses":[63]}],"verseLabel":"الأنعام: 63","question":"لماذا أكدوا وعدهم باللام والنون: ﴿لنكونن من الشاكرين﴾؟","answer":"اللام موطئة للقسم، ونون التوكيد الثقيلة تثبت الوعد؛ فشدة الكرب حملتهم على أغلظ صيغة في التعهد بالشكر إن وقعت النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص62، تحت «دلالة أسلوب القسم في قوله تعالى: ﴿لئن أنجانا من هذه لنكونن من الشاكرين﴾».","url":""}]},{"id":"s6-461","number":461,"surah":6,"verses":[63],"references":[{"surah":6,"verses":[63]}],"verseLabel":"الأنعام: 63","question":"ما دلالة تعبيرهم بقوله: ﴿لنكونن من الشاكرين﴾، دون: لنشكرن؟","answer":"قولهم ﴿من الشاكرين﴾ يتعهد بأن يكونوا ثابتين في زمرة عُرفت بالشكر، وهو أبلغ من وعد بفعل شكر مرة واحدة؛ ثم يكشف رجوعهم إلى الشرك كذب هذا التعهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص64، تحت «دلالة التعبير بحرف الجر ﴿من﴾ مع إمكان الاستغناء عنه لغة»","url":""}]},{"id":"s6-462","number":462,"surah":6,"verses":[64],"references":[{"surah":6,"verses":[64]}],"verseLabel":"الأنعام: 64","question":"لماذا جاء الجواب صريحًا: ﴿قل الله ينجيكم منها﴾، ولم يقل: هو ينجيكم؟","answer":"ذكر اسم الله جوابًا مباشرًا عن ﴿من ينجيكم﴾، وهو جواب يعرفه المخاطبون ويقرون به عند الشدة. فصرح به لإقامة الحجة عليهم من اعترافهم، قبل توبيخهم على عودتهم إلى الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص64، تحت «فصل جملة: ﴿قل الله ينجيكم منها﴾ لجريانها مجرى القول في المحاورة»","url":""}]},{"id":"s6-463","number":463,"surah":6,"verses":[64],"references":[{"surah":6,"verses":[64]}],"verseLabel":"الأنعام: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿منها ومن كل كرب﴾، فعطف العام على الخاص؟","answer":"عطف ﴿من كل كرب﴾ تعميم بعد تخصيص؛ فبعد إنجائهم من تلك الشدة يذكرهم بأن كل ضيق سواها لا يكشفه على الحقيقة إلا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص65، تحت «دلالة عطف شبه الجملة ﴿ومن كل كرب﴾ على الضمير في ﴿منها﴾»","url":""}]},{"id":"s6-464","number":464,"surah":6,"verses":[64],"references":[{"surah":6,"verses":[64]}],"verseLabel":"الأنعام: 64","question":"لماذا اختير لفظ ﴿كرب﴾ بعد ظلمات البر والبحر؟","answer":"الكرب هو الغم الشديد الذي يضيق به الصدر كأنه يعقد النفس؛ فناسب ظلمات البر والبحر بما تثيره من خوف واختناق وحيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص68، تحت «الكرب والحزن»","url":""}]},{"id":"s6-465","number":465,"surah":6,"verses":[64],"references":[{"surah":6,"verses":[64]}],"verseLabel":"الأنعام: 64","question":"لماذا أعقب النجاة بقوله: ﴿ثم أنتم تشركون﴾؟","answer":"﴿ثم﴾ للتراخي الرتبي والاستبعاد؛ فبعد اعترافهم بالله ووعدهم بالشكر كان المتوقع التوحيد، فجاء الشرك بعيدًا في القبح عن مقدمة النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص66، تحت «دلالة ﴿ثم﴾ في قوله: ﴿ثم أنتم تشركون﴾»","url":""}]},{"id":"s6-466","number":466,"surah":6,"verses":[64],"references":[{"surah":6,"verses":[64]}],"verseLabel":"الأنعام: 64","question":"لماذا أظهر الضمير ﴿أنتم﴾ في ﴿ثم أنتم تشركون﴾؟","answer":"إظهار ﴿أنتم﴾ يقوي نسبة الشرك إليهم ويعجب من فعلهم هم خاصة بعد أن دعوا الله وحده؛ فلا ينسب رجوعهم إلى غموض الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص66–67، تحت «تقديم المسند إليه على الخبر الفعلي في قوله تعالى: ﴿ثم أنتم تشركون﴾»","url":""}]},{"id":"s6-467","number":467,"surah":6,"verses":[65],"references":[{"surah":6,"verses":[65]}],"verseLabel":"الأنعام: 65","question":"ما سرّ التعبير في قوله تعالى: ﴿قل هو القادر﴾ بإظهار الضمير ﴿هو﴾؟","answer":"اجتمع تعريف المبتدأ ﴿هو﴾ والخبر ﴿القادر﴾ لإفادة الاختصاص في هذا المقام: هو وحده القادر على هذا العذاب، وأصنامهم لا تملك شيئًا منه. فالذي يملك النجاة يملك إنزال العذاب، فيجتمع الوعد والتهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص72–73، تحت «التعبير بأسلوب القصر على كمال قدرة الله»","url":""}]},{"id":"s6-468","number":468,"surah":6,"verses":[65],"references":[{"surah":6,"verses":[65]}],"verseLabel":"الأنعام: 65","question":"لم قدم ﴿عليكم﴾ على ﴿عذابًا﴾ في قوله: ﴿أن يبعث عليكم عذابًا﴾؟","answer":"للعناية بالمخاطبين والمسارعة إلى بيان أن العذاب متوجه إليهم هم. فيبرز التقديم موضع التهديد، ويجعل السامع يترقب نوع ما قد ينزل به قبل التصريح بالعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص73، تحت «تقديم شبه الجملة ﴿عليكم﴾ على مفعول الفعل الصريح ﴿عذابًا﴾»","url":""}]},{"id":"s6-469","number":469,"surah":6,"verses":[65],"references":[{"surah":6,"verses":[65]}],"verseLabel":"الأنعام: 65","question":"لماذا قُسّم العذاب إلى ﴿من فوقكم﴾ و﴿من تحت أرجلكم﴾؟","answer":"قسّم العذاب إلى ما يأتي من فوق وما ينبع من تحت لاستيعاب الجهات وإحاطة القدرة؛ فلا تحميهم سماء ولا أرض من أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص73، تحت «دلالة تصوير العذاب بأنه آتٍ من أعلى أو من أسفل».","url":""}]},{"id":"s6-470","number":470,"surah":6,"verses":[65],"references":[{"surah":6,"verses":[65]}],"verseLabel":"الأنعام: 65","question":"ما المعنى الكنائي الذي يحتمله ﴿من تحت أرجلكم﴾ في تصوير العذاب؟","answer":"يحمل على ما ينزل بهم من هوان ونكبات تأتيهم من جهة الأسفل، في مقابل عذاب يأتي من فوقهم. وتعدد الصورتين تهديد بأن عذاب الله متى نزل لم يكن لهم ملجأ يرده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص74، تحت «دلالة الكناية في قوله تعالى: ﴿أو من تحت أرجلكم﴾»","url":""}]},{"id":"s6-471","number":471,"surah":6,"verses":[65],"references":[{"surah":6,"verses":[65]}],"verseLabel":"الأنعام: 65","question":"لماذا عطف النوعين الأولين بـ﴿أو﴾ ثم قال: ﴿أو يلبسكم شيعًا﴾؟","answer":"تكرر ﴿أو﴾ لتقسيم صور العذاب الممكنة: عذاب من فوق، أو من تحت، أو تفريق داخلي؛ وكل واحد منها مقدور لله وقد يقع مستقلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص74، تحت «دلالة العطف بالحرف ﴿أو﴾ وأثرها في المعنى»","url":""}]},{"id":"s6-472","number":472,"surah":6,"verses":[65],"references":[{"surah":6,"verses":[65]}],"verseLabel":"الأنعام: 65","question":"لماذا عبّر عن تفريق الناس بقوله: ﴿يلبسكم شيعًا﴾؟","answer":"اللبس هو الخلط والإشكال؛ فـ﴿يلبسكم شيعًا﴾ يصور الجماعة الواحدة وقد خلطت فرقًا متنازعة لا يتميز لها طريق جامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص74–75، تحت «بلاغة التعبير بلفظ: ﴿يلبسكم﴾»","url":""}]},{"id":"s6-473","number":473,"surah":6,"verses":[65],"references":[{"surah":6,"verses":[65]}],"verseLabel":"الأنعام: 65","question":"لم اختير لفظ ﴿شيعًا﴾ بدل فرقًا في تصوير تفرقهم؟","answer":"الشيعة جماعة يتقوى بعض أفرادها ببعض ويشدون أزر بعضهم، وقد تتبع أهواء متعددة. فالتعبير يصور جماعات متكتلة متنازعة، لا مجرد انفصال أفراد؛ أما الفرقة فيغلب فيها معنى المفارقة والانفصال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص77، تحت «(شيعًا) و(فرقًا)»","url":""}]},{"id":"s6-474","number":474,"surah":6,"verses":[65],"references":[{"surah":6,"verses":[65]}],"verseLabel":"الأنعام: 65","question":"ما سرّ التعبير في قوله تعالى: ﴿ويذيق بعضكم بأس بعض﴾، فجعل الحرب ذوقًا؟","answer":"استعيرت الإذاقة للألم، وصُوّر التناوش والقتال بين الفرق كالمأكول الذي يذيقه بعضهم بعضًا؛ تهويلًا لأمر النزاع وتعظيمًا لألم الخصام والعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص75، تحت «بلاغة الاستعارة المكنية في قوله تعالى: ﴿ويذيق بعضكم بأس بعض﴾»","url":""}]},{"id":"s6-475","number":475,"surah":6,"verses":[65],"references":[{"surah":6,"verses":[65]}],"verseLabel":"الأنعام: 65","question":"لماذا كرر ﴿بعض﴾ في ﴿بعضكم بأس بعض﴾؟","answer":"كرر ﴿بعض﴾ لتعيين طرفي البأس: بعضٌ يذيق، وبعضٌ آخر يذوق بأسه؛ فصوّر تسليط طائفة على أخرى بالقتل والعذاب، وفي ذلك وعيد للمعتدين ووعد للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص75، تحت «بلاغة الاستعارة المكنية في قوله تعالى: ﴿ويذيق بعضكم بأس بعض﴾»","url":""}]},{"id":"s6-476","number":476,"surah":6,"verses":[65],"references":[{"surah":6,"verses":[65]}],"verseLabel":"الأنعام: 65","question":"لم أُمر بالنظر في ﴿انظر كيف نصرف الآيات﴾ مع أن آيات القرآن تُسمع؟","answer":"نُزل تنوع الدلائل المعقول منزلة المشهد المحسوس، فدعا إلى تأمله كأنه يراه. والمراد التنبيه والتعجيب من عرض الحجة بوجوه من الترغيب والترهيب، ليصل المتأمل إلى الفهم والرجوع إلى الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص75–76، تحت «تنزيل المعقول منزلة المحسوس في النظر إلى تصريف الآيات»","url":""}]},{"id":"s6-477","number":477,"surah":6,"verses":[65],"references":[{"surah":6,"verses":[65]}],"verseLabel":"الأنعام: 65","question":"لم ختم تصريف الآيات بـ﴿لعلهم يفقهون﴾ بدل يعلمون؟","answer":"الفقه أخص من مطلق العلم؛ فهو فهم مقتضى الكلام عن تأمل. فالمقصود أن يتجاوزوا سماع الآيات إلى النظر في دلائلها والوصول إلى الحق والتزامه، وهو ما يناسب تنويع البيان وتصريف الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص78–79، تحت «(يفقهون) و(يعلمون)»","url":""}]},{"id":"s6-478","number":478,"surah":6,"verses":[66],"references":[{"surah":6,"verses":[66]}],"verseLabel":"الأنعام: 66","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذب به قومك﴾، وإلى ماذا يعود الضمير في ﴿به﴾؟","answer":"يحتمل الضمير العذاب الموعود في الآيات السابقة، ويحتمل القرآن المتضمن خبره وسائر العقيدة والشريعة؛ والمعنيان متلازمان، إذ كذبوا بالكتاب وبوعيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص81، تحت «عودة الضميرين في قوله تعالى: ﴿وكذب به قومك﴾ وأثرهما في المعنى».","url":""}]},{"id":"s6-479","number":479,"surah":6,"verses":[66],"references":[{"surah":6,"verses":[66]}],"verseLabel":"الأنعام: 66","question":"ما أثر عطف المباني في تعانق معاني الآيات المتوالية؟","answer":"وصل العطف بين دلائل القدرة وموقف المكذبين وما يترتب عليه، فجعل المعاني المتتابعة بناءً واحدًا تتساند أجزاؤه في إقامة الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص81، تحت عنوان «تعانق المعاني بعطف المباني في الآيات المتوالية»","url":""}]},{"id":"s6-1193","number":1193,"surah":6,"verses":[66],"references":[{"surah":6,"verses":[66]}],"verseLabel":"الأنعام: 66","question":"إلى ماذا يعود الضميران في قوله تعالى: ﴿وكذب به قومك﴾، وما أثر ذلك؟","answer":"يعود ضمير ﴿به﴾ إلى القرآن أو الحق المعلوم من السياق، وضمير الخطاب في ﴿قومك﴾ إلى النبي ﷺ؛ وفي الإضافة تشنيع لتكذيب من عرفوا صدقه وقربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص81–82، تحت عنوان «عودة الضميرين في قوله تعالى: ﴿وكذب به قومك﴾، وأثرهما في المعنى»","url":""}]},{"id":"s6-480","number":480,"surah":6,"verses":[66],"references":[{"surah":6,"verses":[66]}],"verseLabel":"الأنعام: 66","question":"لماذا اعترض بقوله: ﴿وهو الحق﴾ بين التكذيب والأمر بالجواب؟","answer":"جملة ﴿وهو الحق﴾ اعتراض يثبت حقيقة ما كذبوا به ويعجل بيانها؛ فالتكذيب لا يغير ثبوته، بل يضاعف قبح فعلهم لأنهم قابلوا الحق المبين بالإنكار.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص82، تحت «بلاغة الاعتراض بقوله تعالى: ﴿وهو الحق﴾».","url":""}]},{"id":"s6-481","number":481,"surah":6,"verses":[66],"references":[{"surah":6,"verses":[66]}],"verseLabel":"الأنعام: 66","question":"ما سرّ التعبير في قوله تعالى: ﴿لست عليكم بوكيل﴾، دون أن يقال: لست وكيلكم؟","answer":"تدل ﴿عليكم﴾ على معنى الاستعلاء والسلطان المنفي عنه هنا؛ فليس قيّمًا يجبرهم على الإيمان أو يمنعهم من التكذيب. وإبرازها في التركيب يوجه النفي إلى هذا التسلط، مع بقاء وظيفته في البلاغ والإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص82–83، تحت «أثر أسلوب الأمر في ثراء المعنى وبيانه»","url":""}]},{"id":"s6-482","number":482,"surah":6,"verses":[66],"references":[{"surah":6,"verses":[66]}],"verseLabel":"الأنعام: 66","question":"لماذا دخلت الباء على ﴿وكيل﴾؟","answer":"تؤكد الباء نفي ملابسة صفة الوكيل له في هذا المقام؛ فكأن المعنى: لست متعلقًا بكم تعلق من يتولى أعمالكم وحسابكم. ويشرح المصدر هذا من أصل معنى الإلصاق في الباء، مع تقرير أن عليه البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص82–83، تحت «أثر أسلوب الأمر في ثراء المعنى وبيانه»","url":""}]},{"id":"s6-483","number":483,"surah":6,"verses":[67],"references":[{"surah":6,"verses":[67]}],"verseLabel":"الأنعام: 67","question":"ما سرّ التعبير في قوله تعالى: ﴿لكل نبإ مستقر﴾، دون أن يقال: لكل خبر؟","answer":"النبأ خبر عظيم له شأن ونتيجة، وهو أنسب بالوعيد والوحي من مطلق الخبر؛ فلكل نبأ إلهي وقت يظهر فيه صدقه ويقع مضمونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص85، تحت «ما ورد من توجيه لغوي في قوله تعالى: ﴿لكل نبإ مستقر﴾».","url":""}]},{"id":"s6-484","number":484,"surah":6,"verses":[67],"references":[{"surah":6,"verses":[67]}],"verseLabel":"الأنعام: 67","question":"لم قدم ﴿لكل نبإ﴾ على ﴿مستقر﴾؟","answer":"للعناية بالنبأ وتأكيد أن لكل خبر من أخبار الوحي حقيقة وغاية ينتهي إليها. فالتقديم يربط كل نبأ بتحققه، ويطمئن إلى أن تأخر وقوع الوعيد لا يبطله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص85، تحت «ما ورد من توجيه لغوي في قوله تعالى: ﴿لكل نبإ مستقر﴾»","url":""}]},{"id":"s6-485","number":485,"surah":6,"verses":[67],"references":[{"surah":6,"verses":[67]}],"verseLabel":"الأنعام: 67","question":"ما التوجيه اللغوي لقوله تعالى: ﴿لكل نبإ مستقر﴾؟","answer":"مستقر النبأ وقت تحقق مضمونه أو غايته التي ينتهي إليها؛ فصوّر الخبر كأنه يسير إلى موضع يستقر فيه صدقه واقعًا مشهودًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص85، تحت عنوان «ما ورد من توجيه لغوي في قوله تعالى: ﴿لكل نبإ مستقر﴾»","url":""}]},{"id":"s6-486","number":486,"surah":6,"verses":[67],"references":[{"surah":6,"verses":[67]}],"verseLabel":"الأنعام: 67","question":"لماذا خُتم الوعيد بقوله: ﴿وسوف تعلمون﴾، ولم يذكر ما سيعلمونه؟","answer":"يدل المقام على ما سيعلمونه: صدق ما أخبرهم به الوحي ووقوع ما وُعدوا به من الجزاء. فالمقصود تهديدهم بأن ما ينكرونه الآن سيصير علمًا يشهدونه، وأن وعيد الله واقع لا يتخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص86، تحت «دلالة ﴿وسوف﴾ في الجملة المعطوفة»","url":""}]},{"id":"s6-487","number":487,"surah":6,"verses":[67],"references":[{"surah":6,"verses":[67]}],"verseLabel":"الأنعام: 67","question":"ما دلالة الاستقبال في ﴿وسوف تعلمون﴾ بعد ﴿لكل نبإ مستقر﴾؟","answer":"يدل على تحقق العلم في وقت آت، ولا يحدد بنفسه مقدار الزمن. فهو يمهل وقوع المشهد إلى مستقره المقدر مع توكيد الوعيد؛ فلا يجعل التأخر دليلًا على عدم الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص86، تحت «دلالة ﴿وسوف﴾ في الجملة المعطوفة»","url":""}]},{"id":"s6-488","number":488,"surah":6,"verses":[68],"references":[{"surah":6,"verses":[68]}],"verseLabel":"الأنعام: 68","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذا رأيت الذين يخوضون في آياتنا﴾، فعبّر عن كلامهم بالخوض؟","answer":"الخوض أصله الدخول في الماء والاضطراب فيه بلا ثبات، فاستعير لحديثهم في الآيات بالباطل؛ يصورهم منغمسين في جدل مضطرب لا يقصد الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص90، تحت «دلالة الاستعارة في قوله تعالى: ﴿يخوضون في آياتنا﴾»","url":""}]},{"id":"s6-489","number":489,"surah":6,"verses":[68],"references":[{"surah":6,"verses":[68]}],"verseLabel":"الأنعام: 68","question":"ما دلالة الاستعارة في قوله تعالى: ﴿يخوضون في آياتنا﴾؟","answer":"استعير الخوض في الماء للدخول والتوغل في الحديث بالباطل؛ فصورهم منغمسين فيه من غير تثبت أو هدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص90، تحت عنوان «دلالة الاستعارة في قوله تعالى: ﴿يخوضون في آياتنا﴾»","url":""}]},{"id":"s6-490","number":490,"surah":6,"verses":[68],"references":[{"surah":6,"verses":[68]}],"verseLabel":"الأنعام: 68","question":"ما سرّ التعبير في قوله تعالى: ﴿فأعرض عنهم﴾، ولم يأمره بالرد عليهم؟","answer":"أُمر بالإعراض لأن مجلس الاستهزاء ليس مقام طلب حق ينفع معه الجدل؛ ومفارقته إنكار عملي يحفظ حرمة الآيات ولا يمنح باطلهم شرعية الإصغاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص88–89، تحت «دلالة الاسم الموصول في الجملة المعطوفة على الآيات السابقة»","url":""}]},{"id":"s6-491","number":491,"surah":6,"verses":[68],"references":[{"surah":6,"verses":[68]}],"verseLabel":"الأنعام: 68","question":"لماذا جعل غاية الإعراض: ﴿حتى يخوضوا في حديث غيره﴾؟","answer":"جعل الإعراض مؤقتًا بانتهاء الخوض ليبين أن المنهي عنه مجالستهم حال الاستهزاء لا مقاطعتهم مطلقًا؛ فإذا انتقلوا إلى حديث غيره زال سبب الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص90–91، تحت «دلالة ﴿حتى﴾ على الغاية في قوله تعالى: ﴿حتى يخوضوا في حديث غيره﴾»","url":""}]},{"id":"s6-492","number":492,"surah":6,"verses":[68],"references":[{"surah":6,"verses":[68]}],"verseLabel":"الأنعام: 68","question":"لماذا أعاد فعل ﴿يخوضوا﴾ مع الحديث الآخر؟","answer":"أعيد ﴿يخوضوا﴾ لأن الخوض وصف عادتهم في الكلام، ولو انتقل متعلقه؛ لكن الممنوع هنا خوضهم في آيات الله خاصة، فيزول المنع بتغير الحديث.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص90–91، تحت «دلالة حتى على الغاية في حتى يخوضوا في حديث غيره»","url":""}]},{"id":"s6-493","number":493,"surah":6,"verses":[68],"references":[{"surah":6,"verses":[68]}],"verseLabel":"الأنعام: 68","question":"لماذا نُسب النسيان إلى الشيطان: ﴿وإما ينسينك الشيطان﴾؟","answer":"جاء إسناد الإنساء إلى الشيطان في سياق الشرط لزيادة تأكيد الأمر بالإعراض عند التذكر، مع بقاء النسيان عارضًا بشريًا لا مؤاخذة فيه، وقد عصم الله رسوله من وسوسة الشيطان في عمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص92، تحت «عطف حالة النسيان لتأكيد الأمر بالإعراض عن الخوض المذموم»","url":""}]},{"id":"s6-494","number":494,"surah":6,"verses":[68],"references":[{"surah":6,"verses":[68]}],"verseLabel":"الأنعام: 68","question":"ما أثر عطف حالة النسيان في تأكيد الأمر بالإعراض عن الخوض المذموم؟","answer":"بيّن أن النسيان عذر عارض فقط؛ فإذا وقع التذكر وجب ترك المجلس، فشمل الأمر حال القصد وحدد انتهاء العذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص92، تحت عنوان «عطف حالة النسيان لتأكيد الأمر بالإعراض عن الخوض المذموم»","url":""}]},{"id":"s6-1194","number":1194,"surah":6,"verses":[68],"references":[{"surah":6,"verses":[68]}],"verseLabel":"الأنعام: 68","question":"ما بلاغة وضع الاسم الظاهر موضع الضمير في قوله تعالى: ﴿مع القوم الظالمين﴾؟","answer":"صرح بوصف الظلم بدل أن يقال «معهم»؛ ليسجل علة النهي عن القعود معهم ويعم الحكم كل من اتصف بهذا الخوض.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص93، تحت عنوان «وضع المظهر موضع المضمر في قوله تعالى: ﴿مع القوم الظالمين﴾»","url":""}]},{"id":"s6-495","number":495,"surah":6,"verses":[68],"references":[{"surah":6,"verses":[68]}],"verseLabel":"الأنعام: 68","question":"لماذا أظهر وصفهم فقال: ﴿مع القوم الظالمين﴾، ولم يقل: معهم؟","answer":"أُظهر وصفهم فقيل ﴿مع القوم الظالمين﴾ بدل: معهم، لزيادة فائدة وصفهم بالظلم وبيان أن خوضهم في آيات الله ظلم، وأن النهي عن القعود معهم معلل بهذه الحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص93، تحت «وضع المظهر موضع المضمر، في قوله تعالى: ﴿مع القوم الظالمين﴾».","url":""}]},{"id":"s6-496","number":496,"surah":6,"verses":[69],"references":[{"surah":6,"verses":[69]}],"verseLabel":"الأنعام: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿وما على الذين يتقون من حسابهم من شيء﴾ بتكرار ﴿من﴾؟","answer":"تعلقت ﴿من حسابهم﴾ بالحساب المنفي عن المتقين، ثم زيدت ﴿من﴾ قبل ﴿شيء﴾ في سياق النفي لتأكيد الاستغراق؛ أي ليس عليهم أدنى شيء من حساب الخائضين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص98، تحت «السر في استغراق النفي والتنكير، في قوله: ﴿من شيء﴾».","url":""}]},{"id":"s6-497","number":497,"surah":6,"verses":[69],"references":[{"surah":6,"verses":[69]}],"verseLabel":"الأنعام: 69","question":"ما بلاغة الاستدراك في قوله تعالى: ﴿ولكن ذكرى﴾؟","answer":"بعد نفي تحمل المتقين شيئًا من حساب الخائضين، استدرك فأثبت عليهم التذكير والإنكار؛ فانتفاء المؤاخذة لا يعني ترك النصيحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص98، تحت عنوان «بلاغة الاستدراك في قوله: ﴿ولكن﴾»","url":""}]},{"id":"s6-1195","number":1195,"surah":6,"verses":[69],"references":[{"surah":6,"verses":[69]}],"verseLabel":"الأنعام: 69","question":"ما أثر احتمال الحالية والعطف في لفظ ﴿ذكرى﴾؟","answer":"على الحالية يكون المعنى الإعراض حال كون المقصود تذكيرهم، وعلى العطف يثبت واجب الذكرى بعد نفي الحساب؛ والوجهان يجمعان الإنكار مع المفارقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص99، تحت عنوان «لفظ ﴿ذكرى﴾ بين الحالية والعطف، وأثره في المعنى»","url":""}]},{"id":"s6-498","number":498,"surah":6,"verses":[69],"references":[{"surah":6,"verses":[69]}],"verseLabel":"الأنعام: 69","question":"لماذا حُذف فعل الأمر أو الخبر قبل ﴿ذكرى﴾؟","answer":"﴿ذكرى﴾ مصدر ناب عن فعل محذوف، والتقدير: ولكن ذكّروهم ذكرى، أو: ولكن عليهم ذكرى. وحذفه أوجز وأجمع لمعنيي التذكير والاتعاظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص100، تحت «دلالة اختيار المصدر: ﴿ذكرى﴾».","url":""}]},{"id":"s6-499","number":499,"surah":6,"verses":[69],"references":[{"surah":6,"verses":[69]}],"verseLabel":"الأنعام: 69","question":"ما بلاغة الاستئناف في قوله تعالى: ﴿لعلهم يتقون﴾؟","answer":"استأنف لبيان الغاية المرجوة من التذكير والإعراض، وهي أن يترك الخائضون باطلهم ويتقوا سببه وعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص100، تحت عنوان «بلاغة الاستئناف في قوله: ﴿لعلهم يتقون﴾»","url":""}]},{"id":"s6-1196","number":1196,"surah":6,"verses":[69],"references":[{"surah":6,"verses":[69]}],"verseLabel":"الأنعام: 69","question":"لماذا عُلّق الرجاء بالخائضين في قوله تعالى: ﴿لعلهم يتقون﴾؟","answer":"لأن تذكير المتقين وامتناعهم عن مجالستهم قد يردع الخائضين ويحملهم على ترك الخوض، فالضمير يوجه الرجاء إلى من يحتاج إلى التقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص100، تحت عنوان «علة تعليق الرجاء بالخائضين»","url":""}]},{"id":"s6-500","number":500,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما سرّ التعبير في قوله تعالى: ﴿وذر الذين اتخذوا دينهم لعبًا ولهوًا﴾، دون أن يقال: اتركهم؟","answer":"اختير ﴿ذر﴾ لما فيه من معنى الإعراض وعدم الاعتداد: دعهم ولا تبال بتكذيبهم واستهزائهم، ولا تشغل نفسك بلغوهم، مع الاستمرار في تذكيرهم وبلاغهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص102، تحت «شرح المفردات»، مادة «﴿وذر﴾».","url":""}]},{"id":"s6-501","number":501,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"كيف اتخذ الخائضون دينهم لعبًا ولهوًا؟","answer":"عاملوا ما يجب تعظيمه بالسخرية والعبث، أو جعلوا أهواءهم وعاداتهم التي يلهون بها بمنزلة الدين، فلم يحملهم على جد أو عمل للآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص108–109، تحت عنوان «كيفية اتخاذ الخائضين الدين لعبًا ولهوًا»","url":""}]},{"id":"s6-1197","number":1197,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما سر التعبير عن الكفر باتخاذ الدين لعبًا ولهوًا؟","answer":"كشف التعبير أن كفرهم لم يكن بحثًا جادًا عن الحق، بل تحويلًا للدين عن غايته إلى العبث والانشغال بما يصد عن الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص109، تحت عنوان «سر التعبير عن الكفر باتخاذ الدين لعبًا ولهوًا»","url":""}]},{"id":"s6-502","number":502,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما سرّ تقديم ﴿اللعب﴾ على ﴿اللهو﴾ كما في الآية 32؟","answer":"قُدّم ﴿اللعب﴾ على ﴿اللهو﴾ هنا وفي نظائره مراعاةً للترتيب الزمني؛ لأن زمن اللعب ـ وهو الصبا ـ يسبق زمن اللهو ـ وهو الشباب ـ فجاء اللفظ على ترتيب الأصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص126، تحت «بلاغة التشابه اللفظي».","url":""}]},{"id":"s6-503","number":503,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما سرّ التعبير في قوله تعالى: ﴿وغرتهم الحياة الدنيا﴾، فجعل الحياة نفسها غارّة؟","answer":"أُسند الغرور إلى الحياة الدنيا على سبيل المجاز العقلي؛ لأنها بلذاتها وشهواتها كانت سبب اغترارهم بها حتى اطمأنوا إليها وظنوا ألا حياة بعدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص111، تحت «نكتة المجاز في إسناد الغرور إلى الحياة الدنيا».","url":""}]},{"id":"s6-504","number":504,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"لماذا أعقب الأمر بتركهم بقوله: ﴿وذكر به﴾؟","answer":"ترك مجالس المستهزئين لا يعني ترك دعوتهم؛ لذلك عطف ﴿وذكر به﴾ ليجمع بين الإعراض عن عبثهم ومواصلة إنذارهم بالقرآن، فلا تتحول المفاصلة إلى إهمال للبلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص113، تحت «فائدة الأمر بالتذكير، بعد الأمر بترك الخائضين».","url":""}]},{"id":"s6-505","number":505,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"إلى ماذا يعود الضمير في ﴿وذكر به﴾؟","answer":"الضمير في ﴿به﴾ يعود إلى القرآن، دل عليه السياق وإن لم يسبق له ذكر صريح؛ فهو أداة التذكير بالبعث والنعيم والعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص112، تحت «نكتة الإضمار في محل الإظهار، في قوله: ﴿وذكر به﴾».","url":""}]},{"id":"s6-506","number":506,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما سر بناء ﴿أبسلوا﴾ للمجهول؟","answer":"ركز البناء للمجهول على وقوع الإبسال بالنفوس وسوء مصيرها، مع العلم بأن الله هو الذي يسلمها للعذاب جزاء بما كسبت.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص120، تحت عنوان «السر في بناء ﴿أبسلوا﴾ للمجهول»","url":""}]},{"id":"s6-507","number":507,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"لماذا نُكرت ﴿نفس﴾؟","answer":"نُكرت ﴿نفس﴾ للعموم؛ أي لئلا تسلم أي نفس إلى الهلاك بما كسبت، مهما كان صاحبها، فالمسؤولية فردية شاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص114، تحت «إيثار التنكير في قوله: ﴿نفس﴾».","url":""}]},{"id":"s6-508","number":508,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما دلالة الباء في قوله تعالى: ﴿بما كسبوا﴾؟","answer":"هي للسببية؛ فإبسالهم وعذابهم ناشئان عن أعمالهم التي اكتسبوها باختيارهم، لا عن ظلم وقع عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص121، تحت عنوان «دلالة الباء في قوله: ﴿بما كسبوا﴾»","url":""}]},{"id":"s6-1198","number":1198,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما فائدة التعبير بـ﴿ما﴾ في قوله تعالى: ﴿بما كسبوا﴾؟","answer":"أبهم الموصول جنس ما كسبوه ليعم أعمالهم الباطلة كلها، ويجعل الجزاء متعلقًا بكل ما دخل في هذا الكسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص121، تحت عنوان «فائدة التعبير بـ﴿بما﴾»","url":""}]},{"id":"s6-1199","number":1199,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما الفرق بين الكسب والفعل؟","answer":"الفعل أعم في مجرد وقوع الحدث، أما الكسب فيلحظ قصد الفاعل وتحصيله أثرًا لنفسه؛ لذلك ناسب مقام تحميل الإنسان تبعة عمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص127–128، تحت عنوان «الفروق المعجمية: (الكسب) و(الفعل)»","url":""}]},{"id":"s6-509","number":509,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"لماذا جمع بين نفي ﴿ولي﴾ و﴿شفيع﴾؟","answer":"نُفيا معًا لإبطال ما توهمه المشركون من النصرة: فالولي ناصر مقيد بالقرب أو رابطة، وهو أخص، والشفيع ناصر مطلق قريبًا كان أو أجنبيًا، وهو أعم؛ فنفيهما يقطع تعلقهم بالأولياء والشفعاء من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص116، تحت «غرض تقديم ﴿ولي﴾ على ﴿شفيع﴾».","url":""}]},{"id":"s6-510","number":510,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما الغرض من تأكيد الفداء في قوله تعالى: ﴿وإن تعدل كل عدل لا يؤخذ منها﴾؟","answer":"بالغ في نفي النجاة بالفدية، فحتى لو بذلت النفس كل ما يمكن أن يعادلها لم يقبل منها؛ وبذلك انقطعت وسيلة النجاة المتوهمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص117، تحت عنوان «الغرض من تأكيد الفداء»","url":""}]},{"id":"s6-1200","number":1200,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما دلالة تنكير ﴿عدل﴾ في قوله تعالى: ﴿وإن تعدل كل عدل﴾؟","answer":"أفاد العموم والتعظيم، أي أيَّ فداء مهما عظم وكثر؛ فلا يخرج من النفي بدل يمكن أن يتوهم قبوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص118، تحت عنوان «إيثار التعبير بالنكرة في لفظ ﴿عدل﴾»","url":""}]},{"id":"s6-1201","number":1201,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما الفرق بين العدل والفداء؟","answer":"العدل هو البدل المكافئ للشيء، والفداء ما يبذل لتخليص النفس؛ فسمي الفداء عدلًا بالنظر إلى كونه معادلًا للمفدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص127، تحت عنوان «الفروق المعجمية: (العدل) و(الفداء)»","url":""}]},{"id":"s6-511","number":511,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"لماذا أسند الأخذ إلى المجهول: ﴿لا يؤخذ منها﴾؟","answer":"بُني ﴿لا يؤخذ﴾ للمجهول لأن المقصود نفي قبول الفداء نفسه والاهتمام بعدم أخذه، لا بيان من يأخذه؛ فلا فداء يُقبل منها بحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص119، تحت «دلالة المبني للمجهول في قوله: ﴿لا يؤخذ منها﴾».","url":""}]},{"id":"s6-512","number":512,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"لماذا كرر: ﴿أولئك الذين أبسلوا بما كسبوا﴾ بعد التحذير من أن تبسل نفس؟","answer":"الأول تحذير عام من الإبسال، ثم جاء ﴿أولئك﴾ لتعيين الذين وقع عليهم الوعيد وتقرير سببه: هم الذين سلموا للهلاك بكسبهم، لا بظلم من غيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص119، تحت «الغرض من الاستئناف في ﴿أولئك الذين﴾».","url":""}]},{"id":"s6-513","number":513,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"لماذا اختير لهم ﴿شراب من حميم﴾ في مقابلة ما كسبوا؟","answer":"خُص شراب الحميم لأنهم يعطشون فلا يجدون إلا ماء بالغ الحرارة يزيدهم حرارةً على حرارة العطش، فصار الشراب نفسه وجهًا من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص122، تحت «العلة بتخصيص ذكر الشراب».","url":""}]},{"id":"s6-514","number":514,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"لماذا وصف العذاب بـ﴿أليم﴾، مع أن الألم مفهوم من العذاب؟","answer":"وصف العذاب بالأليم لتوكيد بلوغ الألم وتمييزه بأنه عذاب يباشر إحساسهم، لا مجرد حرمان أو تهديد؛ فاجتمع شراب الحميم وسائر الألم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص123، تحت «إيثار التعبير عن المفعول بالصفة المشبهة».","url":""}]},{"id":"s6-515","number":515,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"لماذا فُرّق بين سبب الإبسال وسبب العذاب الأليم؟","answer":"نسب الإبسال إلى ما كسبوا ليشمل أعمالهم، ثم نسب العذاب إلى كفرهم لأنه أصل تلك الأعمال وأشد أسباب العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص124، تحت عنوان «علة التفريق بين سبب الإبسال، وسبب العذاب الأليم»","url":""}]},{"id":"s6-1202","number":1202,"surah":6,"verses":[70],"references":[{"surah":6,"verses":[70]}],"verseLabel":"الأنعام: 70","question":"ما سر جعل العذاب مسببًا على الكفر في قوله تعالى: ﴿بما كانوا يكفرون﴾؟","answer":"صرح بالكفر لأنه الجذر الذي أفسد أعمالهم وأبقاهم على الإعراض، فناسب أن يذكر علة للعذاب الأليم خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص124، تحت عنوان «السر في جعل العذاب مسببًا على الكفر»","url":""}]},{"id":"s6-516","number":516,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما الغرض المجازي من الاستفهام في قوله تعالى: ﴿قل أندعوا من دون الله﴾؟","answer":"خرج الاستفهام إلى الإنكار؛ فيرفض عبادة ما لا يملك نفعًا ولا ضرًا، ويلزم المخاطبين بالإقرار بفسادها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص133، تحت عنوان «الغرض المجازي من الاستفهام في ﴿قل أندعوا﴾»","url":""}]},{"id":"s6-1203","number":1203,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما بلاغة التعبير بالدعاء عن العبادة في قوله تعالى: ﴿أندعوا من دون الله﴾؟","answer":"أطلق الدعاء وأريدت العبادة لأنه أبرز مظاهر الافتقار والتوجه إلى المعبود؛ فدل الجزء الظاهر على حقيقة العبادة كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص133، تحت عنوان «بلاغة التعبير بالدعاء عن العبادة»","url":""}]},{"id":"s6-517","number":517,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما سرّ تقديم نفي النفع على نفي الضر؟","answer":"قُدّم نفي النفع لأنه أجلب لترك عبادتهم؛ إذ الداعي إنما يدعو معبوده طلبًا للنفع لا للضر، ولأن سياق السورة في تعداد النعم، فبدأ بما يلائم السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص135، تحت «علة تقديم ذكر النفع على الضر».","url":""}]},{"id":"s6-518","number":518,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿ونرد على أعقابنا﴾؟","answer":"صوّر ترك الإيمان برجوع السائر إلى الخلف بعد تقدمه؛ فجعل الارتداد انتكاسًا محسوسًا بعد سلوك طريق الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص137، تحت عنوان «بلاغة الاستعارة في قوله: ﴿ونرد على أعقابنا﴾»","url":""}]},{"id":"s6-1204","number":1204,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"لماذا أوثر التعبير عن الردة بقوله تعالى: ﴿ونرد على أعقابنا﴾؟","answer":"لأن الرجوع على الأعقاب يوحي بالانتكاس والخسران بعد التقدم، فيقبح الردة ولا يجعلها انتقالًا متكافئًا بين طريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص138، تحت عنوان «إيثار التعبير عن الردة بـ﴿ونرد على أعقابنا﴾»","url":""}]},{"id":"s6-519","number":519,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما الفرق بين الردة والرجوع؟","answer":"الرجوع أعم في العودة إلى ما كان عليه الإنسان، أما الردة فتغلب في الرجوع عن الإسلام إلى الكفر؛ لذلك تحمل في السياق معنى الانتكاس بعد الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص146، تحت عنوان «(الردة) و(الرجوع)»","url":""}]},{"id":"s6-520","number":520,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما دلالة قوله تعالى: ﴿بعد إذ هدانا الله﴾ في إنكار الرجوع إلى الشرك؟","answer":"ذكر الهداية يؤكد نفي الارتداد وإنكاره؛ أي كيف نعود إلى الشرك بعد أن أنقذنا الله منه ومنّ علينا بالإيمان؟ فهو تشنيع للرجوع إلى الكفر بعد نعمة الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص139، تحت «تأكيد إنكار الارتداد بذكر الهداية»","url":""}]},{"id":"s6-521","number":521,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"لماذا أظهر اسم الله في ﴿هدانا الله﴾؟","answer":"أظهر اسم الجلالة ليعظم نعمة الهدى ويبين مصدرها وحده؛ فالارتداد ليس ترك رأي بشري، بل رد لهداية تفضل الله بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص139، تحت «دلالة إسناد الهداية لله تعالى».","url":""}]},{"id":"s6-522","number":522,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"لماذا شُبّه المرتد بـ﴿الذي استهوته الشياطين في الأرض حيران﴾؟","answer":"شُبّه المرتد برجل أضلته الشياطين في فلاة فبقي حيران لا يهتدي، وترك رفاقه على الطريق المستقيم يدعونه إلى الرجوع فلا يستجيب؛ فالصورة تجسّد ضياع المرتد مع قيام داعي الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص139، تحت «بلاغة التشبيه التمثيلي».","url":""}]},{"id":"s6-523","number":523,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما وجه تأنيث الفعل في قوله تعالى: ﴿استهوته الشياطين﴾ مع جمع ﴿الشياطين﴾؟","answer":"جاء التأنيث مراعاةً لمعنى جماعة الشياطين؛ فجمع التكسير يجوز أن يراعى فيه معنى الجماعة، فيؤنث فعله. ووردت قراءة بالتذكير مراعاةً للفظ الجمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص140، تحت «توجيه القراءات القرآنية في استهوته»","url":""}]},{"id":"s6-524","number":524,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما دلالة صيغة الاستفعال في قوله تعالى: ﴿استهوته الشياطين﴾؟","answer":"تصور الصيغة طلب الشياطين سقوطه وحرصها عليه حتى أوقعته في الضلال، فزادت معنى السعي والاستدراج على مجرد الإضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص139–140، تحت عنوان «دلالة صيغة الاستفعال في الفعل ﴿استهوته﴾»","url":""}]},{"id":"s6-525","number":525,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"لماذا قُيّد الحيران بقوله: ﴿في الأرض﴾؟","answer":"قُيّد الحيران بقوله ﴿في الأرض﴾ لتكتمل صورة التائه الضال عن الجادة في فلاة، لا يهتدي إلى مخرج ولا يعرف كيف يسلك وأين يذهب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص129، 131، تحت «شرح المفردات»، مادة «﴿حيران﴾».","url":""}]},{"id":"s6-526","number":526,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما بلاغة التشبيه التمثيلي في تصوير من استهوته الشياطين في الأرض؟","answer":"شُبه من ترك الهدى بعد معرفته بحائر أضلته الشياطين في فلاة، وأصحابه على الطريق يدعونه؛ فصورت الهيئة اضطرابه وبعده عن النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص139، تحت عنوان «بلاغة التشبيه التمثيلي»","url":""}]},{"id":"s6-1205","number":1205,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما دلالة مجيء الصفة جملة فعلية مضارعية في قوله تعالى: ﴿له أصحاب يدعونه إلى الهدى﴾؟","answer":"المضارع يصور دعاء أصحابه متجددًا مستمرًا، فيبرز شدة حيرته إذ يبقى معرضًا مع وضوح النداء وتكرره.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص140، تحت عنوان «دلالة مجيء الصفة جملة فعلية مضارعية ﴿يدعونه﴾»","url":""}]},{"id":"s6-527","number":527,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما وجه الإيجاز في قوله تعالى: ﴿له أصحاب يدعونه إلى الهدى ائتنا﴾؟","answer":"حُذف فعل القول قبل ﴿ائتنا﴾ لدلالة ﴿يدعونه﴾ عليه؛ والتقدير: يقولون له ائتنا. فالأصحاب على الطريق المستقيم يدعونه أن يترك طريق الضلال ويعود إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص141، تحت «بلاغة الإيجاز بالحذف»","url":""}]},{"id":"s6-528","number":528,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿إن هدى الله هو الهدى﴾ بضمير الفصل وتعريف الطرفين؟","answer":"ضمير الفصل وتعريف الطرفين يفيدان القصر: هدى الله وحده هو الهدى الكامل الحقيقي، وما عداه استهواء وحيرة وإن سماه أصحابه هداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص142، تحت «اجتماع المؤكدات والقصر في قوله: ﴿إن هدى الله هو الهدى﴾».","url":""}]},{"id":"s6-529","number":529,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿وأمرنا لنسلم لرب العالمين﴾ باللام؟","answer":"اللام في ﴿لنسلم﴾ للتعليل وتعيين الغاية التي وقع الأمر لأجلها؛ أي أُمرنا بما أُمرنا به لننقاد ونستسلم بإخلاص لرب العالمين، بخلاف الباء التي تدل على مجرد وقوع الأمر بالإسلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص144، تحت «إيثار التعبير بـ(لنفعل) دون (بأن نفعل)».","url":""}]},{"id":"s6-530","number":530,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما دلالة اللام في قوله تعالى: ﴿لنسلم لرب العالمين﴾؟","answer":"تفيد التخصيص، أي نخلص الاستسلام لرب العالمين وحده، فلا نشرك معه من لا يملك نفعًا ولا ضرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص144، تحت عنوان «دلالة اللام على التخصيص في قوله: ﴿لرب العالمين﴾»","url":""}]},{"id":"s6-1206","number":1206,"surah":6,"verses":[71],"references":[{"surah":6,"verses":[71]}],"verseLabel":"الأنعام: 71","question":"ما بلاغة التعبير بالاسم الظاهر في قوله تعالى: ﴿لنسلم لرب العالمين﴾؟","answer":"أظهر وصف الربوبية موضع الضمير ليعلل الاستسلام؛ فمن يربي العالمين ويدبرهم هو وحده المستحق له.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص144، تحت عنوان «التعبير بالاسم الظاهر في ﴿لنسلم لرب العالمين﴾»","url":""}]},{"id":"s6-531","number":531,"surah":6,"verses":[72],"references":[{"surah":6,"verses":[72]}],"verseLabel":"الأنعام: 72","question":"لماذا خُصت الصلاة بالذكر بعد الأمر بالاستسلام لله؟","answer":"لأنها أعظم مظهر عملي للاستسلام وعمود العبادة، فخصت بالذكر تنويهًا بمكانتها بعد الأمر الجامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص150، تحت عنوان «العلة بتخصيص ذكر الصلاة»","url":""}]},{"id":"s6-532","number":532,"surah":6,"verses":[72],"references":[{"surah":6,"verses":[72]}],"verseLabel":"الأنعام: 72","question":"ما سرّ التعبير في قوله تعالى: ﴿أقيموا الصلاة﴾، دون أن يقال: صلوا؟","answer":"إقامة الصلاة أداؤها مستقيمة تامة بأوقاتها وأركانها وخشوعها والمداومة عليها؛ فهي أوسع من مجرد وقوع فعل الصلاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص151، تحت «السر بالتعبير عن الأمر بالصلاة بـ﴿أقيموا﴾».","url":""}]},{"id":"s6-533","number":533,"surah":6,"verses":[72],"references":[{"surah":6,"verses":[72]}],"verseLabel":"الأنعام: 72","question":"ما أثر عطف قوله تعالى: ﴿وأن أقيموا الصلاة واتقوه﴾ على الأمر بالاستسلام؟","answer":"فصل العطف مقتضيات الاستسلام: عبادة ظاهرة في إقامة الصلاة، وحال جامعة في التقوى؛ فبيّن العمل الذي يصدق الدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص149، تحت عنوان «بلاغة العطف بين الجمل وأثره في المعنى»","url":""}]},{"id":"s6-534","number":534,"surah":6,"verses":[72],"references":[{"surah":6,"verses":[72]}],"verseLabel":"الأنعام: 72","question":"ما سرّ الانتقال من ﴿وأمرنا لنسلم﴾ إلى خطاب ﴿وأن أقيموا الصلاة واتقوه﴾؟","answer":"انتقل الكلام من صيغة المتكلم إلى خطاب المواجهة تشريفًا بالقرب؛ فالاستسلام والإيمان قربٌ من الله، فناسبه خطاب الحاضر بالأمر بالصلاة والتقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص150، تحت «بلاغة الالتفات في سياق الآيات الكريمة»","url":""}]},{"id":"s6-535","number":535,"surah":6,"verses":[72],"references":[{"surah":6,"verses":[72]}],"verseLabel":"الأنعام: 72","question":"ما دلالة الواو في قوله تعالى: ﴿وهو الذي إليه تحشرون﴾؟","answer":"عطفت تقرير الحشر على أوامر الاستسلام والصلاة والتقوى، فربطت التكليف بالمآل الذي يقع فيه الحساب والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص151، تحت عنوان «دلالة الواو في قوله تعالى: ﴿وهو الذي إليه تحشرون﴾»","url":""}]},{"id":"s6-1207","number":1207,"surah":6,"verses":[72],"references":[{"surah":6,"verses":[72]}],"verseLabel":"الأنعام: 72","question":"لماذا جاء الحديث عن الحشر بعد جملة من الأوامر؟","answer":"ليذكر بأن امتثال الأوامر مرتبط بالرجوع إلى الله والجزاء عليها؛ فالحشر باعث على الطاعة وزاجر عن المخالفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص152، تحت عنوان «الحديث عن الحشر بعد جملة من الأوامر»","url":""}]},{"id":"s6-536","number":536,"surah":6,"verses":[72],"references":[{"surah":6,"verses":[72]}],"verseLabel":"الأنعام: 72","question":"ما سرّ تقديم ﴿إليه﴾ في ﴿إليه تحشرون﴾؟","answer":"قُدم ﴿إليه﴾ لقصر الحشر على الله وتأكيد الرجوع إلى حكمه وحده؛ فلا تنفع عنده الأرباب التي دُعيت من دونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص152، تحت «فائدة تقديم الجار والمجرور ﴿إليه﴾».","url":""}]},{"id":"s6-537","number":537,"surah":6,"verses":[72],"references":[{"surah":6,"verses":[72]}],"verseLabel":"الأنعام: 72","question":"لماذا بُني ﴿تحشرون﴾ للمجهول؟","answer":"بُني ﴿تحشرون﴾ للمفعول للاهتمام بالحشر نفسه وتعظيم شأنه، ولأن فاعله معلوم من سبق ذكر الله في قوله ﴿وهو الذي إليه﴾، فاستُغني عن تسميته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص153، تحت «الغرض من بناء الفعل ﴿تحشرون﴾ لما لم يسم فاعله».","url":""}]},{"id":"s6-538","number":538,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما بلاغة الباء في قوله تعالى: ﴿خلق السماوات والأرض بالحق﴾؟","answer":"تفيد الملابسة، أي خلقهما ملتبسين بالحكمة والغاية الثابتة، لا عبثًا ولا باطلًا؛ ومن هذا الحق البعث والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص157، تحت عنوان «بلاغة التعبير بالباء، في ﴿بالحق﴾»","url":""}]},{"id":"s6-1208","number":1208,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما أثر استئناف قوله تعالى: ﴿ويوم يقول كن فيكون﴾ بالواو؟","answer":"وصل مشهد الخلق الأول بمشهد الإيجاد يوم القيامة، فدل على أن القدرة التي أنشأت السماوات والأرض تنفذ أمر البعث كذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص158، تحت عنوان «الاستئناف بالواو في قوله تعالى: ﴿ويوم﴾»","url":""}]},{"id":"s6-539","number":539,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"لماذا انتقل من خلق السماوات والأرض إلى ﴿ويوم يقول كن فيكون﴾؟","answer":"انتقل من الخلق الأول المشاهد إلى يوم البعث ليدل بالأول على الثاني؛ فمن خلق السماوات والأرض بالحق ينشئ الخلق يوم القيامة بكلمة نافذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص158، تحت «الاستئناف بالواو في قوله تعالى: ﴿ويوم﴾».","url":""}]},{"id":"s6-540","number":540,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما متعلق ﴿يوم﴾ في قوله: ﴿ويوم يقول كن فيكون﴾؟","answer":"﴿يوم يقول﴾ ظرف متعلق بمحذوف وقع خبرًا مقدمًا، و﴿قوله الحق﴾ مبتدأ مؤخر؛ والتقدير: قوله الحق يوم يقول للشيء كن فيكون، فخُص ذلك اليوم لظهور نفاذ قوله فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص158–159، تحت «تقديم الظرف على المبتدأ».","url":""}]},{"id":"s6-541","number":541,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما بلاغة الخطاب بفعل الأمر ﴿كن﴾ في الخلق والإيجاد؟","answer":"مثل نفاذ الإرادة الإلهية بصورة أمر لا يتخلف عنه المأمور، فدل على كمال القدرة من غير معالجة أو آلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص159، تحت عنوان «بلاغة الخطاب بفعل الأمر ﴿كن﴾ في الخلق والإيجاد»","url":""}]},{"id":"s6-1209","number":1209,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما الغرض من ذكر جملة ﴿كن فيكون﴾؟","answer":"تقرر سرعة نفاذ مشيئة الله وسهولة الإيجاد عليه، وتحتج بالقدرة المطلقة على إمكان البعث بعد الموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص160، تحت عنوان «الغرض من ذكر جملة ﴿كن فيكون﴾»","url":""}]},{"id":"s6-542","number":542,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"لماذا جاء ﴿فيكون﴾ بالمضارع بعد الأمر ﴿كن﴾؟","answer":"جاء ﴿فيكون﴾ مرتبًا بالفاء على ﴿كن﴾ ليدل على أن التكوين يعقب الأمر التكويني من غير مهلة؛ فمتى قال للشيء كن وُجد، وفي السياق استحضار سرعة البعث والحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص160، تحت «دلالة الفاء في قوله: ﴿كن فيكون﴾».","url":""}]},{"id":"s6-543","number":543,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما دلالة صيغة القصر بتعريف الطرفين في قوله تعالى: ﴿قوله الحق﴾؟","answer":"تعريف المسند إليه والمسند يفيد أن قوله هو الحق الكامل الثابت، وينفي عنه الخلف والباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص161، تحت عنوان «دلالة صيغة القصر بتعريف الطرفين»","url":""}]},{"id":"s6-1210","number":1210,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما دلالة ﴿أل﴾ في لفظ ﴿الحق﴾ من قوله تعالى: ﴿قوله الحق﴾؟","answer":"تحتمل العهد الذهني للحق المعروف الكامل، أو الدلالة الكنائية على استغراق كماله؛ وفي الوجهين تعظم صدق قوله ونفاذه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص161، تحت عنوان «دلالة (أل) على العهد الذهني أو الكنائي في ﴿الحق﴾»","url":""}]},{"id":"s6-544","number":544,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿وله الملك يوم ينفخ في الصور﴾، أليس الملك له في كل يوم؟","answer":"الملك لله في كل وقت، لكن خُص يوم النفخ لأن ملكه يظهر يومئذ بلا دعوى ولا منازع، وتسقط أملاك الخلق وسلطاتهم التي توهموها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص162، تحت «السر بتخصيص الملك به يوم القيامة».","url":""}]},{"id":"s6-545","number":545,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"لماذا بُني ﴿ينفخ﴾ للمجهول؟","answer":"بُني ﴿ينفخ﴾ للمجهول لتوجيه العناية إلى النفخ وهوله وآثاره، ولأن النافخ معلوم من السنة وهو إسرافيل المأمور من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص163، تحت «إيثار التعبير بالفعل المبني للمفعول ﴿ينفخ﴾».","url":""}]},{"id":"s6-546","number":546,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما المراد بـ﴿الصور﴾، وما دلالة تعريفه في قوله تعالى: ﴿يوم ينفخ في الصور﴾؟","answer":"الصور هو القرن الذي ينفخ فيه إسرافيل بأمر الله. وتعريفه للعهد الذهني؛ إذ صار يوم النفخ فيه حاضرًا في الأذهان بما ورد من ذكره في الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص163، تحت «العهد الحضوري الذهني في لفظ الصور»","url":""}]},{"id":"s6-547","number":547,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"لماذا عُبر عن علم الله المطلق بقوله تعالى: ﴿عالم الغيب والشهادة﴾؟","answer":"جمع ما غاب عن الخلق وما شهدوه، فاستوعب طرفا المعلومات وأثبت إحاطة علم الله بكل موجود وحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص164، تحت عنوان «التعبير عن علمه تعالى المطلق بكونه عالم الغيب والشهادة»","url":""}]},{"id":"s6-1211","number":1211,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما دلالة الاستغراق في لفظي ﴿الغيب﴾ و﴿الشهادة﴾؟","answer":"استغرق التعريف كل غائب وكل مشهود، فدل مجموع اللفظين على أنه لا يخرج عن علم الله معلوم دق أو عظم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص165، تحت عنوان «دلالة الاستغراق في لفظي ﴿الغيب﴾ و﴿الشهادة﴾»","url":""}]},{"id":"s6-548","number":548,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما سر ذكر الغيب في قوله تعالى: ﴿عالم الغيب والشهادة﴾ مع أنه لا يغيب عن الله شيء؟","answer":"سمي غيبًا بالنظر إلى المخلوقين الذين يخفى عنهم، أما الله فلا يغيب عن علمه شيء؛ فالإضافة تراعي حال المخاطبين وتثبت كمال علمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص164، تحت عنوان «السر في ذكر الغيب، ولا غيب يغيب على الله تعالى»","url":""}]},{"id":"s6-549","number":549,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"لماذا خُتمت الآية بـ﴿وهو الحكيم الخبير﴾؟","answer":"هو ﴿الحكيم﴾ في خلقه وأمره وبعثه، يضع كل شيء موضعه، و﴿الخبير﴾ بدقائق الغيب والشهادة وعواقب الأمور؛ فالخاتمة تعلل ما سبق من الخلق والملك والعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص166، تحت «تخصيص ختام الآية بصفتي الحكيم والخبير دون سواهما».","url":""}]},{"id":"s6-550","number":550,"surah":6,"verses":[74],"references":[{"surah":6,"verses":[74]}],"verseLabel":"الأنعام: 74","question":"لماذا ذُكرت قصة إبراهيم هنا دون غيرها؟","answer":"لأنها تقيم حجة التوحيد بلسان أبي الأنبياء الذي ينتسب إليه مشركو العرب، وتصل إنكار الشرك في السياق بموقفه من الأصنام.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص170–171، تحت عنوان «وجه ذكر قصة إبراهيم دون غيره»","url":""}]},{"id":"s6-551","number":551,"surah":6,"verses":[74],"references":[{"surah":6,"verses":[74]}],"verseLabel":"الأنعام: 74","question":"لماذا ذُكر اسم الأب ﴿آزر﴾ هنا؟","answer":"ذُكر اسم ﴿آزر﴾ هنا لأن سورة الأنعام هي أول موضع في ترتيب المصحف يعرض دعوة إبراهيم لأبيه، فناسب تعريفه باسمه في أول ورود، ثم حُمِل حذف الاسم في المواضع الأخرى على هذا التعريف السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص174، تحت «سر انفراد موضع الأنعام بذكر ﴿آزر﴾ دون بقية المواضع».","url":""}]},{"id":"s6-552","number":552,"surah":6,"verses":[74],"references":[{"surah":6,"verses":[74]}],"verseLabel":"الأنعام: 74","question":"ما دلالة الاستفهام في قوله تعالى: ﴿أتتخذ أصنامًا آلهة﴾؟","answer":"هو للإنكار والتوبيخ؛ إذ يجعل المصنوع العاجز معبودًا، ويلزم المخاطب بمواجهة التناقض الظاهر في فعله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص175، تحت عنوان «دلالة الاستفهام في أتتخذ أصنامًا آلهة»","url":""}]},{"id":"s6-553","number":553,"surah":6,"verses":[74],"references":[{"surah":6,"verses":[74]}],"verseLabel":"الأنعام: 74","question":"ما سرّ البدء بإبطال عبادة الأصنام في قوله تعالى: ﴿أتتخذ أصنامًا آلهة﴾ قبل محاجة قومه في الكواكب؟","answer":"بدأ بالأصنام لأنها أوضح بطلانًا، ثم انتقل إلى الكواكب التي جعلوا الأصنام صورًا لها ووسائط إليها؛ فترقى في الحجة من الأجلى إلى الأخفى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص179، تحت «سر تقديم إبطال ألوهية الأصنام على ربوبية الكواكب»","url":""}]},{"id":"s6-554","number":554,"surah":6,"verses":[74],"references":[{"surah":6,"verses":[74]}],"verseLabel":"الأنعام: 74","question":"ما دلالة صيغة الافتعال في قوله تعالى: ﴿أتتخذ أصنامًا آلهة﴾؟","answer":"صيغة ﴿تتخذ﴾ تدل على التكلف والمبالغة في تحصيل الفعل؛ فكون الصنم مصنوعًا ينافي الألوهية، واتخاذه إلهًا عمل يتكلفه عابده ويصطنعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص176، تحت «سر التعبير بصيغة الافتعال الاتخاذ»","url":""}]},{"id":"s6-555","number":555,"surah":6,"verses":[74],"references":[{"surah":6,"verses":[74]}],"verseLabel":"الأنعام: 74","question":"لماذا بدأ إبراهيم بدعوة أبيه قبل دعوة قومه؟","answer":"بدأ بالأقرب الذي له حق الصلة والنصيحة، ثم انتقل منه إلى قومه؛ فجمع ترتيب الدعوة بحسب القرب مع عموم الإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص179، تحت عنوان «سر بدء إبراهيم بدعوة أبيه قبل دعوة قومه»","url":""}]},{"id":"s6-1212","number":1212,"surah":6,"verses":[74],"references":[{"surah":6,"verses":[74]}],"verseLabel":"الأنعام: 74","question":"ما دلالة عطف ﴿قومك﴾ على ضمير الخطاب في قوله تعالى: ﴿إني أراك وقومك في ضلال مبين﴾؟","answer":"أدخل قومه معه في الحكم نفسه، فانتقل من نصيحة الأب المخاطب إلى بيان ضلال الجماعة التي شاركته عبادة الأصنام.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص181، تحت عنوان «دلالة عطف القوم في ﴿وقومك﴾ على ضمير الخطاب»","url":""}]},{"id":"s6-556","number":556,"surah":6,"verses":[74],"references":[{"surah":6,"verses":[74]}],"verseLabel":"الأنعام: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿في ضلال﴾، فجعل الضلال كأنه مكان يحيط بهم؟","answer":"﴿في﴾ تصور الضلال كحيز أحاط بهم واستقروا داخله، فلا يرون خارجه طريق الحق؛ وهي أبلغ من مجرد وصفهم بأنهم ضالون.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص181، تحت «نوع الظرفية في قوله ﴿في ضلال مبين﴾».","url":""}]},{"id":"s6-557","number":557,"surah":6,"verses":[74],"references":[{"surah":6,"verses":[74]}],"verseLabel":"الأنعام: 74","question":"ما فائدة وصف الضلال بالمبين في قوله تعالى: ﴿في ضلال مبين﴾؟","answer":"أظهر أن بطلان عبادة المصنوعات واضح لا خفاء فيه، فزاد الوصف في تقبيح موقفهم وإقامة الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص182، تحت عنوان «فائدة وصف الضلال بالمبين»","url":""}]},{"id":"s6-1213","number":1213,"surah":6,"verses":[74],"references":[{"surah":6,"verses":[74]}],"verseLabel":"الأنعام: 74","question":"ما نكتة التعبير باسم الفاعل ﴿مبين﴾ في وصف الضلال؟","answer":"اسم الفاعل يثبت للضلال صفة الظهور والاستقرار، فكأنه بيّن في نفسه وكاشف عن فساد معتقد أصحابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص182، تحت عنوان «نكتة التعبير باسم الفاعل ﴿مبين﴾»","url":""}]},{"id":"s6-558","number":558,"surah":6,"verses":[75],"references":[{"surah":6,"verses":[75]}],"verseLabel":"الأنعام: 75","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذلك نري إبراهيم ملكوت السماوات والأرض﴾، لا: ملك السماوات والأرض؟","answer":"الملكوت صيغة تفيد سعة الملك وعظم السلطان ودقائقه، فرؤية إبراهيم لم تقف عند الأجرام بل نفذت إلى نظامها وتدبيرها ودلالتها على المالك الواحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص190، تحت «نكتة التعبير بالملكوت»","url":""}]},{"id":"s6-559","number":559,"surah":6,"verses":[75],"references":[{"surah":6,"verses":[75]}],"verseLabel":"الأنعام: 75","question":"لماذا عبّر بالمضارع ﴿نري﴾ مع أن الرؤية وقعت في الماضي؟","answer":"المضارع ﴿نري﴾ يحكي الرؤية الماضية في صورة حاضرة متجددة، ويستحضر تدرج إبراهيم في النظر كأن القارئ يشهده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص188–189، تحت «نكتة اختيار التعبير بالمضارع ﴿نري﴾»","url":""}]},{"id":"s6-560","number":560,"surah":6,"verses":[75],"references":[{"surah":6,"verses":[75]}],"verseLabel":"الأنعام: 75","question":"ما سرّ تقديم السماوات على الأرض في قوله تعالى: ﴿ملكوت السماوات والأرض﴾؟","answer":"قُدمت السماوات لما أودع الله فيها من الكواكب والنجوم والشمس والقمر وما تكشفه من عظمة الملكوت؛ أما الأرض فهي بالنسبة إلى ذلك الملكوت العظيم بعضُ ما تحويه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص191، تحت «سر إضافة ملكوت إلى السماوات قبل الأرض»","url":""}]},{"id":"s6-561","number":561,"surah":6,"verses":[75],"references":[{"surah":6,"verses":[75]}],"verseLabel":"الأنعام: 75","question":"ما سرّ التعبير في قوله تعالى: ﴿وليكون من الموقنين﴾، دون أن يقال: ليوقن؟","answer":"﴿من الموقنين﴾ يدل على ثباته في زمرة أهل اليقين ورسوخ الصفة فيه، وهو أبلغ من حصول فعل يقين في لحظة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص193، تحت «سر إيثار التعبير بـ﴿الموقنين﴾ دون (المهتدين)».","url":""}]},{"id":"s6-562","number":562,"surah":6,"verses":[75],"references":[{"surah":6,"verses":[75]}],"verseLabel":"الأنعام: 75","question":"لماذا جيء بواو قبل ﴿ليكون﴾؟","answer":"على أبرز الأوجه عطفت الواو علة مذكورة على علة محذوفة دل عليها السياق؛ أي أريناه الملكوت ليستدل به وليكون من الموقنين، وقيل إن الجملة مستأنفة، فالرؤية ذات غايات متصلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص191، تحت «دلالة الواو بين الاستئناف والعطف».","url":""}]},{"id":"s6-563","number":563,"surah":6,"verses":[76],"references":[{"surah":6,"verses":[76]}],"verseLabel":"الأنعام: 76","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما جن عليه الليل﴾، فعبّر عن إظلام الليل بالجنّ؟","answer":"﴿جن﴾ معناه ستر وغطى، فصوّر الليل غطاءً أطبق على إبراهيم وحجب ضوء النهار؛ ومن مادته الجن لاستتارهم والجَنين لخفائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص198، تحت «سر التعبير بالفعل ﴿جن﴾».","url":""}]},{"id":"s6-564","number":564,"surah":6,"verses":[76],"references":[{"surah":6,"verses":[76]}],"verseLabel":"الأنعام: 76","question":"لماذا عُدّي ﴿جن﴾ بـ﴿على﴾؟","answer":"عُدّي ﴿جن﴾ بـ﴿على﴾ لتصوير وقوع ستر الليل على إبراهيم وتغطيته له، حتى صارت الظلمة كغطاء محيط به؛ فالتعدية تقوي معنى الستر والإطباق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص198، تحت «دلالة حرف الجر (على) في قوله تعالى: ﴿فلما جن عليه الليل﴾».","url":""}]},{"id":"s6-565","number":565,"surah":6,"verses":[76],"references":[{"surah":6,"verses":[76]}],"verseLabel":"الأنعام: 76","question":"لماذا نُكّر ﴿كوكبًا﴾، ولم يعيّن اسمه؟","answer":"نُكر ﴿كوكبًا﴾ لأن المقصود جنس الكوكب وصفته في البزوغ والأفول، لا تعيين اسمه؛ فالحجة تصح في أي جرم من هذا النوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص199، تحت «نكتة تنكير ﴿كوكبًا﴾».","url":""}]},{"id":"s6-566","number":566,"surah":6,"verses":[76],"references":[{"surah":6,"verses":[76]}],"verseLabel":"الأنعام: 76","question":"ما دلالة تعريف طرفي الجملة في قوله تعالى: ﴿هذا ربي﴾؟","answer":"أفاد تعريف المسند والمسند إليه القصر، فجارى إبراهيم قومه في افتراض استحقاق الكوكب للربوبية تمهيدًا لإبطال قولهم من داخله، ولم يكن ذلك اعتقادًا منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص201، تحت عنوان «براعة القصر بتعريف الجزأين»","url":""}]},{"id":"s6-1214","number":1214,"surah":6,"verses":[76],"references":[{"surah":6,"verses":[76]}],"verseLabel":"الأنعام: 76","question":"هل جملة ﴿هذا ربي﴾ خبر أم استفهام، وما أثر الاحتمالين؟","answer":"تحتمل الخبر على سبيل التنزل مع الخصم، وتحتمل استفهام الإنكار؛ والوجهان يستدرجان القوم إلى النظر في فساد اعتقادهم من غير أن يثبتا شركًا لإبراهيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص201–202، تحت عنوان «جملة هذا ربي بين الخبر والاستفهام»","url":""}]},{"id":"s6-567","number":567,"surah":6,"verses":[76],"references":[{"surah":6,"verses":[76]}],"verseLabel":"الأنعام: 76","question":"ما وظيفة اسم الإشارة في قول إبراهيم عن الكوكب: ﴿هذا ربي﴾؟","answer":"يميّز اسم الإشارة الكوكب المعين من بين الكواكب، لينصبّ عليه الاحتجاج ومجاراة القوم في دعواهم؛ فالإشارة تعيّن ما اتخذوه معبودًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص201، تحت «نكتة تعريف المسند إليه بالإشارة»","url":""}]},{"id":"s6-568","number":568,"surah":6,"verses":[76],"references":[{"surah":6,"verses":[76]}],"verseLabel":"الأنعام: 76","question":"لماذا جعل أفول الكوكب هو الحجة على بطلان ربوبيته؟","answer":"الأفول انتقال وغياب وتغير، ومن كان محكومًا بالحركة والاحتجاب لا يصلح أن يكون ربًا مدبرًا دائمًا؛ فاتخذ الصفة المشاهدة حجة يفهمها قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص204، تحت «ترتيب النتائج على (الأفول) دون الطلوع أو الظهور».","url":""}]},{"id":"s6-569","number":569,"surah":6,"verses":[76],"references":[{"surah":6,"verses":[76]}],"verseLabel":"الأنعام: 76","question":"ما سرّ التعبير في قوله تعالى: ﴿لا أحب الآفلين﴾، دون أن يقال: ليس هذا ربي؟","answer":"﴿لا أحب الآفلين﴾ ينقل الحجة من نفي ربوبية جرم واحد إلى قاعدة عامة: المعبود لا يكون غائبًا متغيرًا. وفي نفي المحبة إعلان أن القلب لا يتعلق بما يزول.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص205، تحت «إيثار الكناية بنفي حب الآفلين».","url":""}]},{"id":"s6-570","number":570,"surah":6,"verses":[76],"references":[{"surah":6,"verses":[76]}],"verseLabel":"الأنعام: 76","question":"ما سرّ التعبير بـ﴿الآفلين﴾ بصيغة جمع العقلاء؟","answer":"جارى إبراهيم اعتقاد قومه أن الكواكب عاقلة متصرفة في الكون، فعبّر عنها بصيغة جمع العقلاء؛ ثم أبطل استحقاقها العبادة بما يلحقها من الأفول، وفي ذلك تهكم بدعواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص206، تحت «دلالة التعبير بالآفلين دون المصدر الأفول»","url":""}]},{"id":"s6-571","number":571,"surah":6,"verses":[77],"references":[{"surah":6,"verses":[77]}],"verseLabel":"الأنعام: 77","question":"لماذا وصف القمر بأنه ﴿بازغًا﴾، ولم يصف الكوكب بمثله؟","answer":"وُصف القمر بالبزوغ لأن طلوعه أوضح ونوره أعظم من الكوكب، فناسب إبراز ظهوره مرحلةً أقوى في الحجة؛ أما رؤية الكوكب فتكفي فيها تسميته من غير وصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص210، تحت «دلالة ذكر البزوغ مع القمر».","url":""}]},{"id":"s6-572","number":572,"surah":6,"verses":[77],"references":[{"surah":6,"verses":[77]}],"verseLabel":"الأنعام: 77","question":"ما دلالة تكرار قوله تعالى: ﴿قال هذا ربي﴾ في محاورة إبراهيم قومه؟","answer":"مثّل التكرار انتقال الحجة درجة بعد درجة من الكوكب إلى القمر ثم الشمس، مع مجاراة القوم حتى يظهر بطلان ربوبية كل جرم آفل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص211، تحت عنوان «دلالة تكرار قوله: ﴿قال هذا ربي﴾ في المحاورة»","url":""}]},{"id":"s6-1215","number":1215,"surah":6,"verses":[77],"references":[{"surah":6,"verses":[77]}],"verseLabel":"الأنعام: 77","question":"ما سر تكرار الفعل ﴿أفل﴾ في محاورة إبراهيم مع قومه؟","answer":"كرر الأفول لأنه العلة المشتركة التي تهدم دعوى الربوبية في الأجرام كلها؛ فما يغيب ويتغير لا يصلح إلهًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص211، تحت عنوان «سر تكرار الفعل ﴿أفل﴾ في محاورة إبراهيم مع قومه»","url":""}]},{"id":"s6-573","number":573,"surah":6,"verses":[77],"references":[{"surah":6,"verses":[77]}],"verseLabel":"الأنعام: 77","question":"لماذا انتقل بعد أفول القمر إلى الدعاء: ﴿لئن لم يهدني ربي﴾؟","answer":"بعد أفول القمر أظهر افتقاره إلى هداية ربه؛ لأن الهداية الحقيقية من الله، وعرّض بأن قومه في ضلال، تمهيدًا للتصريح ببراءته من عبادة الأجرام.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص212، تحت عنوان «بلاغة التعريض في ﴿لئن لم يهدني ربي﴾»","url":""}]},{"id":"s6-574","number":574,"surah":6,"verses":[77],"references":[{"surah":6,"verses":[77]}],"verseLabel":"الأنعام: 77","question":"لماذا أسند إبراهيم الهداية إلى الربوبية في قوله تعالى: ﴿لئن لم يهدني ربي﴾؟","answer":"لأن مقام الهداية والإنعام يلائمه وصف الرب الذي يربي عبده ويوصله إلى الحق، وفيه تعريض بأن هداية قومه لا تكون من أصنامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص214، تحت عنوان «دلالة إسناد الهداية إلى الربوبية دون الألوهية»","url":""}]},{"id":"s6-1216","number":1216,"surah":6,"verses":[77],"references":[{"surah":6,"verses":[77]}],"verseLabel":"الأنعام: 77","question":"ما فائدة إضافة لفظ ﴿ربي﴾ إلى ضمير المتكلم؟","answer":"أفادت الإضافة اختصاص إبراهيم بولاية ربه وعنايته وهدايته، وأظهرت صلته المباشرة بمن يطلب منه الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص214، تحت عنوان «فائدة الإضافة في لفظ ﴿ربي﴾»","url":""}]},{"id":"s6-575","number":575,"surah":6,"verses":[77],"references":[{"surah":6,"verses":[77]}],"verseLabel":"الأنعام: 77","question":"لماذا أكد الجواب باللام والنون: ﴿لأكونن من القوم الضالين﴾؟","answer":"اللام موطئة للقسم ونون التوكيد الثقيلة تثبت الجواب؛ فبيّن أن انتفاء هداية الله يفضي حتمًا إلى الضلال، لا إلى احتمال متردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص214، تحت «دلالة اللام والنون في ﴿لأكونن﴾».","url":""}]},{"id":"s6-576","number":576,"surah":6,"verses":[77],"references":[{"surah":6,"verses":[77]}],"verseLabel":"الأنعام: 77","question":"ما سرّ التعبير في قوله تعالى: ﴿من القوم الضالين﴾، دون أن يقال: ضالًا؟","answer":"﴿من القوم الضالين﴾ أبلغ من ﴿ضالًا﴾؛ لأنها تصور الدخول في جماعة استقر فيها الضلال، وتلمح إلى قومه الذين رأى طريقهم وعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص215، تحت «سر التعبير بنسق ﴿من القوم الضالين﴾».","url":""}]},{"id":"s6-577","number":577,"surah":6,"verses":[78],"references":[{"surah":6,"verses":[78]}],"verseLabel":"الأنعام: 78","question":"لماذا خُصّت الشمس بقوله: ﴿هذا أكبر﴾؟","answer":"الشمس أكبر الأجرام الثلاثة في الحس وأشدها ضوءًا، فخصها بذلك ليبلغ افتراض قومه أقصى قوته؛ فإذا أفل الأكبر بطل ما دونه من باب أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص220، تحت «سر التعبير بقوله: ﴿أكبر﴾ مع الشمس دون غيرها».","url":""}]},{"id":"s6-578","number":578,"surah":6,"verses":[78],"references":[{"surah":6,"verses":[78]}],"verseLabel":"الأنعام: 78","question":"ما سرّ التعبير في قوله تعالى عن الشمس المؤنثة: ﴿هذا ربي﴾ لا ﴿هذه﴾؟","answer":"ذُكر اسم الإشارة على معنى: هذا الجرم أو هذا الطالع ربي، وذُكرت تأويلات أخرى منها إرادة ضوء الشمس لا عينها؛ فالمراعاة للمعنى المقصود لا لتأنيث لفظ الشمس.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص218، تحت «نكتة تذكير اسم الإشارة في قوله تعالى: ﴿هذا ربي﴾».","url":""}]},{"id":"s6-579","number":579,"surah":6,"verses":[78],"references":[{"surah":6,"verses":[78]}],"verseLabel":"الأنعام: 78","question":"ما دلالة التعبير بالفعل الماضي في قوله تعالى عن الشمس: ﴿فلما أفلت﴾؟","answer":"يفيد الماضي تحقق الأفول ووقوعه؛ فلم يعلن إبراهيم البراءة من عبادتها إلا بعد أن غاب جرمها وذهب نورها، فصارت الحجة مشاهدة متحققة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص221، تحت «دلالة التعبير بالفعل الماضي أفلت»","url":""}]},{"id":"s6-580","number":580,"surah":6,"verses":[78],"references":[{"surah":6,"verses":[78]}],"verseLabel":"الأنعام: 78","question":"لماذا نادى قومه عند أفول الشمس: ﴿يا قوم﴾ ولم ينادهم في المرحلتين السابقتين؟","answer":"نادى قومه عند اكتمال التجربة وظهور النتيجة ليعلن الحكم العام أمامهم؛ أما المرحلتان السابقتان فكانتا تمهيدًا متدرجًا للمحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص221، تحت «بلاغة النداء في قوله تعالى: ﴿يا قوم﴾».","url":""}]},{"id":"s6-581","number":581,"surah":6,"verses":[78],"references":[{"surah":6,"verses":[78]}],"verseLabel":"الأنعام: 78","question":"ما سرّ التعبير في قوله تعالى: ﴿إني بريء مما تشركون﴾ بالاسم، لا: أتبرأ؟","answer":"الاسم ﴿بريء﴾ يدل على ثبوت البراءة واستقرارها، لا على فعل يتجدد مرة؛ فهو إعلان قاطع لانفصاله عن الشرك وأهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص222، تحت «دلالة التعبير بالاسمية في ﴿إني بريء﴾».","url":""}]},{"id":"s6-582","number":582,"surah":6,"verses":[78],"references":[{"surah":6,"verses":[78]}],"verseLabel":"الأنعام: 78","question":"ما سرّ التعبير في قوله تعالى: ﴿مما تشركون﴾، ولم يسم الشمس والقمر والكوكب؟","answer":"تحتمل «ما» الموصولية، فتعم الشمس والقمر والكوكب وسائر ما يشركون به، وتحتمل المصدرية، فيكون المعنى: إني بريء من إشراككم؛ فجمع التعبير البراءة من الشرك ومعبوداته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص223، تحت «دلالة (ما) في قوله تعالى: ﴿مما تشركون﴾».","url":""}]},{"id":"s6-583","number":583,"surah":6,"verses":[79],"references":[{"surah":6,"verses":[79]}],"verseLabel":"الأنعام: 79","question":"لماذا أوثر الفعل ﴿وجهت﴾ في قوله تعالى: ﴿إني وجهت وجهي﴾؟","answer":"يدل التوجيه على قصد جهة واحدة والإقبال عليها، فعبّر عن إخلاص الدين والعبادة لله والإعراض عما سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص228، تحت عنوان «دلالة إيثار التعبير بقوله: ﴿وجهت﴾ دون أملت»","url":""}]},{"id":"s6-1217","number":1217,"surah":6,"verses":[79],"references":[{"surah":6,"verses":[79]}],"verseLabel":"الأنعام: 79","question":"ما سر الكناية عن الطاعة بتوجيه الوجه؟","answer":"الوجه أشرف ما يظهر من الإنسان وبه تعرف وجهته، فتوجيهه كناية عن إقبال الذات كلها بالقصد والطاعة على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص229، تحت عنوان «سر الكناية عن الطاعة بتوجيه الوجه»","url":""}]},{"id":"s6-584","number":584,"surah":6,"verses":[79],"references":[{"surah":6,"verses":[79]}],"verseLabel":"الأنعام: 79","question":"لماذا أوثر لفظ ﴿وجهي﴾ دون قلبي في قوله تعالى: ﴿إني وجهت وجهي﴾؟","answer":"لأن الوجه مظهر الإقبال والجهة ويعبّر عن الذات الظاهرة والباطنة معًا، فدل على إخلاص الكيان كله لله، لا مجرد انفعال القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص229، تحت عنوان «دلالة إيثار ﴿وجهي﴾ دون (قلبي)»","url":""}]},{"id":"s6-585","number":585,"surah":6,"verses":[79],"references":[{"surah":6,"verses":[79]}],"verseLabel":"الأنعام: 79","question":"ما سر التعبير بالاسم الموصول ﴿الذي﴾ في وصف الله بأنه فطر السماوات والأرض؟","answer":"وصل اسم الجلالة بصفة الخلق التي يعرفونها، فجعلها علة ظاهرة لاستحقاقه وحده التوجه والعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص230، تحت عنوان «سر التعبير بالاسم الموصول ﴿الذي﴾»","url":""}]},{"id":"s6-1218","number":1218,"surah":6,"verses":[79],"references":[{"surah":6,"verses":[79]}],"verseLabel":"الأنعام: 79","question":"ما نكتة الكناية في قوله تعالى: ﴿فطر السماوات والأرض﴾؟","answer":"ذكر ابتداء خلق السماوات والأرض كناية عن كمال القدرة والوحدانية؛ فمن خلق الأجرام كلها لا يكون شيء منها ندًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص230، تحت عنوان «نكتة الكناية في قوله: ﴿فطر السماوات والأرض﴾»","url":""}]},{"id":"s6-586","number":586,"surah":6,"verses":[79],"references":[{"surah":6,"verses":[79]}],"verseLabel":"الأنعام: 79","question":"ما سرّ التعبير في قوله تعالى: ﴿حنيفًا﴾، وما الصورة التي تحملها مادة الحنف؟","answer":"الحنف ميل عن الاعوجاج إلى الاستقامة؛ فـ﴿حنيفًا﴾ يصور إبراهيم مائلًا عن الشرك كله، متجهًا بقصد واحد إلى التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص231–232، تحت «فائدة ذكر الحال ﴿حنيفًا﴾»؛ مع تتمة بيان معنى الحنيف في ص232.","url":""}]},{"id":"s6-587","number":587,"surah":6,"verses":[79],"references":[{"surah":6,"verses":[79]}],"verseLabel":"الأنعام: 79","question":"لماذا جاء ﴿حنيفًا﴾ مفردًا منصوبًا بعد ﴿وجهت وجهي﴾؟","answer":"﴿حنيفًا﴾ حال من فاعل ﴿وجهت﴾، فبين هيئة إبراهيم وقت توجيه وجهه؛ وجاء مفردًا لأنه وصف للمتكلم الواحد، ومنصوبًا لأنه حال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص231، تحت «فائدة ذكر الحال ﴿حنيفًا﴾».","url":""}]},{"id":"s6-588","number":588,"surah":6,"verses":[79],"references":[{"surah":6,"verses":[79]}],"verseLabel":"الأنعام: 79","question":"لماذا ذكرت البراءة من الشرك بعد توجيه الوجه لله تعالى؟","answer":"لأن إثبات الإخلاص لله يكتمل بنفي عبادة ما سواه، فجمع الكلام بين التوحيد الإيجابي والبراءة من الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص232، تحت عنوان «دلالة ذكر البراءة من الشرك بعد توجيه الوجه لله تعالى»","url":""}]},{"id":"s6-1219","number":1219,"surah":6,"verses":[79],"references":[{"surah":6,"verses":[79]}],"verseLabel":"الأنعام: 79","question":"ما أثر النفي على جهة الجمع في قوله تعالى: ﴿وما أنا من المشركين﴾؟","answer":"نفى دخوله في جنس المشركين نفيًا ثابتًا مستمرًا، وهو أبلغ من نفي فعل إشراك عارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص232، تحت عنوان «نكتة التعبير بالنفي على جهة الجمع في ﴿وما أنا من المشركين﴾»","url":""}]},{"id":"s6-589","number":589,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما دلالة اختيار مادة المحاجّة في قوله تعالى: ﴿وحاجه قومه﴾؟","answer":"المحاجة مقابلة الحجة بالحجة، فصورت قومه يخاصمونه بما يعدونه دليلًا ثم يرد عليهم ببرهان يكشف بطلانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص235–236، تحت عنوان «دلالة اختيار مادة المحاجّة»","url":""}]},{"id":"s6-1220","number":1220,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"لماذا أوثر التعبير بالمحاجّة دون المناظرة والمجادلة؟","answer":"لأن المحاجة أصرح في ادعاء كل فريق إقامة الحجة، فناسبت مقام إلزام القوم وإبطال شبهتهم، لا مجرد تبادل النظر أو الكلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص236–237، تحت عنوان «دلالة إيثار التعبير بالمحاجّة دون المناظرة والمجادلة»","url":""}]},{"id":"s6-590","number":590,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما سر التعبير بالهداية في قوله تعالى: ﴿وقد هدان﴾ جوابًا عن محاجة القوم؟","answer":"قابل إبراهيم جدلهم النظري بحقيقة هداية وقعت له وأوصلته إلى اليقين، فلا تزعزعها شبهتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص239، تحت عنوان «سر التعبير بالهداية في قوله ﴿هدان﴾»","url":""}]},{"id":"s6-1221","number":1221,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما دلالة تقييد المحاجة بالجملة الحالية ﴿وقد هدان﴾؟","answer":"بينت الحال أن محاجتهم وقعت بعد تحقق هدايته وثباتها، فزاد ذلك إنكار جدالهم وقطع طمعهم في رده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص239–240، تحت عنوان «دلالة التقييد بالجملة الحالية ﴿وقد هدان﴾»","url":""}]},{"id":"s6-591","number":591,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما دلالة الظرفية في قوله تعالى: ﴿أتحاجوني في الله﴾؟","answer":"جعلت الله متعلق المحاجة، فشملت ما جادلوا فيه من ربوبيته ووحدانيته واستحقاقه العبادة من غير حصر في جانب واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص238، تحت عنوان «دلالة الظرفية في قوله تعالى: ﴿أتحاجوني في الله﴾»","url":""}]},{"id":"s6-1222","number":1222,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"لماذا اختير اسم الجلالة ﴿الله﴾ دون لفظ الرب في مقام المحاجة؟","answer":"لأن اسم الجلالة جامع لمعاني الألوهية واستحقاق العبادة، وهو محور النزاع مع المشركين، فجاء أصرح في إلزامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص238–239، تحت عنوان «سر اختيار اسم الجلالة (الله) دون الرب»","url":""}]},{"id":"s6-592","number":592,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"لماذا عبّر بالماضي: ﴿وقد هدان﴾؟","answer":"الماضي مع ﴿قد﴾ يحقق وقوع الهداية وثبوتها؛ فهي نعمة حصلت واستقرت، فلا تزعزعها محاجة قومه ولا تخويفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص239، تحت عنوان «سر دخول (قد) على الفعل الماضي ﴿هدان﴾»","url":""}]},{"id":"s6-593","number":593,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما دلالة اختيار ﴿ما﴾ في قوله تعالى: ﴿ما تشركون به﴾؟","answer":"عم الموصول غير العاقل كل ما جعلوه شريكًا من أصنام وأجرام، وحقرها بعدم تسميتها آلهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص242، تحت عنوان «دلالة اختيار ﴿ما﴾ في قوله: ﴿ما تشركون﴾»","url":""}]},{"id":"s6-1223","number":1223,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما سر التعبير بلفظ الشرك عن عبادة الأصنام؟","answer":"كشف اللفظ حقيقة فعلهم: جعل مخلوق شريكًا لله في العبادة، فحكم على العبادة بالبطلان من أصل وصفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص242، تحت عنوان «سر التعبير بلفظ الشرك عن عبادتهم للأصنام»","url":""}]},{"id":"s6-594","number":594,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما سر الاستدراك بالاستثناء في قوله تعالى: ﴿إلا أن يشاء ربي شيئًا﴾؟","answer":"بعد نفي الخوف من شركائهم استثنى ما يشاؤه الله، فرد القدرة كلها إليه ومنع أن يفهم من النفي استقلال إبراهيم عن مشيئة ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص242، تحت عنوان «سر الاستدراك بالاستثناء»","url":""}]},{"id":"s6-1224","number":1224,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما دلالة تعليق المشيئة بالربوبية في قوله تعالى: ﴿إلا أن يشاء ربي شيئًا﴾؟","answer":"إضافة المشيئة إلى الرب تؤكد أن تدبير ما يقع لإبراهيم بيد من يتولاه ويربيه، لا بيد المعبودات الباطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص243، تحت عنوان «دلالة تعليق المشيئة بالربوبية»","url":""}]},{"id":"s6-595","number":595,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"لماذا نُكّر ﴿شيئًا﴾ بعد مشيئة الرب؟","answer":"نُكر ﴿شيئًا﴾ للعموم؛ أي أي شيء شاءه الله قل أو عظم، فلا يخرج ممكن عن مشيئته، ولا يدل وقوعه على قدرة الشركاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص243، تحت «دلالة تنكير ﴿شيئًا﴾».","url":""}]},{"id":"s6-596","number":596,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما سر التعبير بالفعل ﴿وسع﴾ في قوله تعالى: ﴿وسع ربي كل شيء علمًا﴾؟","answer":"دل على شمول علم الله وإحاطته بجميع الأشياء والعوالم من غير أن يخرج عنه معلوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص244، تحت عنوان «سر التعبير بالفعل ﴿وسع﴾»","url":""}]},{"id":"s6-1225","number":1225,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما دلالة التمييز ﴿علمًا﴾ في قوله تعالى: ﴿وسع ربي كل شيء علمًا﴾؟","answer":"بيّن جهة السعة وأزال إبهامها، وأصل المعنى: وسع علم ربي كل شيء، فقدم المفعول وأبرز العلم تمييزًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص244–245، تحت عنوان «دلالة التمييز ﴿علمًا﴾»","url":""}]},{"id":"s6-597","number":597,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما أثر التذييل بالاستفهام في قوله تعالى: ﴿أفلا تتذكرون﴾؟","answer":"أنكر عليهم استمرار الغفلة بعد وضوح الحجة، وحضهم على مراجعة ما تعرفه فطرهم وعقولهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص245، تحت عنوان «التذييل بالاستفهام ﴿أفلا تتذكرون﴾»","url":""}]},{"id":"s6-1226","number":1226,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"لماذا اختيرت مادة ﴿تتذكرون﴾ دون تتفكرون؟","answer":"لأن بطلان عبادة ما لا يضر ولا ينفع معلوم مركوز في العقول، فهو محتاج إلى إيقاظ وتذكر أكثر من احتياجه إلى إنشاء نظر جديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص245–246، تحت عنوان «دلالة اختيار مادة ﴿تتذكرون﴾»","url":""}]},{"id":"s6-598","number":598,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما الفرق بين الحجاج والجدال الذي يعين على فهم قوله تعالى: ﴿وحاجه قومه﴾؟","answer":"المطلوب بالحجاج ظهور الحجة، أما الجدال فالمطلوب به رجوع الخصم عن مذهبه وإلزامه بالحجة، وقد يستعمل في مطلق المخاصمة. فبين اللفظين فرق في الغرض مع اشتراكهما في مراجعة الكلام والحجج.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص279، تحت «الجدال والحجاج»","url":""}]},{"id":"s6-599","number":599,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما نكتة الاستفهام بـ﴿كيف﴾ في قوله تعالى: ﴿وكيف أخاف ما أشركتم﴾؟","answer":"خرج الاستفهام إلى التعجب والإنكار من أصل تصور خوفه من معبوداتهم، وهو أبلغ من مجرد نفي الخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص249، تحت عنوان «نكتة الاستفهام بـ﴿وكيف﴾»","url":""}]},{"id":"s6-1227","number":1227,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما دلالة توجيه الاستفهام إلى كيفية الخوف؟","answer":"نفي الكيفية يستلزم نفي الخوف من أصله؛ إذ لا توجد صورة معقولة يخاف بها الموحد ما لا يملك ضرًا ولا نفعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص249–250، تحت عنوان «دلالة توجيه الاستفهام إلى كيفية الخوف»","url":""}]},{"id":"s6-600","number":600,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما سرّ التعبير بالماضي في قوله تعالى: ﴿ما أشركتم﴾؟","answer":"يدل الماضي على تمكن الشرك منهم؛ فقد ألفوه حتى صار كأنه جزء من طبيعتهم جُبلوا عليه، فهم ثابتون عليه يدافعون عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص250، تحت «سر التعبير بالفعل الماضي أشركتم»","url":""}]},{"id":"s6-601","number":601,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿أشركتم بالله ما لم ينزل به عليكم سلطانًا﴾، فجعل البرهان سلطانًا؟","answer":"السلطان أصله القوة والقهر، وسميت الحجة سلطانًا لأن الحق يقهر الباطل ويتسلط على القلوب والعقول بقوة بيانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص252، تحت «سر التعبير بالسلطان دون الحجة».","url":""}]},{"id":"s6-602","number":602,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿لم ينزل به عليكم سلطانًا﴾، مع أن الحجة عقلية لا جسم ينزل؟","answer":"عبر بالإنزال لأن الحجة المعتبرة في أمر العبادة لا تكون إلا بإذن من الله ووحي منه؛ فنفى أن يكون قد نزل عليهم أي مستند يجيز الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص252، تحت «ذكر المعبودات بـ﴿ما لم ينزل به عليكم سلطانًا﴾»؛ وفيه أن المعوّل عليه في الأمور الدينية هو الحجة المنزلة من الله تعالى.","url":""}]},{"id":"s6-603","number":603,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما دلالة وصف المعبودات بأنها مما لم ينزل الله به سلطانًا؟","answer":"بيّن أن شركهم لا أصل له ولا حجة منزلة من الله، وفي الوصف تهكم بمعبودات لا تملك برهانًا على استحقاق العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص252، تحت عنوان «ذكر المعبودات بما لم ينزل به عليكم سلطانًا»","url":""}]},{"id":"s6-1228","number":1228,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما بلاغة الإيجاز في قوله تعالى: ﴿ما لم ينزل به عليكم سلطانًا﴾؟","answer":"جمع التركيب القصير نفي الدليل، وبيان مصدر الحجة الحق، وكشف جرأة المشركين على دعوى لا برهان لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص252–253، تحت عنوان «بلاغة الإيجاز في الآية»","url":""}]},{"id":"s6-604","number":604,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما دلالة سوق المعلوم مساق غيره في قوله تعالى: ﴿فأي الفريقين أحق بالأمن﴾؟","answer":"مع أن الموحد أحق بالأمن قطعًا، صيغ الحكم سؤالًا ليحمل الخصم على الإقرار به من نفسه وتقوم عليه الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص253، تحت عنوان «دلالة سوق المعلوم مساق غيره»","url":""}]},{"id":"s6-1229","number":1229,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما براعة الإنصاف في قوله تعالى: ﴿فأي الفريقين أحق بالأمن﴾؟","answer":"لم يسم إبراهيم نفسه أحق ابتداء، بل عرض الفريقين للحكم كطالب للإنصاف، فكان ذلك أدعى لإلزام القوم بالجواب الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص253–254، تحت عنوان «براعة الإنصاف في ﴿فأي الفريقين أحق بالأمن﴾»","url":""}]},{"id":"s6-605","number":605,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿الفريقين﴾، دون أن يقال: أنا وأنتم؟","answer":"عبر بـ﴿الفريقين﴾ بدل «أنا وأنتم» على طريقة المنصف الذي يعرض القضية كحكم عام، فيستدرج المخالف إلى النظر بعيدًا عن المكابرة الشخصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص253–254، تحت «نكتة الإظهار في مقام الإضمار» في قوله: ﴿فأي الفريقين أحق بالأمن﴾.","url":""}]},{"id":"s6-606","number":606,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿أحق بالأمن﴾ بصيغة التفضيل؟","answer":"جاء ﴿أحق﴾ بصيغة التفضيل على أسلوب الإنصاف في المحاورة، كأن الأمن مفترض للفريقين ثم يطلب تعيين الأجدر به؛ ليكون إلزام الخصم أبلغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص254، تحت «براعة الإنصاف في ﴿فأي الفريقين أحق بالأمن﴾».","url":""}]},{"id":"s6-607","number":607,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"لماذا قيل ﴿إن كنتم تعلمون﴾ بـ﴿إن﴾ دون إذا؟","answer":"أشعرت ﴿إن﴾ بأن علمهم غير متحقق أو غير راجح؛ فهم بين الجهل بالحق والتجاهل عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص254، تحت عنوان «سر التعبير بـ﴿إن﴾ دون (إذا) في قوله: ﴿إن كنتم تعلمون﴾»","url":""}]},{"id":"s6-1230","number":1230,"surah":6,"verses":[81],"references":[{"surah":6,"verses":[81]}],"verseLabel":"الأنعام: 81","question":"ما دلالة حذف جواب الشرط في قوله تعالى: ﴿إن كنتم تعلمون﴾؟","answer":"قدّر الجواب من المقام: إن كنتم تعلمون فأخبروني؛ فحذفه أوجز وحثهم على النطق بما تلزمهم به الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص254، تحت عنوان «دلالة حذف جواب الشرط»","url":""}]},{"id":"s6-608","number":608,"surah":6,"verses":[82],"references":[{"surah":6,"verses":[82]}],"verseLabel":"الأنعام: 82","question":"لماذا جاء الجواب بصفة عامة: ﴿الذين آمنوا﴾، ولم يقل: إبراهيم ومن اتبعه؟","answer":"جاء الجواب عامًا بـ﴿الذين آمنوا﴾ ليقرر قاعدة لا تختص بإبراهيم: الأمن لكل من جمع الإيمان الخالص وترك خلطه بالظلم. والموصول يبين سبب استحقاقهم الأمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص259، تحت «فائدة التعبير عن أهل الإيمان بالاسم الموصول والصلة» في ﴿الذين آمنوا﴾.","url":""}]},{"id":"s6-609","number":609,"surah":6,"verses":[82],"references":[{"surah":6,"verses":[82]}],"verseLabel":"الأنعام: 82","question":"ما بلاغة الاستعارة في الفعل ﴿يلبسوا﴾ في قوله تعالى: ﴿ولم يلبسوا إيمانهم بظلم﴾؟","answer":"صوّر إدخال الظلم على الإيمان بخلط يغطي صفاءه ويمنع تميزه، كما يلتبس الشيء بغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص261، تحت عنوان «بلاغة الاستعارة في الفعل ﴿يلبسوا﴾»","url":""}]},{"id":"s6-1231","number":1231,"surah":6,"verses":[82],"references":[{"surah":6,"verses":[82]}],"verseLabel":"الأنعام: 82","question":"ما الفرق بين اللبس والخلط؟","answer":"الخلط جمع أشياء بعضها ببعض، أما اللبس فيزيد معنى الاشتباه والتغطية حتى يصعب التمييز؛ لذلك كان أدق في تصوير أثر الظلم في الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص266، تحت عنوان «(اللبس) و(الخلط)»","url":""}]},{"id":"s6-610","number":610,"surah":6,"verses":[82],"references":[{"surah":6,"verses":[82]}],"verseLabel":"الأنعام: 82","question":"ما نكتة إضافة الإيمان إليهم والتعبير عن الشرك بالظلم؟","answer":"أضاف الإيمان إليهم لتشريف ما تحقق فيهم منه، وسمى الشرك ظلمًا لأنه وضع العبادة في غير موضعها وأعظم الجور على حق الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص261–262، تحت عنوان «نكتة إضافة الإيمان لهم، وإيثار التعبير عن الشرك بالظلم»","url":""}]},{"id":"s6-1232","number":1232,"surah":6,"verses":[82],"references":[{"surah":6,"verses":[82]}],"verseLabel":"الأنعام: 82","question":"ما فائدة تنكير لفظ ﴿بظلم﴾؟","answer":"أفاد التحذير من أدنى قدر من الظلم المقصود، وهو الشرك؛ فإذا انتفى قليله كان نفي كثيره أولى، فخلص الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص262–263، تحت عنوان «فائدة تنكير لفظ ﴿بظلم﴾»","url":""}]},{"id":"s6-611","number":611,"surah":6,"verses":[82],"references":[{"surah":6,"verses":[82]}],"verseLabel":"الأنعام: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿أولئك لهم الأمن﴾ بتقديم ﴿لهم﴾؟","answer":"قُدم ﴿لهم﴾ للاختصاص والعناية؛ فالأمن الحق ثابت لهؤلاء دون من خلط إيمانه بالشرك، وهو جواب مباشر لسؤال: أي الفريقين أحق بالأمن؟","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص263–264، تحت «العدول عن الجواب بـ(أحق بالأمن) إلى ﴿أولئك لهم الأمن﴾».","url":""}]},{"id":"s6-612","number":612,"surah":6,"verses":[82],"references":[{"surah":6,"verses":[82]}],"verseLabel":"الأنعام: 82","question":"لماذا عُرّف ﴿الأمن﴾؟","answer":"عُرّف ﴿الأمن﴾ تعريف الجنس لإثبات جنس الأمن كله لهم بطريق أوكد؛ فيشمل طمأنينة القلب في الدنيا والسلامة من الخوف والعذاب في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص263–264، تحت «العدول عن الجواب بـ(أحق بالأمن) إلى ﴿أولئك لهم الأمن﴾»، في بيان تعريف ﴿الأمن﴾ للجنس.","url":""}]},{"id":"s6-613","number":613,"surah":6,"verses":[82],"references":[{"surah":6,"verses":[82]}],"verseLabel":"الأنعام: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿وهم مهتدون﴾ بالاسم، دون أن يقال: ويهتدون؟","answer":"الجملة الاسمية تدل على ثبوت اهتدائهم ودوامه، لا على حدوث عابر؛ فمن خلص إيمانه استقر على الهدى ولم يكن اهتداؤه مؤقتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص264، تحت «نكتة الإخبار بالاسمية في قوله: ﴿وهم مهتدون﴾».","url":""}]},{"id":"s6-614","number":614,"surah":6,"verses":[83],"references":[{"surah":6,"verses":[83]}],"verseLabel":"الأنعام: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿وتلك حجتنا﴾ باسم الإشارة للبعيد؟","answer":"أشير إلى الحجة باسم البعيد تعظيمًا لشأنها ورفعة منزلتها، مع استحضار ما سبق من وجوه البرهان كأنه أمر متميز مشاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص270، تحت «فائدة اسم الإشارة في قوله: ﴿وتلك حجتنا﴾».","url":""}]},{"id":"s6-615","number":615,"surah":6,"verses":[83],"references":[{"surah":6,"verses":[83]}],"verseLabel":"الأنعام: 83","question":"لماذا أضيفت الحجة إلى الله: ﴿حجتنا﴾، مع أن إبراهيم هو الذي نطق بها؟","answer":"أضيفت الحجة إلى الله لأنها بتعليمه وتوفيقه وإيتائه، وإن جرت على لسان إبراهيم؛ فمصدر نورها وقوتها من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص270، تحت «فائدة التعريف بالإضافة إلى ضمير العظمة في ﴿حجتنا﴾».","url":""}]},{"id":"s6-616","number":616,"surah":6,"verses":[83],"references":[{"surah":6,"verses":[83]}],"verseLabel":"الأنعام: 83","question":"ما دلالة التعبير عن الحجة بالإيتاء في قوله تعالى: ﴿وتلك حجتنا آتيناها إبراهيم﴾؟","answer":"جعل الحجة عطاء من الله، فدل على أنها نعمة موهوبة لإبراهيم بالعلم والبيان، لا ثمرة استقلال بشري.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص270، تحت عنوان «التعبير عن الحجة بالإيتاء»","url":""}]},{"id":"s6-1233","number":1233,"surah":6,"verses":[83],"references":[{"surah":6,"verses":[83]}],"verseLabel":"الأنعام: 83","question":"ما نكتة تقديم المفعول الثاني ﴿حجتنا﴾ على المفعول الأول؟","answer":"قدم الحجة للعناية بها والتنويه بشأنها، ثم ذكر من أوتيها، فصار محور الكلام النعمة التي أقام الله بها البرهان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص270–271، تحت عنوان «نكتة تقديم المفعول الثاني على المفعول الأول»","url":""}]},{"id":"s6-617","number":617,"surah":6,"verses":[83],"references":[{"surah":6,"verses":[83]}],"verseLabel":"الأنعام: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿على قومه﴾، وما دلالة ﴿على﴾؟","answer":"تفيد ﴿على﴾ الاستعلاء؛ فقد علت حجة إبراهيم حجج قومه وغلبتها، فكانت له منزلة الانتصار بالحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص272، تحت «سر استعمال حرف الاستعلاء في قوله: ﴿على قومه﴾».","url":""}]},{"id":"s6-618","number":618,"surah":6,"verses":[83],"references":[{"surah":6,"verses":[83]}],"verseLabel":"الأنعام: 83","question":"ما بلاغة الاستعارة في التعبير برفع الدرجات؟","answer":"صوّر زيادة المنزلة والفضل بصعود محسوس في درجات عالية، فقرّب رفعة أهل الإيمان والعلم إلى الذهن.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص273، تحت عنوان «بلاغة الاستعارة بالتعبير برفع الدرجات»","url":""}]},{"id":"s6-1234","number":1234,"surah":6,"verses":[83],"references":[{"surah":6,"verses":[83]}],"verseLabel":"الأنعام: 83","question":"ما سر التعبير بالموصول والعدول عن الضمير في قوله تعالى: ﴿من نشاء﴾؟","answer":"عم الموصول كل من تتعلق به المشيئة، فلم يقصر الرفع على إبراهيم وحده، وربط المنزلة باختيار الله وحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص273–274، تحت عنوان «سر التعبير بالموصول، والعدول عن الضمير إليه»","url":""}]},{"id":"s6-619","number":619,"surah":6,"verses":[83],"references":[{"surah":6,"verses":[83]}],"verseLabel":"الأنعام: 83","question":"لماذا أوثر لفظ الربوبية في قوله تعالى: ﴿إن ربك حكيم عليم﴾؟","answer":"ناسب مقام رفع الدرجات والهداية؛ فالرب هو المتولي للتربية والإنعام، وفي إضافته إلى النبي عناية وتثبيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص276–277، تحت عنوان «إيثار لفظ الربوبية في قوله: ﴿إن ربك حكيم عليم﴾»","url":""}]},{"id":"s6-1235","number":1235,"surah":6,"verses":[83],"references":[{"surah":6,"verses":[83]}],"verseLabel":"الأنعام: 83","question":"كيف ناسبت فاصلة ﴿حكيم عليم﴾ مضمون الآية؟","answer":"رفع الدرجات يجري بحكمة تضع الفضل موضعه، وبعلم بمن يستحقه وبمقادير أحوال العباد، فلا يكون اعتباطًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص277–278، تحت عنوان «مناسبة الفاصلة لمضمون الآية»","url":""}]},{"id":"s6-620","number":620,"surah":6,"verses":[83],"references":[{"surah":6,"verses":[83]}],"verseLabel":"الأنعام: 83","question":"لم قدم ﴿حكيم﴾ على ﴿عليم﴾ في ختام إيتاء الحجة ورفع الدرجات؟","answer":"المقام يبين تفضيل إبراهيم ورفع درجته، وهو مظهر للحكمة في وضع الفضل موضعه، فناسب تقديمها. ثم جاء العلم ليبين أن هذا الإحكام قائم على العلم بمن يليق به ذلك الفضل وبما ينبغي له.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص278، تحت «سر تقديم الحكيم على العليم»","url":""}]},{"id":"s6-621","number":621,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"ما بلاغة الكناية في وصف إيتاء الذرية بأنه هبة؟","answer":"الهبة عطاء بلا عوض، فكنى بها عن محض فضل الله على إبراهيم بإسحاق ويعقوب، ثم كملت النعمة بهدايتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص282، تحت عنوان «بلاغة الكناية في وصف إيتاء الذرية بأنه هبة»","url":""}]},{"id":"s6-1236","number":1236,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"ما معنى اللام في قوله تعالى: ﴿ووهبنا له إسحاق ويعقوب﴾؟","answer":"تفيد الاختصاص والنفع؛ أي جعلنا إسحاق ويعقوب هبة خاصة لإبراهيم وقرة عين له وامتدادًا صالحًا لذريته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص282–283، تحت عنوان «معنى اللام في قوله: ﴿له﴾»","url":""}]},{"id":"s6-622","number":622,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"ما سرّ تقديم إسحاق ويعقوب على نوح مع أن نوحًا أسبق زمنًا؟","answer":"قُدم إسحاق ويعقوب لاتصالهما المباشر بإبراهيم الذي يساق الكلام في إنعام الله عليه، ثم استؤنف بنوح السابق زمنًا لبيان تأصل الهداية في أصول هذه السلسلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص284، تحت «الغرض من تقديم ذكر إسحاق ويعقوب في السياق».","url":""}]},{"id":"s6-623","number":623,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"ما نكتة الفصل في قوله تعالى: ﴿كلًّا هدينا﴾؟","answer":"استؤنفت الجملة لتقرير تمام نعمة الهداية لكل من إسحاق ويعقوب، فجاءت كحكم مستقل بعد ذكر الهبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص285، تحت عنوان «نكتة الفصل في قوله تعالى: ﴿كلًّا هدينا﴾»","url":""}]},{"id":"s6-1237","number":1237,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"ما بلاغة عطف جملة ﴿ونوحًا هدينا من قبل﴾ على ﴿كلًّا هدينا﴾؟","answer":"وصل هداية نوح بهداية إبراهيم وذريته مع التنبيه بـ﴿من قبل﴾ على سبق زمنه وتأصل طريق الهدى في أصولهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص286–287، تحت عنوان «بلاغة عطف جملة: ﴿ونوحًا هدينا من قبل﴾ على جملة: ﴿كلًّا هدينا﴾»","url":""}]},{"id":"s6-624","number":624,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"ما فائدة التعبير بقبلية هداية نوح؟","answer":"أثبت أن سنة الهداية قديمة قبل إبراهيم وذريته، وربط السلسلة اللاحقة بأصل سابق ثابت.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص288، تحت عنوان «فائدة التعبير بقبلية هداية نوح»","url":""}]},{"id":"s6-1238","number":1238,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"ما فائدة التعبير بالحال في قوله تعالى: ﴿ومن ذريته﴾؟","answer":"جاء ذكر الذرية في سياق تعداد نعم الله على إبراهيم، فبيّن أن الهداية امتدت في ذريته وصارت من وجوه تكريمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص288–289، تحت عنوان «فائدة التعبير بالحال في قوله: ﴿ومن ذريته﴾»","url":""}]},{"id":"s6-625","number":625,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"لماذا بدأ من الذرية بداود وسليمان؟","answer":"بدأ بداود وسليمان لأنهما زوج يجمع النبوة والملك مع علاقة الأب والابن، ثم نُظمت الأسماء في مجموعات تقوم على مناسبات كالحكم والابتلاء والقرابة، لا على التسلسل الزمني.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص301، تحت «السر بذكر الأنبياء بهذا الترتيب في مجمل الآية الكريمة».","url":""}]},{"id":"s6-626","number":626,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"ما بلاغة الاعتراض بأسلوب التشبيه في قوله تعالى: ﴿وكذلك نجزي المحسنين﴾؟","answer":"اعترض بين أسماء الأنبياء ليقرر أن مثل ذلك الجزاء والهداية سنة للمحسنين، فعمم الحكم بعد أمثلته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص290، تحت عنوان «بلاغة الاعتراض بأسلوب التشبيه في ﴿وكذلك﴾»","url":""}]},{"id":"s6-1239","number":1239,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"ما دلالة حرف التشبيه في ﴿وكذلك نجزي المحسنين﴾؟","answer":"ربط الكاف جزاء كل محسن بالجزاء السابق للأنبياء؛ فكما أكرمهم الله بإحسانهم يكرم غيرهم من المحسنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص290–291، تحت عنوان «دلالة حرف التشبيه في ﴿وكذلك﴾»","url":""}]},{"id":"s6-627","number":627,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"ما دلالة العطف بالواو بين أسماء الأنبياء؟","answer":"الواو لمطلق الجمع ولا تقتضي ترتيبًا زمنيًا، فجمعت الأنبياء في أصل الهداية والفضل من غير أن تجعل تسلسل الأسماء تاريخًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص301، تحت عنوان «دلالة العطف بالواو بين أسماء الأنبياء مطلق الجمع»","url":""}]},{"id":"s6-1240","number":1240,"surah":6,"verses":[84],"references":[{"surah":6,"verses":[84]}],"verseLabel":"الأنعام: 84","question":"ما السر في ذكر الأنبياء بهذا الترتيب في مجمل الآية؟","answer":"راعى السياق مناسبات من القرابة والزمن والملك والابتلاء والصلاح وتنوع أحوال الرسالة، فكان ترتيب المعاني لا ترتيب الأعمار وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص301–302، تحت عنوان «السر بذكر الأنبياء بهذا الترتيب في مجمل الآية الكريمة»","url":""}]},{"id":"s6-628","number":628,"surah":6,"verses":[85],"references":[{"surah":6,"verses":[85]}],"verseLabel":"الأنعام: 85","question":"ما وجه جمع زكريا ويحيى وعيسى وإلياس في نسق واحد؟","answer":"جمع الأربعة وصف الصلاح والزهد عن زخارف الدنيا، مع تقارب بعضهم في النسب والزمن وحال الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص295، تحت عنوان «وجه ذكر الأنبياء ﴿وزكريا ويحيى وعيسى وإلياس﴾ معًا»","url":""}]},{"id":"s6-1241","number":1241,"surah":6,"verses":[85],"references":[{"surah":6,"verses":[85]}],"verseLabel":"الأنعام: 85","question":"ما علة ترتيب زكريا ويحيى وعيسى وإلياس في الآية؟","answer":"قدم زكريا على ابنه يحيى، وجاءا قبل عيسى لقرب الزمن، وقدم عيسى على إلياس لكونه صاحب كتاب؛ فترتبوا بحسب مناسبات ظاهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص295–296، تحت عنوان «علة ترتيب ذكر الأنبياء في ﴿وزكريا ويحيى وعيسى وإلياس﴾»","url":""}]},{"id":"s6-629","number":629,"surah":6,"verses":[85],"references":[{"surah":6,"verses":[85]}],"verseLabel":"الأنعام: 85","question":"لم وصف هؤلاء الأنبياء بـ﴿الصالحين﴾ مع أن الصلاح قد يوصف به غيرهم؟","answer":"المراد كمال الصلاح، لا مجرد أصله؛ فاللام تبرز أنهم الكاملون في الإتيان بما ينبغي والتحرز عما لا ينبغي. وفي الوصف ثناء يبين نقاء نفوسهم وتمام استقامتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص296–297، تحت «معنى اللام في لفظ ﴿الصالحين﴾»","url":""}]},{"id":"s6-630","number":630,"surah":6,"verses":[86],"references":[{"surah":6,"verses":[86]}],"verseLabel":"الأنعام: 86","question":"لماذا جُمِع إسماعيل واليسع ويونس ولوط في نسق واحد؟","answer":"جُمع إسماعيل واليسع ويونس ولوط لأنهم لم يبق لهم أتباع وأشياع، وقيل: لأن كل واحد منهم أرسل إلى أمة صغيرة؛ فجعلهم السياق مجموعة ثالثة يجمعها أصل الهداية والرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص298–299، تحت عنوان «مناسبة اقتران الأنبياء في قوله: ﴿وإسماعيل واليسع ويونس ولوط﴾»","url":""}]},{"id":"s6-631","number":631,"surah":6,"verses":[86],"references":[{"surah":6,"verses":[86]}],"verseLabel":"الأنعام: 86","question":"ما فائدة الاعتراض بجملة ﴿وكلًّا فضلنا على العالمين﴾؟","answer":"قرر وسط تعداد الأسماء أن الجامع بينهم تفضيل الله، وفصل منزلة الاصطفاء عن مجرد ذكر الأشخاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص298–299، تحت عنوان «فائدة الاعتراض بجملة ﴿وكلًّا فضلنا على العالمين﴾»","url":""}]},{"id":"s6-1242","number":1242,"surah":6,"verses":[86],"references":[{"surah":6,"verses":[86]}],"verseLabel":"الأنعام: 86","question":"ما دلالة إسناد الفعل إلى ضمير العظمة في ﴿فضلنا﴾؟","answer":"أسند التفضيل إلى الله بضمير العظمة للتنويه بعظم العطاء وعلو منزلة من اختارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص299–300، تحت عنوان «دلالة إسناد الفعل إلى ضمير العظمة في ﴿فضلنا﴾»","url":""}]},{"id":"s6-632","number":632,"surah":6,"verses":[86],"references":[{"surah":6,"verses":[86]}],"verseLabel":"الأنعام: 86","question":"لماذا عُمّم تفضيل كل واحد منهم على ﴿العالمين﴾؟","answer":"المراد تفضيل كل نبي على عالمي زمانه أو على من عدا الأنبياء، لا تفضيل كل واحد على جميع الأنبياء الآخرين؛ فالتعميم مقيد بما يليق بمقام النبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص300–301، تحت «دلالة اللام في قوله: ﴿على العالمين﴾ على الاستغراق المقيد»","url":""}]},{"id":"s6-633","number":633,"surah":6,"verses":[87],"references":[{"surah":6,"verses":[87]}],"verseLabel":"الأنعام: 87","question":"ما بلاغة عطف ﴿ومن آبائهم﴾ على قوله تعالى: ﴿وكلًّا فضلنا﴾؟","answer":"وسع العطف دائرة الاجتباء بعد الأنبياء المسمين لتشمل الصالحين من آبائهم وذرياتهم وإخوانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص304–305، تحت عنوان «بلاغة عطف جملة ﴿ومن آبائهم﴾ على جملة ﴿وكلًّا فضلنا﴾»","url":""}]},{"id":"s6-1243","number":1243,"surah":6,"verses":[87],"references":[{"surah":6,"verses":[87]}],"verseLabel":"الأنعام: 87","question":"ما دلالة ﴿من﴾ في قوله تعالى: ﴿ومن آبائهم﴾؟","answer":"تفيد التبعيض مع البيان؛ فالمجتبى بعض الآباء والذريات والإخوان ممن صلح، لا كل من دخل في القرابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص305–306، تحت عنوان «إفادة ﴿من﴾ التبعيض والبيان في ﴿ومن آبائهم﴾»","url":""}]},{"id":"s6-634","number":634,"surah":6,"verses":[87],"references":[{"surah":6,"verses":[87]}],"verseLabel":"الأنعام: 87","question":"ما بلاغة الحذف في قوله تعالى بعد ذكر ﴿آبائهم وذرياتهم وإخوانهم﴾؟","answer":"حذف بيان من اجتبي منهم اعتمادًا على ﴿واجتبيناهم﴾؛ فدل السياق على أن المصطفى بعض أهل القرابة ممن صلح، لا جميعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص304–305، تحت عنوان «بلاغة الحذف في قوله تعالى»","url":""}]},{"id":"s6-635","number":635,"surah":6,"verses":[87],"references":[{"surah":6,"verses":[87]}],"verseLabel":"الأنعام: 87","question":"ما سرّ التعبير في قوله تعالى: ﴿واجتبيناهم﴾، دون أن يقال: اخترناهم؟","answer":"الاجتباء جمع على طريق الاصطفاء مع تخصيص العبد بفيض من النعم من غير سعي سابق؛ وهو أنسب لجماعة مختارة جمعها الله بعد اصطفائها، وأخص من مطلق الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص303، تحت عنوان «شرح المفردات: ﴿واجتبيناهم﴾»","url":""}]},{"id":"s6-636","number":636,"surah":6,"verses":[87],"references":[{"surah":6,"verses":[87]}],"verseLabel":"الأنعام: 87","question":"ما نكتة تعدية فعل الهداية بـ﴿إلى﴾ في قوله تعالى: ﴿وهديناهم إلى صراط مستقيم﴾؟","answer":"صورت الهداية إيصالًا إلى طريق معلوم يسلكونه، فجمعت الدلالة على الإرشاد والتمكين من بلوغ الصراط.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص307، تحت عنوان «نكتة تعدية فعل الهداية بـ﴿إلى﴾»","url":""}]},{"id":"s6-1244","number":1244,"surah":6,"verses":[87],"references":[{"surah":6,"verses":[87]}],"verseLabel":"الأنعام: 87","question":"لماذا وصف الصراط بالاستقامة مع أن الصراط لا يكون إلا مستقيمًا؟","answer":"جاء الوصف للتنويه بكمال الطريق ونفي كل اعوجاج عنه، وتثبيت أن ما هدي إليه الأنبياء هو الطريق الواضح الموصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص307–308، تحت عنوان «نكتة وصف الصراط بالاستقامة مع كونه كذلك»","url":""}]},{"id":"s6-637","number":637,"surah":6,"verses":[87],"references":[{"surah":6,"verses":[87]}],"verseLabel":"الأنعام: 87","question":"ما فائدة وصف الصراط بالاستقامة في قوله تعالى: ﴿وهديناهم إلى صراط مستقيم﴾؟","answer":"الصراط هو الطريق الواضح الخالي من العوج، فوصْفه بالاستقامة تصريح بالمعنى المفهوم منه وتأكيد له، لئلا يكتفى بدلالة اللفظ الضمنية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص308، تحت «نكتة وصف الصراط بالاستقامة مع كونه كذلك»","url":""}]},{"id":"s6-638","number":638,"surah":6,"verses":[88],"references":[{"surah":6,"verses":[88]}],"verseLabel":"الأنعام: 88","question":"ما فائدة التعبير عن هدى الله باسم الإشارة في قوله تعالى: ﴿ذلك هدى الله﴾؟","answer":"جمع اسم الإشارة ما تقدم من وجوه الهداية وجعلها كأمر حاضر متميز يشار إليه ويعتمد عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص312، تحت عنوان «فائدة التعبير عن هدى الله باسم الإشارة»","url":""}]},{"id":"s6-1245","number":1245,"surah":6,"verses":[88],"references":[{"surah":6,"verses":[88]}],"verseLabel":"الأنعام: 88","question":"لماذا أوثر اسم إشارة البعيد في قوله تعالى: ﴿ذلك هدى الله﴾؟","answer":"استعمل البعيد لرفع منزلة الهدى وتعظيم قدره، فكأنه في مرتبة عالية يشير إليها المتكلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص312، تحت عنوان «إيثار التعبير باسم إشارة البعد»","url":""}]},{"id":"s6-639","number":639,"surah":6,"verses":[88],"references":[{"surah":6,"verses":[88]}],"verseLabel":"الأنعام: 88","question":"لماذا أضيف الهدى إلى الله: ﴿هدى الله﴾؟","answer":"أضيف الهدى إلى الله لتعظيمه وتشريفه، ولبيان اختصاص التوفيق الحقيقي به؛ فما ناله الأنبياء ليس مستقلًا عن مشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص312، تحت «دلالة إضافة الهدى إلى الله تعالى»","url":""}]},{"id":"s6-640","number":640,"surah":6,"verses":[88],"references":[{"surah":6,"verses":[88]}],"verseLabel":"الأنعام: 88","question":"ما دلالة الباء في قوله تعالى: ﴿يهدي به﴾؟","answer":"جعلت هدى الله سببًا وواسطة يوصل بها من يشاء إلى الحق، والضمير عائد إلى الهدى المذكور.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص313، تحت عنوان «دلالة الباء في يهدي به»","url":""}]},{"id":"s6-1246","number":1246,"surah":6,"verses":[88],"references":[{"surah":6,"verses":[88]}],"verseLabel":"الأنعام: 88","question":"ما فائدة تعليق الهداية بمشيئة الله تعالى؟","answer":"بيّن أن التوفيق للهدى فضل يجري باختيار الله وحكمته، فلا يستقل به العبد ولا يفرضه نسب أو منزلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص313–314، تحت عنوان «فائدة تعليق الهداية بمشيئة الله تعالى»","url":""}]},{"id":"s6-641","number":641,"surah":6,"verses":[88],"references":[{"surah":6,"verses":[88]}],"verseLabel":"الأنعام: 88","question":"ما معنى ﴿من﴾ في قوله تعالى: ﴿من يشاء من عباده﴾؟","answer":"هي بيانية تبين أن من تعلقت بهم مشيئة الهداية أفراد من عباده، مع بقاء الاختيار له سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص315، تحت عنوان «معنى من في من عباده»","url":""}]},{"id":"s6-1247","number":1247,"surah":6,"verses":[88],"references":[{"surah":6,"verses":[88]}],"verseLabel":"الأنعام: 88","question":"ما سر التعبير بلفظ ﴿عباد﴾ في مقام الهداية؟","answer":"اختير لفظ العباد لإظهار مقام الخضوع لله والانتساب إليه، وهو أنسب بمن قبلوا هدايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص315، تحت عنوان «سر التعبير بلفظ عباد»","url":""}]},{"id":"s6-1248","number":1248,"surah":6,"verses":[88],"references":[{"surah":6,"verses":[88]}],"verseLabel":"الأنعام: 88","question":"ما فائدة إضافة العباد إلى ضمير الجلالة؟","answer":"الإضافة تشريف وتكريم، وتبين أن هدايتهم عناية خاصة من الله بعباده الذين اختارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص315–316، تحت عنوان «فائدة إضافة العباد إلى ضمير الجلالة»","url":""}]},{"id":"s6-642","number":642,"surah":6,"verses":[88],"references":[{"surah":6,"verses":[88]}],"verseLabel":"الأنعام: 88","question":"ما دلالة ذكر الشرك بعد ذكر الهدى في قوله تعالى: ﴿ولو أشركوا لحبط عنهم﴾؟","answer":"قابل أعلى الهداية بأشد ما يبطلها ليقرر أن الشرك يهدم العمل ولا تحمي منه منزلة صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص316، تحت عنوان «دلالة ذكر الشرك بعد ذكر الهدى»","url":""}]},{"id":"s6-1249","number":1249,"surah":6,"verses":[88],"references":[{"surah":6,"verses":[88]}],"verseLabel":"الأنعام: 88","question":"ما دلالة الشرط بـ﴿لو﴾ في قوله تعالى: ﴿ولو أشركوا﴾؟","answer":"فرضت أمرًا ممتنع الوقوع من الأنبياء لتقرير قاعدة عامة: لو وقع الشرك ممن علا قدره لحبط عمله، فغيره أولى بالحذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص316، تحت عنوان «دلالة الشرط بلو في ولو أشركوا»","url":""}]},{"id":"s6-643","number":643,"surah":6,"verses":[88],"references":[{"surah":6,"verses":[88]}],"verseLabel":"الأنعام: 88","question":"ما الصورة في التعبير بحبوط العمل في قوله تعالى: ﴿لحبط عنهم ما كانوا يعملون﴾؟","answer":"الحبط في أصله انتفاخ بطن الإبل من أكل يضرها ولا ينفعها. فصُوّر به بطلان الأعمال بالشرك وذهاب ثمرتها؛ إذ تشبه الأعمال التي أفسدها الشرك طعامًا أضر آكله ولم يحقق له النفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص317–318، تحت «بلاغة المجاز في التعبير بالحبط»","url":""}]},{"id":"s6-644","number":644,"surah":6,"verses":[89],"references":[{"surah":6,"verses":[89]}],"verseLabel":"الأنعام: 89","question":"ما المراد بالكتاب والحكم في قوله تعالى: ﴿أولئك الذين آتيناهم الكتاب والحكم والنبوة﴾؟","answer":"الكتاب جنس الكتب المنزلة، والحكم العلم والحكمة والفصل والقضاء بالحق؛ وهما مع النبوة وجوه تكريم للأنبياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص322–323، تحت عنوان «شرح المفردات: الكتاب والحكم»","url":""}]},{"id":"s6-1250","number":1250,"surah":6,"verses":[89],"references":[{"surah":6,"verses":[89]}],"verseLabel":"الأنعام: 89","question":"ما براعة الاستئناف الابتدائي في قوله تعالى: ﴿أولئك الذين آتيناهم الكتاب والحكم والنبوة﴾؟","answer":"استأنف بعد تعداد الأنبياء حكمًا جامعًا لعطاياهم، فربط الأسماء السابقة بسبب رفعتها من غير عطف يضعف استقلال التقرير.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص323–324، تحت عنوان «براعة الاستئناف الابتدائي في الآية»","url":""}]},{"id":"s6-645","number":645,"surah":6,"verses":[89],"references":[{"surah":6,"verses":[89]}],"verseLabel":"الأنعام: 89","question":"ما سرّ تقديم ﴿الكتاب﴾ على ﴿الحكم والنبوة﴾؟","answer":"قُدِّم الكتاب لأنه أعلى مراتب التفضيل المذكورة في هذا السياق، ثم ذُكر الحكم، ثم النبوة؛ فجاء الترتيب بحسب وجوه العطاء والتكريم التي خُص بها أولئك المهديون.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص326–327، تحت «دلالة ذكر الكتاب والحكم والنبوة دون سواها على هذا الترتيب»","url":""}]},{"id":"s6-646","number":646,"surah":6,"verses":[89],"references":[{"surah":6,"verses":[89]}],"verseLabel":"الأنعام: 89","question":"ما دلالة الإشارة إلى غير مذكور بلفظ ﴿هؤلاء﴾؟","answer":"استحضر كفار مكة المشاهدين من غير أن يسبق لهم اسم، تحقيرًا لاعتراضهم أمام موكب الأنبياء وتنبيهًا إلى حضورهم في مقام الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص329، تحت عنوان «دلالة الإشارة إلى غير مذكور في هؤلاء»","url":""}]},{"id":"s6-1251","number":1251,"surah":6,"verses":[89],"references":[{"surah":6,"verses":[89]}],"verseLabel":"الأنعام: 89","question":"ما دلالة دخول الفاء في قوله تعالى: ﴿فقد وكلنا بها قومًا﴾؟","answer":"ربطت الجواب بشرط كفر هؤلاء ربط النتيجة بسببها، وأفادت سرعة تحقق البديل وأن كفرهم لا يعطل حفظ الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص329–330، تحت عنوان «دلالة دخول الفاء في فقد وكلنا بها قومًا»","url":""}]},{"id":"s6-647","number":647,"surah":6,"verses":[89],"references":[{"surah":6,"verses":[89]}],"verseLabel":"الأنعام: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿فقد وكلنا بها قومًا﴾، فجعل الإيمان أمانة موكّلة؟","answer":"التوكيل هو إسناد الشيء إلى من يحفظه ويقوم به؛ فصور الإيمان بهذه الأصول أمانة قد أقام الله لها قومًا يحفظونها، فلا تضيع بكفر قوم آخرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص330–331، تحت «بلاغة الاستعارة في فقد وكلنا بها قومًا»","url":""}]},{"id":"s6-648","number":648,"surah":6,"verses":[89],"references":[{"surah":6,"verses":[89]}],"verseLabel":"الأنعام: 89","question":"من هم القوم الموكلون بالكتاب والحكم والنبوة في المعنى الإجمالي للآية؟","answer":"هم من قاموا بالإيمان بالوحي وحفظه، وفي مقدمتهم الأنبياء والمؤمنون ومن تبعهم بإحسان، فلا يضيع الحق بكفر قوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص323–324، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s6-1252","number":1252,"surah":6,"verses":[89],"references":[{"surah":6,"verses":[89]}],"verseLabel":"الأنعام: 89","question":"لماذا قيل ﴿قومًا﴾ منكرة دون ناس أو فئة؟","answer":"أفاد التنكير التعظيم والعموم، ولفظ القوم يدل على جماعة متماسكة تنهض بالحق، وفيه بشارة بانتشار الإيمان بين أقوام.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص331–332، تحت عنوان «إيثار التعبير بقومًا منكرة دون ناس أو فئة»","url":""}]},{"id":"s6-649","number":649,"surah":6,"verses":[89],"references":[{"surah":6,"verses":[89]}],"verseLabel":"الأنعام: 89","question":"لماذا دخلت الباء على ﴿بكافرين﴾؟","answer":"الباء زائدة في خبر ﴿ليس﴾ لتوكيد النفي؛ أي ثبت أنهم منزّهون عن الكفر بها، متمسكون بالإيمان لا يتطرق إلى وصفهم شك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص332، تحت «بلاغة الوصف بالجملة الاسمية في ليسوا بها بكافرين»","url":""}]},{"id":"s6-650","number":650,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"ما براعة الاستئناف في قوله تعالى: ﴿أولئك الذين هدى الله﴾؟","answer":"استأنف ثناء جديدًا بعد ذكر عطايا الأنبياء، فجعل هدايتهم حكمًا مستقلًا يمهد للأمر بالاقتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص335، تحت عنوان «براعة الاستئناف في أولئك الذين هدى الله»","url":""}]},{"id":"s6-1253","number":1253,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"ما دلالة الفاء في قوله تعالى: ﴿فبهداهم اقتده﴾؟","answer":"فرعت الأمر بالاقتداء على ثبوت هداية الأنبياء؛ فلأن الله هداهم كان هداهم جديرًا بالاتباع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص335–336، تحت عنوان «دلالة الفاء على التفريع»","url":""}]},{"id":"s6-651","number":651,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"ما نكتة تقديم الجار والمجرور في قوله تعالى: ﴿فبهداهم اقتده﴾؟","answer":"قدم للاختصاص والعناية، فقصر الاقتداء المأمور به على هدى الأنبياء الحق، لا على أهواء المخالفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص337، تحت عنوان «نكتة تقديم الجار والمجرور في فبهداهم اقتده»","url":""}]},{"id":"s6-1254","number":1254,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"ما دلالة الأمر بالاقتداء في قوله تعالى: ﴿اقتده﴾؟","answer":"الأمر باتباع أصول توحيد الأنبياء وأخلاقهم وطرائق طاعتهم، لا الخصائص والشرائع التي تختلف بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص338، تحت عنوان «دلالة الأمر بالاقتداء في اقتده»","url":""}]},{"id":"s6-652","number":652,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"ما فائدة إضافة الهدى إلى الضمير ﴿هم﴾ في قوله تعالى: ﴿فبهداهم اقتده﴾؟","answer":"أشعرت الإضافة بتمكن الهدى في الأنبياء حتى صار صفة ملازمة لهم، وجمعت ما تفرق فيهم من وجوه الكمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص337، تحت عنوان «فائدة إضافة الهدى إلى الضمير هم»","url":""}]},{"id":"s6-1255","number":1255,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"ما فائدة تخصيص النبي ﷺ بالذكر في الأمر بالاقتداء؟","answer":"أفرده بالخطاب تشريفًا وتثبيتًا، وليكون اقتداؤه بالأنبياء قدوة لأمته في اتباع طريقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص338، تحت عنوان «فائدة تخصيص النبي بالذكر»","url":""}]},{"id":"s6-653","number":653,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"لماذا جاءت هاء السكت في ﴿اقتده﴾؟","answer":"الهاء في ﴿اقتده﴾ هاء السكت، تثبت في الوقف، وقد ثبتت في رسم المصحف. وهي تهيئ وقفًا ظاهرًا على كلمة جامعة لمسيرة الأنبياء، فيزداد التنبيه إلى أهمية الاقتداء بهداهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص338، تحت «بلاغة الوقف على هاء السكت في قوله: ﴿فبهداهم اقتده﴾»","url":""}]},{"id":"s6-654","number":654,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"ما دلالة نفي سؤال الأجر في قوله تعالى: ﴿لا أسألكم عليه أجرًا﴾؟","answer":"دل على صدق الرسول وتجرده في البلاغ، وأن دعوته ليست طلبًا لمال أو منفعة من قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص339، تحت عنوان «دلالة نفي سؤاله الأجر»","url":""}]},{"id":"s6-1256","number":1256,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"ما بلاغة التعبير في قوله تعالى: ﴿قل لا أسألكم عليه أجرًا﴾؟","answer":"جاء الأمر بالقول إعلانًا مباشرًا لنزاهة الدعوة، ووافق هدي الأنبياء الذين يبلغون بلا عوض.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص339–340، تحت عنوان «بلاغة التعبير في قل لا أسألكم عليه أجرًا»","url":""}]},{"id":"s6-655","number":655,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"لماذا حصر القرآن أو الهدى في قوله: ﴿إن هو إلا ذكرى للعالمين﴾؟","answer":"القصر بالنفي والاستثناء قصر إضافي: مهمة الرسول والقرآن تجاه المخاطبين التذكير لا طلب الأجر. ولا ينفي ما للقرآن من هداية وتشريع ووظائف أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص341، تحت «بلاغة أسلوب القصر»","url":""}]},{"id":"s6-656","number":656,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"ما فائدة الإخبار عن القرآن بالمصدر في قوله تعالى: ﴿إن هو إلا ذكرى للعالمين﴾؟","answer":"أُخبر بالمصدر ﴿ذكرى﴾ للمبالغة، فكأن القرآن هو التذكير نفسه لا مجرد كلام يذكّر أحيانًا، وإضافته للعالمين تدل على عموم الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص341، تحت «بلاغة الإخبار بالمصدر مضافًا للعالمين في ذكرى للعالمين»","url":""}]},{"id":"s6-657","number":657,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما بلاغة المجاز في الفعل ﴿قدروا﴾ في قوله تعالى: ﴿وما قدروا الله حق قدره﴾؟","answer":"نقل التقدير من معرفة مقدار الأشياء إلى معرفة جلال الله وتعظيمه، فدل على أنهم لم يعرفوا حكمته وصفاته حق المعرفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص350–351، تحت عنوان «بلاغة المجاز في الفعل قدروا»","url":""}]},{"id":"s6-1257","number":1257,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما دلالة ظرف الزمان ﴿إذ قالوا﴾؟","answer":"جعل قولهم: ﴿ما أنزل الله على بشر من شيء﴾ وقتًا ظهر فيه نقص تعظيمهم لله، فربط الحكم بدليله المكشوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص352، تحت عنوان «دلالة ظرف الزمان إذ قالوا»","url":""}]},{"id":"s6-658","number":658,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"لماذا أضيف ﴿حق﴾ إلى ﴿قدره﴾؟","answer":"إضافة ﴿حق﴾ إلى ﴿قدره﴾ تؤكد المقدار الواجب من المعرفة والتعظيم، وتفظع جهلهم؛ إذ لم ينقصوا بعض حقه فحسب، بل نفوا أصل ما يليق به من إرسال الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص351–352، تحت «سر إضافة الحق إلى القدر في حق قدره»","url":""}]},{"id":"s6-659","number":659,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما دلالة الكناية بنفي معرفتهم قدر الله؟","answer":"كنى عن نقص تعظيمهم لله بإنكارهم الوحي؛ فمن عرف حكمته ورحمته وصفة كلامه لم ينف إرسال الرسل وإنزال الكتب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص350، تحت عنوان «دلالة الكناية بنفي معرفتهم قدر الله»","url":""}]},{"id":"s6-1258","number":1258,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما دلالة إسناد الإنزال إلى الله في قولهم: ﴿ما أنزل الله على بشر من شيء﴾؟","answer":"الإسناد صريح في أن دعواهم تنفي أصل الوحي من عند الله، ولذلك كان قولهم جهلًا بصفته وحكمته لا مجرد إنكار كتاب بعينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص354، تحت عنوان «دلالة إسناد الإنزال إلى الله»","url":""}]},{"id":"s6-660","number":660,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"لماذا عبر بلفظ ﴿بشر﴾ وعدل عن رجل أو رسول أو إنسان؟","answer":"حكى نظرهم إلى الأنبياء من جهة الجسد البشري بقصد الحط من شأنهم وتجريدهم من مزية الرسالة، وعم جنس البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص354، تحت عنوان «سر التعبير بقوله بشر والعدول عن رجل أو رسول أو إنسان»","url":""}]},{"id":"s6-1259","number":1259,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما دلالة دخول ﴿من﴾ على النكرة في سياق النفي؟","answer":"أكدت الاستغراق، فصار زعمهم نفي إنزال أي شيء على أي بشر من غير استثناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص355، تحت عنوان «دخول من على النكرة في سياق النفي»","url":""}]},{"id":"s6-661","number":661,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما أثر دخول ﴿من﴾ على النكرة في قوله تعالى: ﴿من شيء﴾؟","answer":"نصت على استغراق النفي، فأبطلت دعواهم إنزال أدنى شيء فضلًا عن كتاب عظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص355، تحت عنوان «دخول من على النكرة في سياق النفي»","url":""}]},{"id":"s6-1260","number":1260,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما فائدة تنكير ﴿شيء﴾ في قوله تعالى: ﴿ما أنزل الله على بشر من شيء﴾؟","answer":"عم التنكير كل منزل قل أو كثر، فظهر غلو قولهم وشموله لما يعرفون من كتب الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص355، تحت عنوان «فائدة تنكير شيء للعموم»","url":""}]},{"id":"s6-662","number":662,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"لماذا كان الرد سؤالًا: ﴿قل من أنزل الكتاب الذي جاء به موسى﴾؟","answer":"جاء الرد سؤالًا ليُلزمهم بما يقرون به من كتاب موسى: إن أنكروا كل وحي فمن أنزل التوراة؟ فالدليل مأخوذ من أصل مسلم عندهم، ولا يسعهم دفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص356–357، تحت «دلالة الاستفهام وغرضه في من أنزل الكتاب الذي جاء به موسى»","url":""}]},{"id":"s6-663","number":663,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما بلاغة استعارة النور للوضوح والبيان في وصف كتاب موسى؟","answer":"شبه الكتاب بالنور لأنه يكشف الحق ويبدد ظلمة الباطل والجهل، فصور أثر الوحي في الإدراك والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص358، تحت عنوان «بلاغة استعارة النور للوضوح والبيان»","url":""}]},{"id":"s6-1261","number":1261,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما دلالة الجمع بين النور والهدى في قوله تعالى: ﴿نورًا وهدى للناس﴾؟","answer":"النور يكشف الطريق ويبين الحق، والهدى يدل عليه ويوصل إلى العمل؛ فجمع الوصفان البيان والإرشاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص359، تحت عنوان «دلالة الجمع بين النور والهدى»","url":""}]},{"id":"s6-1262","number":1262,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما دلالة التعريف في لفظ ﴿الناس﴾ في قوله تعالى: ﴿وهدى للناس﴾؟","answer":"حمل التعريف على الناس المعهودين في السياق، وهم قوم موسى بنو إسرائيل الذين نزل الكتاب لهدايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص359، تحت عنوان «دلالة التعريف في لفظ الناس»","url":""}]},{"id":"s6-664","number":664,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿تجعلونه قراطيس﴾، فجعل الكتاب نفسه أوراقًا متفرقة؟","answer":"ليس الذم لمجرد كتابة الكتاب في أوراق، بل لأنهم جزؤوه قراطيس متفرقة ليظهروا ما وافق أغراضهم ويخفوا كثيرًا؛ فالتجزئة وسيلة للتلاعب بالوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص360–361، تحت «وجه ذم جعلهم الكتاب قراطيس في تجعلونه قراطيس»","url":""}]},{"id":"s6-665","number":665,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما وجه ذم جعلهم الكتاب قراطيس؟","answer":"ذم تفريقهم الكتاب الواحد في صحائف بما مكنهم من إظهار بعضه وإخفاء بعضه بدل عرضه كاملًا والعمل به.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص360–361، تحت عنوان «وجه ذم جعلهم الكتاب قراطيس»","url":""}]},{"id":"s6-1263","number":1263,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما فائدة وصف القراطيس بجملتي ﴿تبدونها وتخفون كثيرًا﴾؟","answer":"كشفت الجملتان غرض التفريق ونتيجته: إبداء ما يوافق أهواءهم وإخفاء كثير من الحق، فصار الوصف توبيخًا عمليًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص360–361، تحت عنوان «فائدة وصف القراطيس بجملتي تبدونها وتخفون كثيرًا»","url":""}]},{"id":"s6-666","number":666,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما سرّ إطلاق الإبداء وتقييد الإخفاء بالكثرة في قوله تعالى: ﴿تبدونها وتخفون كثيرًا﴾؟","answer":"دلّ قوله ﴿وتخفون كثيرًا﴾ على أن المخفي من الكتاب كثير، وأن ما أبدوه قليل لا يرفع عنهم ذم الكتمان والتلاعب؛ فالمقصود إبراز عظم ما أخفوه لا مجرد وقوع الإخفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص362، تحت «نكتة إطلاق الإبداء وتقييد الإخفاء بالكثرة»","url":""}]},{"id":"s6-667","number":667,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿وعلمتم ما لم تعلموا أنتم ولا آباؤكم﴾، وأظهر ﴿أنتم﴾؟","answer":"أُظهر ضمير ﴿أنتم﴾ مع دلالة الفعل عليه لتوكيد اختصاص المخاطبين بالامتنان، ثم عطف الآباء لنفي أن يكون هذا العلم موروثًا عنهم؛ فهو من تعليم الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص365، تحت «فائدة الضمير المنفصل أنتم ودلالة عطف ولا آباؤكم»","url":""}]},{"id":"s6-668","number":668,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما بلاغة المبادرة بالجواب عن الاستفهام التقريري في قوله تعالى: ﴿قل الله﴾؟","answer":"أمر الرسول أن يتولى الجواب لأن المسؤول لا يسعه إنكار الحقيقة وقد يعاند أو يتهرب، فحسم التقرير وألزمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص366، تحت عنوان «بلاغة المبادرة بالجواب عن الاستفهام التقريري»","url":""}]},{"id":"s6-1264","number":1264,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما نكتة الإيجاز في جواب ﴿قل الله﴾؟","answer":"اقتصر على اسم الجلالة لأن الجواب لا يحتمل غيره، فجمع كلمة واحدة حسم الحجة وتعجيل الفائدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص366–367، تحت عنوان «نكتة الإيجاز في الجواب في قل الله»","url":""}]},{"id":"s6-669","number":669,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما دلالة العطف بـ﴿ثم﴾ في قوله تعالى: ﴿ثم ذرهم﴾؟","answer":"أفادت الترتيب الرتبي؛ فبعد إقامة الحجة وقطع المعاذير يأتي تركهم في باطلهم تهديدًا، لا ترك دعوتهم قبل البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص367، تحت عنوان «دلالة العطف بثم»","url":""}]},{"id":"s6-1265","number":1265,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما بلاغة المجاز في الأمر بتركهم؟","answer":"ليس المراد إهمال الدعوة، بل التهديد واليأس من انتفاع المعاندين بعد البيان، فكأنهم يتركون لعاقبة خوضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص367–368، تحت عنوان «بلاغة المجاز في الأمر بتركهم»","url":""}]},{"id":"s6-670","number":670,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿في خوضهم﴾؟","answer":"شبه دخولهم في الكلام الباطل بالخوض في الماء؛ لما فيه من إحاطة واضطراب واندفاع من غير بصيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص370، تحت عنوان «بلاغة الاستعارة في خوضهم»","url":""}]},{"id":"s6-1266","number":1266,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما دلالة التعبير عن عنادهم باللعب؟","answer":"صور فعلهم عملًا بلا غاية نافعة، يكشف عبثهم بالحق وانصرافهم عن الجد والحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص370، تحت عنوان «دلالة التعبير عن عنادهم باللعب»","url":""}]},{"id":"s6-671","number":671,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما سرّ التعبير في قوله تعالى عن أهل الكتاب: ﴿تخفون كثيرًا﴾، ويعبّر القرآن في مواضع أخرى عن صنيعهم بالكتمان؟","answer":"الكتمان سكوت عن المعاني والأخبار، أما الإخفاء فأعم، ويستعمل في المعاني والمحسوسات. وعُبّر هنا بالإخفاء لأن المخفي آيات متلوة في التوراة، لا مجرد معانٍ أو أسرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص373–374، تحت «الفروق المعجمية: الكتمان والإخفاء»","url":""}]},{"id":"s6-672","number":672,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿وهذا كتاب أنزلناه مبارك﴾ باسم الإشارة؟","answer":"اسم الإشارة للقريب يستحضر القرآن كأنه حاضر مشاهد، ولا سيما بعد جدالهم في نزول الوحي، ويزيد المشار إليه تمييزًا وتفخيمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص378–379، تحت «سر إيثار اسم الإشارة هذا»","url":""}]},{"id":"s6-673","number":673,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما الغرض من وصف الكتاب بأنه ﴿مبارك﴾؟","answer":"أكد كثرة خير القرآن وثبات نفعه ودوامه، وأن بركته لازمة له لأنه منزل من عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص379، تحت عنوان «الغرض من وصف الكتاب بأنه مبارك»","url":""}]},{"id":"s6-1267","number":1267,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما علة التعبير عن الإنزال بالفعل وعن البركة بالاسم؟","answer":"جاء الإنزال فعلًا لأنه حدث وقع وتجددت آثاره، وجاءت البركة اسمًا لأنها صفة ثابتة ملازمة للكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص380–381، تحت عنوان «علة التعبير عن الإنزال بالفعل وعن البركة بالاسم في الآية»","url":""}]},{"id":"s6-674","number":674,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما وجه تصديق القرآن للكتب السابقة؟","answer":"وافق أصول الوحي ووعد الكتب السابقة بالنبي، وأظهر صدقها فيما بقي حقًا فيها مع هيمنته عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص383، تحت عنوان «وجه تصديق القرآن للكتب السابقة بقوله: ﴿مصدق الذي بين يديه﴾»","url":""}]},{"id":"s6-1268","number":1268,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما دلالة التعبير عن الكتب السابقة بقوله تعالى: ﴿بين يديه﴾؟","answer":"كنى عما تقدمه من الكتب القريبة المتداولة، وهو أخص من مطلق ما قبله الذي يشمل السابق القريب والبعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص383–384، تحت عنوان «التعبير عن الكتب السابقة بقوله تعالى: ﴿بين يديه﴾»","url":""}]},{"id":"s6-675","number":675,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"لماذا أفرد الموصول: ﴿الذي بين يديه﴾؟","answer":"أُفرد الموصول ﴿الذي﴾ مع أن المراد كتب الوحي السابقة لأن جمع غير العاقل يجوز التعبير عنه بالمفرد؛ والمقصود ما تقدم من كتب الأنبياء، وبخاصة التوراة والإنجيل والزبور والصحف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص383–384، تحت «التعبير بالموصول المفرد الذي عن الكتب»","url":""}]},{"id":"s6-676","number":676,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما بلاغة استعارة لفظ ﴿أم القرى﴾ لمكة؟","answer":"شبهت مكة بالأم لأنها أصل القرى ومرجعها وأعظمها شأنًا، وفيها أول بيت وقبلة الناس ومحجهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص384، تحت عنوان «بلاغة استعارة لفظ ﴿أم القرى﴾»","url":""}]},{"id":"s6-1269","number":1269,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"لماذا أوثر التعبير بـ﴿أم القرى﴾ دون مكة؟","answer":"أبرز الاسم مكانتها المركزية وعمق صلتها بما حولها، فناسب بدء الإنذار منها وامتداده إلى سائر البلاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص385، تحت عنوان «إيثار التعبير بأم القرى دون مكة»","url":""}]},{"id":"s6-677","number":677,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما دلالة الجمع بين عموم الرسالة وخصوص مبدئها في قوله تعالى: ﴿ومن حولها﴾؟","answer":"بدأ الإنذار بأم القرى وما حولها بحسب مكان النزول، لكن اللفظ لا يحصر الرسالة في المحيط القريب؛ فهو مبدأ البلاغ لا غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص386، تحت عنوان «الدلالة على عموم الرسالة وخصوصها في ومن حولها»","url":""}]},{"id":"s6-1270","number":1270,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما دلالة إيجاز القصر في قوله تعالى: ﴿أم القرى ومن حولها﴾؟","answer":"جمع التعبير القليل مركز الدعوة ومجال امتدادها، فدل على إنذار مكة وسائر البلاد المحيطة بها من غير تعداد طويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص386–387، تحت عنوان «دلالة إيجاز القصر»","url":""}]},{"id":"s6-678","number":678,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿والذين يؤمنون بالآخرة يؤمنون به﴾، فجعل الإيمان بالآخرة سببًا للإيمان بالقرآن؟","answer":"من أيقن بالبعث والجزاء عظمت رغبته في الثواب ورهبته من العقاب، فحمله ذلك على النظر في دلائل النبوة والإيمان بالقرآن الذي أبرز مشاهد الآخرة وقررها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص388–389، تحت «تلازم الإيمان بالآخرة والقرآن»","url":""}]},{"id":"s6-679","number":679,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما وجه تخصيص الصلاة بالذكر بعد الإيمان بالآخرة؟","answer":"لأن الصلاة أعظم العبادات الظاهرة بعد الإيمان بالله، وهي صلة بالرب ووسيلة للفوز بالجنة، فكانت علامة جامعة للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص390، تحت عنوان «وجه تخصيص الصلاة بالذكر»","url":""}]},{"id":"s6-1271","number":1271,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما علة تقديم الجار والمجرور في قوله تعالى: ﴿وهم على صلاتهم يحافظون﴾؟","answer":"قدم للعناية والاختصاص، فبرزت الصلاة موضع محافظتهم الدائمة، ودل ذلك على شدة تعاهدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص390–391، تحت عنوان «علة تقديم الجار والمجرور»","url":""}]},{"id":"s6-680","number":680,"surah":6,"verses":[92],"references":[{"surah":6,"verses":[92]}],"verseLabel":"الأنعام: 92","question":"ما الذي يفيده لفظ ﴿يحافظون﴾ زيادة على مجرد أداء الصلاة؟","answer":"المحافظة تعهّد ومداومة؛ فالصلاة عهد بين العبد وربه، والمحافظة عليها رعاية لهذا العهد وحفظ له. لذلك يدل اللفظ على عناية مستمرة تتجاوز مجرد وقوع الأداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص390–391، تحت «إيثار لفظ يحافظون دون غيره»","url":""}]},{"id":"s6-681","number":681,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"ما فائدة تكرار ﴿من﴾ في ﴿ومن قال سأنزل مثل ما أنزل الله﴾ بعد ﴿ممن افترى على الله كذبًا أو قال أوحي إلي﴾؟","answer":"يفيد التكرار استقلال هذا النوع من الافتراء بالذم؛ فلا يتوقف وصف الشخص بأنه من أظلم الناس على جمع الصفات المذكورة كلها، بل يكفي ارتكاب واحدة منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص405، تحت «علة تكرار الموصول من في الآية الكريمة»","url":""}]},{"id":"s6-682","number":682,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"لماذا جُعل الظلم محور الاستفهام في قوله تعالى: ﴿ومن أظلم ممن افترى على الله كذبًا﴾؟","answer":"جعل الظلم محور الاستفهام ليقرر أنه لا أحد أشد ظلمًا ممن اختلق على الله كذبًا؛ لأن جنايته تجمع إفساد الاعتقاد والتقول على الخالق وتضليل الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص400، تحت عنوان «إيثار الظلم ليكون محور الاستفهام»","url":""}]},{"id":"s6-1272","number":1272,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"لماذا عُطفت جملة ﴿أو قال أوحي إلي ولم يوح إليه شيء﴾ على الافتراء؟","answer":"فصل العطف نوعًا خاصًا غليظًا من الافتراء العام، وهو ادعاء نزول الوحي مع انتفائه، فأفرده بالذكر لعظم جريمة ادعاء النبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص401–402، تحت عنوان «بلاغة عطف جملة أو قال أوحي إلي»","url":""}]},{"id":"s6-683","number":683,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"لماذا بُني ﴿أوحي﴾ و﴿يوح﴾ للمجهول؟","answer":"بُني الفعلان للمجهول لأن موضع الإنكار هو وقوع الوحي أو انتفاؤه، لا تعيين الموحي؛ فالفاعل معلوم وهو الله، وذكره لا يضيف إلى مقصد تكذيب المدعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص403، تحت «دلالة بناء الفعلين للمفعول في أو قال أوحي إلي ولم يوح إليه شيء»","url":""}]},{"id":"s6-684","number":684,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"ما فائدة تعقيب دعوى ﴿أوحي إلي﴾ بجملة ﴿ولم يوح إليه شيء﴾؟","answer":"جاءت الجملة حالًا تكشف كذب الدعوى وتناقضها؛ فهي تقيد الذم بمن يدعي الوحي مع انتفائه عنه، وتمنع أن يدخل في هذا الوصف الأنبياء الصادقون الذين أوحى الله إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص403–404، تحت «علة تقييد الجملة بالحال»","url":""}]},{"id":"s6-685","number":685,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"ما دلالة نسبة المفتري الإنزال إلى نفسه في قوله: ﴿سأنزل مثل ما أنزل الله﴾؟","answer":"استعمل المفتري لفظ الإنزال ادعاء لمماثلة فعل الله والتعالي على القرآن؛ فهو يزعم أنه سيأتي بكلام منزل مثله، وفي العبارة كشف لعظم جرأته واستكباره.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص405–406، تحت «فائدة السين في سأنزل وإيثار التعبير بفعل الإنزال»","url":""}]},{"id":"s6-686","number":686,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"لماذا حُذف جواب ﴿لو﴾ في ﴿ولو ترى إذ الظالمون في غمرات الموت﴾؟","answer":"حُذف جواب ﴿لو﴾ لتهويل المشهد وترك النفس تقدر ما لا يحيط به وصف، وتقديره: لرأيت أمرًا عظيمًا أو فظيعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص411، تحت «بلاغة حذف جواب الشرط في قوله: ﴿ولو ترى إذ الظالمون﴾»","url":""}]},{"id":"s6-687","number":687,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿في غمرات الموت﴾؟","answer":"استعيرت الغمرات لشدائد الموت لأنها تغمر الإنسان وتحيط به كما يغمره الماء، فصورت تمكن الشدة منه وعجزه عن دفعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص410، تحت عنوان «بلاغة الاستعارة في غمرات الموت»","url":""}]},{"id":"s6-1273","number":1273,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"لماذا جُمعت ﴿غمرات﴾ في قوله تعالى: ﴿في غمرات الموت﴾؟","answer":"دل الجمع على تعدد الشدائد وأصنافها، أو على تعدد من تنزل بهم، فزاد تصوير أهوال الموت قوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص410، تحت عنوان «علة التعبير بصيغة الجمع»","url":""}]},{"id":"s6-688","number":688,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"ما الصورة التي يكشفها التعبير عن قبض الأرواح ببسط الأيدي في ﴿والملائكة باسطو أيديهم﴾؟","answer":"بسط الأيدي كناية عن العنف في قبض أرواح الظالمين؛ فيصور الأخذ الشديد وما يلقونه عند النزع من شدة، بما يلائم مقام الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص411–412، تحت «بلاغة التعبير عن شدة الموت ببسط الأيدي في الآية»","url":""}]},{"id":"s6-689","number":689,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"ما وجه الأمر في ﴿أخرجوا أنفسكم﴾ مع أن إخراج الروح ليس بأيديهم؟","answer":"الأمر في ﴿أخرجوا أنفسكم﴾ مجازي، لا أمر حقيقيًا بما يقدرون عليه؛ وهو تصوير لعنف الملائكة وإلحاحهم وتشديدهم في قبض الأرواح من غير تنفيس ولا إمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص412–413، تحت «دلالة الأمر على أغراض مجازية في أخرجوا أنفسكم»","url":""}]},{"id":"s6-690","number":690,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"ما نكتة إضافة العذاب إلى الهوان في قوله تعالى: ﴿عذاب الهون﴾؟","answer":"جعلت الإضافة الهوان ملازمًا للعذاب ومن صميم أثره؛ فهو يجمع الألم والذل جزاء الاستكبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص415، تحت عنوان «نكتة إضافة العذاب إلى الهوان»","url":""}]},{"id":"s6-1274","number":1274,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"لماذا قيل ﴿عذاب الهون﴾ بدل وصف العذاب بأنه مهين؟","answer":"الإضافة أبلغ في تمكن الهوان وثبوته في العذاب من مجرد الوصف، فناسبت شدة الجزاء لمن استكبر عن آيات الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص415، تحت عنوان «إيثار إضافة العذاب إلى الهوان على الوصف به»","url":""}]},{"id":"s6-691","number":691,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"ما سرّ التعبير بـ﴿غير الحق﴾ في ﴿بما كنتم تقولون على الله غير الحق﴾ بدل لفظ الباطل؟","answer":"التعبير ينفي عن أقوالهم موافقة الحق نفيًا شاملًا، فيتناول ضروب افترائهم وكفرهم. وذكر الحق مع نفيه عن كلامهم أبلغ في إبراز خلوه منه وثبوت ضده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص417–418، تحت «إيثار التعبير بغير الحق دون الباطل»","url":""}]},{"id":"s6-692","number":692,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"ما بلاغة عطف قوله تعالى: ﴿وكنتم عن آياته تستكبرون﴾ على القول غير الحق؟","answer":"أثبت العطف سببًا مستقلًا للعذاب: فالقول غير الحق فساد باللسان، والاستكبار رفض عملي لقبول الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص418، تحت عنوان «بلاغة العطف وكنتم عن آياته تستكبرون»","url":""}]},{"id":"s6-1275","number":1275,"surah":6,"verses":[93],"references":[{"surah":6,"verses":[93]}],"verseLabel":"الأنعام: 93","question":"ما سر تكرار ﴿كنتم﴾ عند ذكر القول غير الحق والاستكبار؟","answer":"أكد التكرار استقلال كل خصلة واستمرارها فيهم، وأن كل واحدة منهما سبب قائم لاستحقاق العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص418–419، تحت عنوان «سر تكرار كنتم»","url":""}]},{"id":"s6-693","number":693,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿ولقد جئتمونا فرادى﴾، مع أن الخلق يُحشرون جميعًا؟","answer":"يجيئون منفردين عن الأموال والأولاد والأنصار وما تعلقوا به في الدنيا؛ فاجتماعهم في المحشر لا ينافي انفراد كل منهم عن أسباب قوته ومعونته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص429–430، تحت «العدول عن لفظ وحدكم إلى فرادى»","url":""}]},{"id":"s6-694","number":694,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"ما وجه المقابلة بين ضمير التعظيم في ﴿جئتمونا﴾ ووصف مجيئهم بـ﴿فرادى﴾؟","answer":"ضمير التعظيم يبرز جلال من يرجعون إليه وعظمة شأنه، في حين يصور ﴿فرادى﴾ ضعفهم وانفرادهم عما كانوا يستندون إليه؛ فتظهر مهابة المقام ومهانة المقبلين عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص430، تحت «نكتة التعبير بضمير الجمع مع إفراد لفظة فرادى»","url":""}]},{"id":"s6-695","number":695,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"لماذا شُبه الحشر بالخلق الأول: ﴿كما خلقناكم أول مرة﴾؟","answer":"شُبه حالهم عند الحشر بحالهم أول خلقهم: يجيئون منفردين عما كان لهم من مال وولد وخدم وأعوان. فوجه التشبيه تجردهم من تلك الأسباب في الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص431، تحت «بلاغة التشبيه كما خلقناكم أول مرة»","url":""}]},{"id":"s6-696","number":696,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿وتركتم ما خولناكم وراء ظهوركم﴾، فجعل النعم وراء الظهر؟","answer":"التعبير كناية عن مفارقة النعم مفارقةً تامة؛ فما كان محيطًا بهم وفي أيديهم صار متروكًا خلفهم لا يملكون الرجوع إليه ولا الانتفاع به.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص432–433، تحت «بلاغة الكناية في وراء ظهوركم»","url":""}]},{"id":"s6-697","number":697,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"ما الذي يضيفه لفظ ﴿خولناكم﴾ إلى معنى العطاء؟","answer":"التخويل أخص من مجرد العطاء؛ فهو إعطاء الشيء وتمليك صاحبه إياه مع التعهد والرعاية، وفيه تذكير بأن ما بأيديهم من مال ونعم إنما خوّلهم الله إياه ثم فارقوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص425–426، تحت «شرح المفردات: خولناكم»","url":""}]},{"id":"s6-698","number":698,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"ما بلاغة نفي رؤية الشفعاء في قوله تعالى: ﴿وما نرى معكم شفعاءكم﴾؟","answer":"جاء نفي الرؤية للتهكم وإظهار خيبة دعواهم؛ فالذين زعموا شفاعتهم لا أثر لهم في ذلك المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص433، تحت عنوان «بلاغة نفي رؤية شركائهم وشفعائهم»","url":""}]},{"id":"s6-1276","number":1276,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"لماذا عُبر بالمضارع ﴿نرى﴾ في قوله تعالى: ﴿وما نرى معكم شفعاءكم﴾؟","answer":"استحضر المضارع غياب الشفعاء في موقف الحساب وجدّد تقريع المشركين كلما التمسوا أثرهم فلم يجدوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص433–434، تحت عنوان «إيثار التعبير بالفعل المضارع في قوله: ﴿وما نرى معكم شفعاءكم﴾»","url":""}]},{"id":"s6-699","number":699,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"ما نكتة وصف الآلهة بالاسم الموصول في قوله تعالى: ﴿الذين زعمتم﴾؟","answer":"عرّفهم بالصلة التي تفضح منشأ منزلتهم؛ فلم تثبت لهم شركة، وإنما قامت على زعم المشركين وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص435، تحت عنوان «نكتة وصف الآلهة بالاسم الموصول»","url":""}]},{"id":"s6-1277","number":1277,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"ما الغرض من جملة الصلة ﴿زعمتم أنهم فيكم شركاء﴾؟","answer":"سجلت الصلة دعواهم عليهم وقررت بطلانها في مشهد غاب فيه الشفعاء، فصارت سببًا مباشرًا لتقريعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص435–436، تحت عنوان «الغرض من جملة الصلة»","url":""}]},{"id":"s6-1278","number":1278,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"ما علة تقديم الجار والمجرور ﴿فيكم﴾ في قوله تعالى: ﴿زعمتم أنهم فيكم شركاء﴾؟","answer":"قدّم للاهتمام بموضع دعوى الشركة؛ أي في شأنكم وعبادتكم وما خصصتموه لهم من نصيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص436–437، تحت عنوان «علة تقديم الجار والمجرور في قوله: ﴿زعمتم أنهم فيكم شركاء﴾»","url":""}]},{"id":"s6-700","number":700,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"ما بلاغة استعارة التقطيع للبعد في قوله تعالى: ﴿لقد تقطع بينكم﴾؟","answer":"صوّرت الروابط الموهومة بين العابدين ومعبوداتهم شيئًا موصولًا ثم قطع، فدلّت على زوال الصلات والأسباب تمامًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص437، تحت عنوان «بلاغة استعارة لفظ التقطيع للبعد في قوله: ﴿لقد تقطع بينكم﴾»","url":""}]},{"id":"s6-1279","number":1279,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"ما دلالة تأكيد الخبر في قوله تعالى: ﴿لقد تقطع بينكم﴾؟","answer":"أكد الخبر باللام و﴿قد﴾ لتثبيت وقوع الانقطاع ودفع ما رسخ في أوهامهم من بقاء صلة أو شفاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص437، تحت عنوان «دلالة تأكيد الخبر في قوله: ﴿لقد تقطع بينكم﴾»","url":""}]},{"id":"s6-701","number":701,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"لماذا خُتم بقوله: ﴿وضل عنكم ما كنتم تزعمون﴾؟","answer":"تؤكد الخاتمة انقطاع ما توهموه من صلات؛ فقد غاب عنهم ما كانوا يزعمونه من شفاعة وشركة، فلم يجدوا شيئًا من ذلك عند الحاجة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص439، تحت «فائدة التعبير بالضلال»","url":""}]},{"id":"s6-702","number":702,"surah":6,"verses":[95],"references":[{"surah":6,"verses":[95]}],"verseLabel":"الأنعام: 95","question":"ما المعنى اللغوي لوصف الله تعالى بأنه ﴿فالق الحب والنوى﴾؟","answer":"الفالق هو الشاق؛ أي يشق الحب والنوى فيخرج منهما النبات مع صلابة الغلاف وضعف الخارج منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص443–444، تحت عنوان «شرح المفردات: فالق»","url":""}]},{"id":"s6-1280","number":1280,"surah":6,"verses":[95],"references":[{"surah":6,"verses":[95]}],"verseLabel":"الأنعام: 95","question":"ما نكتة التعبير باسم الفاعل ﴿فالق﴾؟","answer":"دل اسم الفاعل على ثبوت القدرة وتجدد أثرها، واستحضر هيئة شق الحب والنوى كلما خرج النبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص447، تحت عنوان «نكتة التعبير باسم الفاعل فالق»","url":""}]},{"id":"s6-1281","number":1281,"surah":6,"verses":[95],"references":[{"surah":6,"verses":[95]}],"verseLabel":"الأنعام: 95","question":"ما الفرق بين الفصل والفرق والفلق والفتق؟","answer":"الفصل إبانة بين شيئين، والفرق تمييز وانفصال، والفلق شق مع إظهار ما في الداخل، والفتق فتح ما كان ملتئمًا؛ فاختير الفلق لمشهد خروج النبات من الحب والنوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص455، تحت عنوان «الفروق المعجمية: الفصل والفرق والفلق والفتق»","url":""}]},{"id":"s6-703","number":703,"surah":6,"verses":[95],"references":[{"surah":6,"verses":[95]}],"verseLabel":"الأنعام: 95","question":"ما المراد بالحب والنوى في قوله تعالى: ﴿فالق الحب والنوى﴾؟","answer":"الحب أصل الزروع والحبوب، والنوى أصل كثير من الأشجار والثمار، فجمعهما التعبير في دلائل الإنبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص443–444، تحت عنوان «شرح المفردات: الحب والنوى»","url":""}]},{"id":"s6-1282","number":1282,"surah":6,"verses":[95],"references":[{"surah":6,"verses":[95]}],"verseLabel":"الأنعام: 95","question":"ما سر تقديم الحب على النوى في قوله تعالى: ﴿فالق الحب والنوى﴾؟","answer":"قدم الحب لكثرة تعلق أقوات الناس به وشدة حاجتهم إلى الزروع، ثم عطف عليه النوى المستخرج منه الأشجار والثمار.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص448، تحت عنوان «تقديم الحب على النوى»","url":""}]},{"id":"s6-704","number":704,"surah":6,"verses":[95],"references":[{"surah":6,"verses":[95]}],"verseLabel":"الأنعام: 95","question":"ما دلالة التنويع بين الفعلية والاسمية في قوله تعالى: ﴿يخرج الحي من الميت ومخرج الميت من الحي﴾؟","answer":"استحضر الفعل تجدد إخراج الحي، وأثبت اسم الفاعل صفة إخراج الميت ودوام القدرة عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص449–450، تحت عنوان «دلالة التنويع بين الفعلية والاسمية في ﴿يخرج﴾ و﴿ومخرج﴾»","url":""}]},{"id":"s6-1283","number":1283,"surah":6,"verses":[95],"references":[{"surah":6,"verses":[95]}],"verseLabel":"الأنعام: 95","question":"ما بلاغة اقتران الفعل ﴿يخرج﴾ بالحي واسم الفاعل ﴿مخرج﴾ بالميت؟","answer":"ناسب الفعل الحياة بما فيها من حركة وتجدد، وناسب الاسم الموت بما فيه من ثبات وسكون، فتلاءم المبنى مع المعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص450–451، تحت عنوان «بلاغة اقتران الفعل ﴿يخرج﴾ بالحي، والاسم ﴿مخرج﴾ بالميت»","url":""}]},{"id":"s6-705","number":705,"surah":6,"verses":[95],"references":[{"surah":6,"verses":[95]}],"verseLabel":"الأنعام: 95","question":"ما سرّ تقديم إخراج الحي من الميت؟","answer":"قُدّم إخراج الحي من الميت لأن وقوعه أكثر والعناية به أكمل، ولأنه المشاهد المحسوس أولًا؛ ثم عطف عليه إخراج الميت من الحي استكمالًا لوجهي القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص451، تحت «بلاغة التقديم، وسر اختلاف الصيغة في الآية الكريمة»","url":""}]},{"id":"s6-706","number":706,"surah":6,"verses":[95],"references":[{"surah":6,"verses":[95]}],"verseLabel":"الأنعام: 95","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلكم الله﴾ بعد عرض ظاهرة النبات؟","answer":"اسم الإشارة يلخّص الدليل ويعين صاحبه: الفاعل لهذه الخوارق المشاهدة هو الله وحده، وفي البعد تعظيم لشأنه ورفع لمنزلته عن الشركاء المزعومين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص453، تحت «بلاغة التعبير باسم الإشارة، بمجيئه جمعًا ﴿ذلكم﴾»","url":""}]},{"id":"s6-707","number":707,"surah":6,"verses":[95],"references":[{"surah":6,"verses":[95]}],"verseLabel":"الأنعام: 95","question":"ما جزالة التعبير بـ﴿أنى﴾ في قوله تعالى: ﴿فأنى تؤفكون﴾؟","answer":"جمعت ﴿أنى﴾ سؤال الجهة والكيفية مع الإنكار والتعجب: من أي وجه وكيف ينصرفون عن الحق بعد ظهور دلائله؟","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص454، تحت عنوان «جزالة التعبير بأنى»","url":""}]},{"id":"s6-1284","number":1284,"surah":6,"verses":[95],"references":[{"surah":6,"verses":[95]}],"verseLabel":"الأنعام: 95","question":"ما سر بناء ﴿تؤفكون﴾ للمجهول؟","answer":"ركز البناء للمجهول على شدة الصرف عن الحق وفظاعته، مهما يكن سببه، وأشعر بأن حالهم بلغت حدًا يعجب منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص454، تحت عنوان «سر التعبير بتؤفكون مبنيًا للمجهول»","url":""}]},{"id":"s6-708","number":708,"surah":6,"verses":[96],"references":[{"surah":6,"verses":[96]}],"verseLabel":"الأنعام: 96","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿فالق الإصباح﴾؟","answer":"صوّر انبثاق ضوء الصبح من ظلمة الليل بشق يكشف النور، فاستحضر هيئة ظهور الصباح شيئًا فشيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص460–461، تحت عنوان «بلاغة الاستعارة في فالق الإصباح»","url":""}]},{"id":"s6-1285","number":1285,"surah":6,"verses":[96],"references":[{"surah":6,"verses":[96]}],"verseLabel":"الأنعام: 96","question":"ما الفرق بين ﴿فالق الإصباح﴾ و«خالق الصباح»؟","answer":"الخالق يدل على الإيجاد، أما الفالق فيضيف صورة شق الظلمة وانبثاق الضوء منها؛ فكان أدق في تصوير المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص466، تحت عنوان «الفروق المعجمية: فالق وخالق»","url":""}]},{"id":"s6-709","number":709,"surah":6,"verses":[96],"references":[{"surah":6,"verses":[96]}],"verseLabel":"الأنعام: 96","question":"لماذا اختير ﴿الإصباح﴾، لا: الصبح؟","answer":"اختير ﴿الإصباح﴾ لأنه مصدر يدل على ضياء النهار وبياضه المنتشر، وهو أوسع وأعم دلالة من لفظ ﴿الصبح﴾ المقصور على الوقت المعروف المقابل لليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص460–461، تحت «سر إيثار لفظ الإصباح على الصبح»","url":""}]},{"id":"s6-710","number":710,"surah":6,"verses":[96],"references":[{"surah":6,"verses":[96]}],"verseLabel":"الأنعام: 96","question":"كيف وُصف الليل بأنه ﴿سكنًا﴾ والذين يسكنون فيه هم الخلق؟","answer":"الليل ظرف السكون والراحة، فسُمي باسم ما يقع فيه على سبيل المجاز؛ وفي ذلك مبالغة في ملاءمته لسكون الخلق حتى كأنه السكون نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص462–463، تحت «فن المجاز في وجعل الليل سكنًا»","url":""}]},{"id":"s6-711","number":711,"surah":6,"verses":[96],"references":[{"surah":6,"verses":[96]}],"verseLabel":"الأنعام: 96","question":"ما سرّ التعبير باسم الفاعل ﴿فالق﴾ ثم بالفعل ﴿جعل﴾ في وصف الإصباح والليل؟","answer":"عُبر عن فلق الإصباح باسم الفاعل ﴿فالق﴾ لأنه وصف ثابت دائم لا يتقيد بمنتفع، وعُبر عن الليل بـ﴿جعل﴾ لأن جعله سكنًا مقيد بمن ينتفع براحة الليل، وكذلك الانتفاع بالشمس والقمر في الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص462، تحت «فائدة التعبير باسم الفاعل فالق مقابل الفعل جعل»","url":""}]},{"id":"s6-712","number":712,"surah":6,"verses":[96],"references":[{"surah":6,"verses":[96]}],"verseLabel":"الأنعام: 96","question":"ما فائدة وصف الشمس والقمر بالمصدر في ﴿والشمس والقمر حسبانًا﴾؟","answer":"جاء المصدر بمعنى اسم الفاعل، فكأن الشمس والقمر حاسبان، مع أن الناس هم الذين يحسبون بهما. وهذا إسناد مجازي؛ لأنهما سبب معرفة الحساب وضبط الأوقات، فأُسند الحساب إلى سببه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص463–464، تحت «بلاغة التعبير بالمجاز في لفظ الحسبان»","url":""}]},{"id":"s6-713","number":713,"surah":6,"verses":[96],"references":[{"surah":6,"verses":[96]}],"verseLabel":"الأنعام: 96","question":"لماذا خُتمت الآية بـ﴿ذلك تقدير العزيز العليم﴾؟","answer":"﴿العزيز﴾ يناسب القدرة التي لا يعجزها ضبط هذه الأجرام، و﴿العليم﴾ يناسب إحكام مقاديرها ومساراتها؛ فالنظام الكوني تقدير صادر عن قوة وعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص465–466، تحت «نكتة التذييل بصفتي العزيز العليم»","url":""}]},{"id":"s6-714","number":714,"surah":6,"verses":[97],"references":[{"surah":6,"verses":[97]}],"verseLabel":"الأنعام: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿جعل لكم النجوم﴾، فقدم منفعتها للناس؟","answer":"تقديم ﴿لكم﴾ يبرز الامتنان وتسخير النجوم لمصلحة الناس، ويهيئ لبيان منفعتها العملية في الاهتداء، مع بقاء سائر حكم خلقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص470، تحت «دلالة تقديم المتعلق لكم على المفعول به»","url":""}]},{"id":"s6-715","number":715,"surah":6,"verses":[97],"references":[{"surah":6,"verses":[97]}],"verseLabel":"الأنعام: 97","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿ظلمات البر والبحر﴾؟","answer":"استعيرت الظلمات لاشتباه الطرق والحيرة، إلى جانب حقيقتها في ظلمة الليل، فصورت حاجة المسافر إلى الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص471، تحت عنوان «بلاغة الاستعارة في الظلمات»","url":""}]},{"id":"s6-1286","number":1286,"surah":6,"verses":[97],"references":[{"surah":6,"verses":[97]}],"verseLabel":"الأنعام: 97","question":"ما بلاغة إضافة الظلمات إلى البر والبحر؟","answer":"عممت الإضافة مواطن الحيرة في اليابسة والماء، وأظهرت شمول نعمة الاهتداء بالنجوم في كلا المجالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص471–472، تحت عنوان «بلاغة الإضافة في قوله: ﴿ظلمات البر والبحر﴾»","url":""}]},{"id":"s6-716","number":716,"surah":6,"verses":[97],"references":[{"surah":6,"verses":[97]}],"verseLabel":"الأنعام: 97","question":"ما سرّ تقديم البر على البحر في ﴿ظلمات البر والبحر﴾؟","answer":"البر هو الأصل في استقرار الناس ومعيشتهم وأسفارهم، أما ركوب البحر فعارض بالنسبة إلى ذلك؛ فقدم ما هو أصل وأكثر ملازمة لأحوالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص472، تحت «سر تقديم البر على البحر»","url":""}]},{"id":"s6-717","number":717,"surah":6,"verses":[97],"references":[{"surah":6,"verses":[97]}],"verseLabel":"الأنعام: 97","question":"كيف يوجَّه اختلاف الفواصل بين ﴿يعلمون﴾ و﴿يفقهون﴾ و﴿يؤمنون﴾؟","answer":"يناسب العلم العلامات الظاهرة كالنجوم، والفقه ما يحتاج إلى تدبر خفي كأطوار الإنسان، والإيمان ما يقتضي تصديقًا بدلالات القدرة؛ فتلائم كل فاصلة سياقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص473، تحت عنوان «توجيه المتشابه اللفظي في ﴿يعلمون﴾ و﴿يفقهون﴾ و﴿يؤمنون﴾»","url":""}]},{"id":"s6-1287","number":1287,"surah":6,"verses":[97],"references":[{"surah":6,"verses":[97]}],"verseLabel":"الأنعام: 97","question":"ما بلاغة التذييل بقوله تعالى: ﴿لقوم يعلمون﴾ في آية النجوم؟","answer":"ختمت الآية بالعلم لأن الانتفاع بالنجوم قائم على معرفة مواقعها ومساراتها ودلالتها على الجهات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص473–474، تحت عنوان «بلاغة التذييل»","url":""}]},{"id":"s6-718","number":718,"surah":6,"verses":[98],"references":[{"surah":6,"verses":[98]}],"verseLabel":"الأنعام: 98","question":"ما دلالة الفعل ﴿أنشأكم﴾ في قوله تعالى: ﴿وهو الذي أنشأكم من نفس واحدة﴾؟","answer":"يدل الإنشاء على الإيجاد مع التربية والتنمية والانتقال في أطوار التكوين، فناسب نشأة البشر وتدرجها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص475، تحت عنوان «شرح المفردات: أنشأكم»","url":""}]},{"id":"s6-1288","number":1288,"surah":6,"verses":[98],"references":[{"surah":6,"verses":[98]}],"verseLabel":"الأنعام: 98","question":"ما الفرق بين الإنشاء والخلق في هذا السياق؟","answer":"الخلق أعم في أصل الإيجاد والتقدير، والإنشاء يبرز بدء الشيء وتنميته حتى يقوم على حاله؛ لذلك كان أوفق بأطوار الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص484–485، تحت عنوان «الفروق المعجمية: أنشأ وخلق»","url":""}]},{"id":"s6-719","number":719,"surah":6,"verses":[98],"references":[{"surah":6,"verses":[98]}],"verseLabel":"الأنعام: 98","question":"ما فائدة التنصيص على وحدة النفس في ﴿أنشأكم من نفس واحدة﴾ مع كثرة البشر واختلافهم؟","answer":"كثرة البشر وتنوعهم مع نشأتهم من أصل واحد تدل على عظيم القدرة. وفي تذكيرهم بوحدة أصلهم ما يبعث على التراحم والتآلف بدل الفرقة والتناكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص478، تحت «دلالة إنشاء البشر من نفس واحدة»","url":""}]},{"id":"s6-720","number":720,"surah":6,"verses":[98],"references":[{"surah":6,"verses":[98]}],"verseLabel":"الأنعام: 98","question":"ما المعنى اللغوي للمستقر والمستودع؟","answer":"المستقر موضع الثبات وطول المكث، والمستودع موضع الإقامة المؤقتة كالوديعة التي ترد إلى غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص475–476، تحت عنوان «شرح المفردات: مستقر ومستودع»","url":""}]},{"id":"s6-1289","number":1289,"surah":6,"verses":[98],"references":[{"surah":6,"verses":[98]}],"verseLabel":"الأنعام: 98","question":"ما دلالة الجمع بين لفظي المستقر والمستودع؟","answer":"صور اختلاف أحوال الإنسان بين مقام يثبت فيه ومرحلة يمر بها ثم ينتقل عنها، فاستوعب تقلبه في أطوار وجوده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص479، تحت عنوان «دلالات لفظي المستقر والمستودع»","url":""}]},{"id":"s6-721","number":721,"surah":6,"verses":[98],"references":[{"surah":6,"verses":[98]}],"verseLabel":"الأنعام: 98","question":"ما سرّ تقديم ﴿مستقر﴾ على ﴿مستودع﴾؟","answer":"من وجوه ذلك مراعاة الترتيب الزمني على تفسير المستقر بصلب الأب والمستودع برحم الأم؛ فالنطفة تكون في مستقرها أولًا، ثم تصير إلى الرحم، فقدم السابق على اللاحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص481، تحت «بلاغة تقديم المستقر على المستودع»","url":""}]},{"id":"s6-722","number":722,"surah":6,"verses":[98],"references":[{"surah":6,"verses":[98]}],"verseLabel":"الأنعام: 98","question":"ما نكتة التعبير بالفعل ﴿يفقهون﴾ في سياق نشأة الإنسان؟","answer":"دل على فهم يتجاوز ظاهر المشاهدة إلى تدبر خفايا التكوين وتقلب الإنسان بين المستقر والمستودع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص482، تحت عنوان «نكتة التعبير بالفعل يفقهون»","url":""}]},{"id":"s6-1290","number":1290,"surah":6,"verses":[98],"references":[{"surah":6,"verses":[98]}],"verseLabel":"الأنعام: 98","question":"لماذا كان لفظ الفقه أبين من لفظ العلم في هذا الموضع؟","answer":"الفقه علم دقيق نافذ في المعنى، والسياق يعرض أحوالًا خفية تحتاج إلى تدبر أعمق من مجرد إدراك المعلومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص482–483، تحت عنوان «لفظ الفقه أبين في الدلالة من لفظ العلم»","url":""}]},{"id":"s6-723","number":723,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما سرّ تقديم ﴿من السماء﴾ على ﴿ماء﴾ في ﴿أنزل من السماء ماء﴾؟","answer":"في التقديم عناية بمصدر الإنزال وتشويق إلى ما أُنزل؛ فإذا جاء ذكر الماء بعد ترقبه كان أوقع في النفس وأمكن فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص490–491، تحت «بلاغة تقديم المتعلق من السماء على المفعول ماء»","url":""}]},{"id":"s6-724","number":724,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما بلاغة الالتفات من الغيبة في ﴿أنزل﴾ إلى التكلم في ﴿فأخرجنا﴾؟","answer":"انتقل إلى ضمير التعظيم لإبراز العناية بإخراج النبات وتعداد آثاره، وتنشيط السامع بعد جريان الكلام على الغيبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص491، تحت عنوان «بلاغة الالتفات من الغيبة إلى التكلم»","url":""}]},{"id":"s6-1291","number":1291,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما نكتة العدول من الماضي ﴿فأخرجنا﴾ إلى المضارع ﴿نخرج﴾؟","answer":"دل الماضي على تحقق أصل الفعل، واستحضر المضارع تجدده وتكرره في أنواع النبات والثمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص494، تحت عنوان «نكتة العدول من الماضي فأخرجنا إلى المضارع نخرج»","url":""}]},{"id":"s6-725","number":725,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما وجه العموم في ﴿نبات كل شيء﴾، مع أن الموجودات ليست كلها نباتًا؟","answer":"المعنى: أخرج بالماء نبات كل صنف مما ينبت، أو النبات الذي تتعلق به حاجات المخلوقات؛ فلا يراد أن كل موجود نبات، بل عموم أجناس النبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص486–487، تحت «شرح المفردات: نبات»","url":""}]},{"id":"s6-726","number":726,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما سرّ التعبير بـ﴿خضرًا﴾ دون أخضر في وصف النبات؟","answer":"﴿خضرًا﴾ يدل على النبات الغض وتمكن النضارة فيه، ولا يقتصر على مجرد اللون؛ أما أخضر فيصح وصف ما لونه أخضر به وإن لم يكن نباتًا حيًا نضرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص492–493، تحت «سبب العدول من أخضر إلى خضر»","url":""}]},{"id":"s6-727","number":727,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿نخرج منه حبًّا متراكبًا﴾ بالمضارع؟","answer":"المضارع يستحضر إخراج الحب وتراكبه كأنه مشاهد الآن، ويفيد تجدد ذلك؛ فجاء بعد الماضي الذي حكى أصل الإنزال والإخراج ليعرض للسامع صورة حية متجددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص494، تحت «نكتة العدول من الماضي فأخرجنا إلى المضارع نخرج»","url":""}]},{"id":"s6-728","number":728,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما معنى وصف الحب بأنه ﴿متراكبًا﴾؟","answer":"يصوّر حبات السنبل وقد ركب بعضها فوق بعض، كما يشاهد في القمح والشعير.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص486–487، تحت عنوان «شرح المفردات: متراكبًا»","url":""}]},{"id":"s6-1292","number":1292,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما بلاغة أسلوب اللف والنشر في تعداد النبات والثمر؟","answer":"وزع الكلام أنواع الخارج من الماء وصفاتها في نظام يجمع الإجمال ثم التفصيل، فيستحضر تنوع النبات وتناسق أجزائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص493، تحت عنوان «بلاغة أسلوب اللف والنشر في المعنى»","url":""}]},{"id":"s6-729","number":729,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما سرّ التعبير بـ﴿ومن النخل من طلعها﴾ بدل الاقتصار على: ومن طلع النخل؟","answer":"ذُكرت النخل أولًا لاستحضار منافعها على وجه العموم، ثم خُص طلعها بما يخرج منه من القنوان. أما الاقتصار على إضافة الطلع إلى النخل فيوجه النظر إلى منافع الطلع وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص494، تحت «سر العدول من الإضافة إلى التفصيل»","url":""}]},{"id":"s6-730","number":730,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"لماذا أوثرت القنوان القريبة بالذكر على البعيدة؟","answer":"لأن الدانية أسهل تناولًا وأظهر في مقام الامتنان بالثمر الميسر للناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص496، تحت عنوان «إيثار ذكر القنوان القريبة على البعيدة»","url":""}]},{"id":"s6-1293","number":1293,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما سر حذف القنوان البعيدة اختصارًا؟","answer":"دل ذكر الدانية على مقابلها، فاكتفى القرآن بما هو أنسب لمقام النعمة مع إيجاز لا يخل بالمعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص496–497، تحت عنوان «سر حذف القنوان البعيدة اختصارًا»","url":""}]},{"id":"s6-1294","number":1294,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما دلالة لفظ ﴿دانية﴾ في وصف القنوان؟","answer":"يشعر بقرب العذوق وسهولة الوصول إليها، فيزيد تصوير تيسير النعمة والانتفاع بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص497، تحت عنوان «دلالة لفظ دانية»","url":""}]},{"id":"s6-731","number":731,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما سرّ التعبير عن الأعناب بقوله ﴿جنات من أعناب﴾ بدل الاكتفاء بذكر أشجارها؟","answer":"الأعناب ذات أغصان كثيفة تلتف حتى تستر الأرض تحتها؛ فناسبها لفظ الجنات المأخوذ من الستر. والتعبير يستحضر هيئة أشجارها مجتمعة وما تحدثه من ظلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص498، تحت «نكتة التعبير عن الأعناب بالجنات»","url":""}]},{"id":"s6-732","number":732,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿مشتبهًا وغير متشابه﴾، فجمع بين الإثبات والنفي من مادة واحدة؟","answer":"جمع بين ﴿مشتبهًا﴾ و﴿غير متشابه﴾ لأن الثمار تتقارب في بعض الصفات والصور حتى تلتبس، ثم تختلف في صفات أخرى كالطعم واللون؛ فاجتمع التشابه والاختلاف في المخلوق الواحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص498–499، تحت «دلالات الاشتباه والتشابه في مشتبهًا وغير متشابه»","url":""}]},{"id":"s6-733","number":733,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما الدلالات المتوالية التي يستدعيها فعل الأمر ﴿انظروا﴾؟","answer":"دعا إلى نظر حسي في الثمر، ثم إلى تأمل عقلي في انتقاله من الظهور إلى النضج، ثم إلى الاستدلال بقدرة منشئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص500، تحت عنوان «توالي الدلالات في الفعل انظروا»","url":""}]},{"id":"s6-1295","number":1295,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما بلاغة عطف الينع على الثمر في قوله تعالى: ﴿انظروا إلى ثمره إذا أثمر وينعه﴾؟","answer":"خص الينع بعد عموم أحوال الثمر لأنه حال كماله وصلاحيته للانتفاع، فهو عطف خاص على عام.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص501، تحت عنوان «بلاغة عطف الخاص على العام»","url":""}]},{"id":"s6-734","number":734,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"ما سرّ التعبير بالفعل في ﴿إذا أثمر﴾ وبالاسم في ﴿وينعه﴾؟","answer":"بدء الإثمار ظهور حادث تتبدل فيه أحوال الثمر، فناسبه الفعل. أما الينع فهو حال بلوغ الثمرة كمال نضجها واستقرار صلاحها للانتفاع، فناسب التعبير عنه بالاسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص500–501، تحت «سر التغاير بين الفعل والاسم في إذا أثمر وينعه»","url":""}]},{"id":"s6-735","number":735,"surah":6,"verses":[99],"references":[{"surah":6,"verses":[99]}],"verseLabel":"الأنعام: 99","question":"لماذا خُتمت الآية بـ﴿لقوم يؤمنون﴾ بعد ﴿يعلمون﴾ و﴿يفقهون﴾؟","answer":"هذه الآية تذكر إنزال الماء وإحياء النبات وتنوع الثمر، وهي دلائل تذكّر بالبعث وتدعو إلى التصديق بالله؛ فناسبها ﴿يؤمنون﴾ بعد ﴿يعلمون﴾ و﴿يفقهون﴾. والإيمان أصل الشكر على هذه النعم، فجيء بما يستدعي الشكر ويؤسسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص502–503، تحت «توجيه المتشابه اللفظي بين فواصل الآي»","url":""}]},{"id":"s6-736","number":736,"surah":6,"verses":[99,141],"references":[{"surah":6,"verses":[99,141]}],"verseLabel":"الأنعام: 99، 141","question":"ما سرّ التعبير في قوله تعالى في الآية 99: ﴿مشتبهًا وغير متشابه﴾، وفي الآية 141: ﴿متشابهًا وغير متشابه﴾؟","answer":"من توجيه الفرق أن آية 99 تدعو إلى النظر في الثمار، فناسبها ﴿مشتبهًا﴾. أما آية 141 ففي سياق الأكل وأحكامه؛ فعدل فيها إلى ﴿متشابهًا﴾ لئلا يقترن الأمر بالأكل بلفظ قد يوهم الشبهة بين الحلال والحرام، مع أن التشابه المذكور في هيئة الثمار.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص306–307، تحت «توجيه متشابه آيتي سورة الأنعام 141 و99»","url":""}]},{"id":"s6-737","number":737,"surah":6,"verses":[99,141],"references":[{"surah":6,"verses":[99,141]}],"verseLabel":"الأنعام: 99، 141","question":"ما سرّ التعبير في قوله تعالى في الآية 99: ﴿انظروا إلى ثمره﴾، وفي الآية 141: ﴿كلوا من ثمره﴾ مع تشابه المذكورات؟","answer":"آية 99 في سياق نصب دلائل الوحدانية والقدرة، فناسبها الأمر بالنظر والاعتبار. وآية 141 في سياق إبطال تحريم الأطعمة وبيان أحكامها وحقها، فناسبها ﴿كلوا﴾ و﴿آتوا حقه﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص503، تحت «وجه التناسب بين الفعلين انظروا وكلوا»","url":""}]},{"id":"s6-738","number":738,"surah":6,"verses":[100],"references":[{"surah":6,"verses":[100]}],"verseLabel":"الأنعام: 100","question":"ما سر كون ﴿الجن﴾ مفعولًا أولًا مؤخرًا في قوله تعالى: ﴿وجعلوا لله شركاء الجن﴾؟","answer":"على هذا الإعراب يكون الجن هم المجعولين، وتأخيرهم يجعل الإنكار منصبًا أولًا على أصل اتخاذ شريك لله قبل تعيينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص508، تحت عنوان «سر كون الجن مفعولًا أولًا وأثر ذلك في المعنى»","url":""}]},{"id":"s6-1296","number":1296,"surah":6,"verses":[100],"references":[{"surah":6,"verses":[100]}],"verseLabel":"الأنعام: 100","question":"ما بلاغة التقديم والتأخير في قوله تعالى: ﴿شركاء الجن﴾؟","answer":"قدم ﴿شركاء﴾ للعناية بإنكار الشركة مطلقًا، ثم ذكر الجن لبيان نوع الشرك الواقع منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص509–510، تحت عنوان «بلاغة التقديم والتأخير في شركاء الجن»","url":""}]},{"id":"s6-739","number":739,"surah":6,"verses":[100],"references":[{"surah":6,"verses":[100]}],"verseLabel":"الأنعام: 100","question":"ما سرّ تقديم ﴿لله﴾ على ﴿شركاء﴾؟","answer":"قُدّم ﴿لله﴾ للاهتمام بمن جُعل له الشريك ولزيادة التشنيع؛ إذ يظهر من أول التركيب أنهم سوّوا مخلوقًا بالله الذي انفرد بالخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص510، تحت «سر تقديم المجرور لله على المفعول»","url":""}]},{"id":"s6-740","number":740,"surah":6,"verses":[100],"references":[{"surah":6,"verses":[100]}],"verseLabel":"الأنعام: 100","question":"ما دلالة مجيء قوله تعالى: ﴿وخلقهم﴾ عقب اتخاذهم الجن شركاء؟","answer":"جملة ﴿وخلقهم﴾ حال أو اعتراض يقرر التناقض: جعلوا الجن شركاء لله مع أن الله خالقهم وخالق من عبدهم، والمخلوق لا يكون شريكًا لخالقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص511، تحت «فائدة إيراد الفعل وخلقهم»","url":""}]},{"id":"s6-741","number":741,"surah":6,"verses":[100],"references":[{"surah":6,"verses":[100]}],"verseLabel":"الأنعام: 100","question":"ما بلاغة المجاز في لفظ ﴿خرقوا﴾؟","answer":"استعمل الخرق، وهو القطع على فساد، في اختلاق دعوى البنين والبنات بلا علم؛ فصور فظاعة الافتراء واضطرابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص511، تحت عنوان «بلاغة المجاز في لفظ وخرقوا»","url":""}]},{"id":"s6-1297","number":1297,"surah":6,"verses":[100],"references":[{"surah":6,"verses":[100]}],"verseLabel":"الأنعام: 100","question":"ما الفرق بين الخرق والخلق؟","answer":"الخلق إيجاد على تقدير ونظام، أما الخرق ففيه معنى القطع والفساد والاختلاق بلا تقدير؛ فناسب وصف دعواهم الباطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص515، تحت عنوان «الفروق المعجمية: خرق وخلق»","url":""}]},{"id":"s6-742","number":742,"surah":6,"verses":[100],"references":[{"surah":6,"verses":[100]}],"verseLabel":"الأنعام: 100","question":"ما سرّ تقديم البنين على البنات في ﴿وخرقوا له بنين وبنات﴾؟","answer":"من وجوه التقديم أن نسبة البنين إلى الله كانت دعوى طوائف أكثر، كاليهود والنصارى، فقدم الأوسع وقوعًا. وذكر المصدر أيضًا مراعاة تقديم الذكر على الأنثى باعتبار أصل الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص512، تحت «بلاغة تقديم البنين على البنات»","url":""}]},{"id":"s6-743","number":743,"surah":6,"verses":[100],"references":[{"surah":6,"verses":[100]}],"verseLabel":"الأنعام: 100","question":"إذا كانت دعوى البنين والبنات افتراءً، فما فائدة زيادة ﴿بغير علم﴾؟","answer":"هي بيان وتوكيد لفساد افترائهم؛ فلا يقوم قولهم على شيء يصح أن يسمى علمًا. وتنكير ﴿علم﴾ في سياق النفي يستأصل دعوى أن لهم فيه دليلًا، فيزيد تقريعهم على الجهل.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص512–513، تحت «سر تنكير لفظ علم من قوله تعالى بغير علم»","url":""}]},{"id":"s6-744","number":744,"surah":6,"verses":[100],"references":[{"surah":6,"verses":[100]}],"verseLabel":"الأنعام: 100","question":"لماذا جمع بين ﴿سبحانه وتعالى﴾؟","answer":"التسبيح تنزيه لله عما لا يليق به، أما التعالي فإثبات أنه متعالٍ في ذاته عن النقائص، سواء نزهه الناس أم لم يفعلوا. فجمع التعبير بين تنزيهه والإخبار بكماله الذاتي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص514، تحت «الفرق بين التسبيح والتعالي في سبحانه وتعالى»","url":""}]},{"id":"s6-745","number":745,"surah":6,"verses":[100],"references":[{"surah":6,"verses":[100]}],"verseLabel":"الأنعام: 100","question":"ما دلالة ختام التنزيه بقوله ﴿عما يصفون﴾؟","answer":"دعواهم الشريك والولد تتضمن نسبة صفات إلى الله؛ فجاء ﴿يصفون﴾ ليتناول تلك الأوصاف الباطلة كلها، وينزه الله عن أن يكون شيء منها وصفًا حقيقيًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص514، تحت «علة الختام بالفعل يصفون»","url":""}]},{"id":"s6-746","number":746,"surah":6,"verses":[101],"references":[{"surah":6,"verses":[101]}],"verseLabel":"الأنعام: 101","question":"ما فائدة التعبير بلفظ ﴿بديع﴾ في قوله تعالى: ﴿بديع السماوات والأرض﴾؟","answer":"دل على إنشاء السماوات والأرض من غير مثال سابق، وهو أبلغ في نفي الحاجة إلى ولد أو معين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص518، تحت عنوان «فائدة التعبير بلفظ بديع في الآية»","url":""}]},{"id":"s6-1298","number":1298,"surah":6,"verses":[101],"references":[{"surah":6,"verses":[101]}],"verseLabel":"الأنعام: 101","question":"ما الفرق بين البديع والخالق؟","answer":"الخالق يقدر ويوجد، والبديع يزيد معنى الإيجاد من غير مثال سابق؛ فكل بديع خالق وليس كل استعمال للخالق مبرزًا لهذا القيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص522–523، تحت عنوان «الفروق المعجمية: بديع وخالق»","url":""}]},{"id":"s6-747","number":747,"surah":6,"verses":[101],"references":[{"surah":6,"verses":[101]}],"verseLabel":"الأنعام: 101","question":"لماذا جاء نفي الولد في صورة سؤال: ﴿أنى يكون له ولد﴾؟","answer":"﴿أنى﴾ استفهام إنكاري تعجبي ينفي كل وجه يمكن أن يتوهم لوجود الولد؛ كيف ومن أين يكون له ولد وهو بديع الخلق ولم تكن له صاحبة؟","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص520، تحت «دلالة الاستفهام في أنى»","url":""}]},{"id":"s6-748","number":748,"surah":6,"verses":[101],"references":[{"surah":6,"verses":[101]}],"verseLabel":"الأنعام: 101","question":"ما فائدة إيراد ﴿ولم تكن له صاحبة﴾ بعد إنكار أن يكون لله ولد؟","answer":"جاءت الجملة حالًا تؤكد استحالة ما ادعوه؛ فالولادة المعهودة تستلزم صاحبة، وقد نُفيت عنه. أما إيجاده المخلوقات فمنشؤه الخلق والإبداع، لا التولد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص520–521، تحت «فائدة جملة ولم تكن له صاحبة»","url":""}]},{"id":"s6-749","number":749,"surah":6,"verses":[101],"references":[{"surah":6,"verses":[101]}],"verseLabel":"الأنعام: 101","question":"لماذا عطف ﴿وخلق كل شيء﴾ على نفي الصاحبة والولد؟","answer":"عطف ﴿وخلق كل شيء﴾ برهانًا جامعًا: كل ما سواه مخلوق له، والولد لو وُجد لكان من جملة الخلق، فلا يصح أن يكون جزءًا من الخالق أو شريكًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص521، تحت «جملة وخلق كل شيء بين الاستئناف والحالية»","url":""}]},{"id":"s6-750","number":750,"surah":6,"verses":[101],"references":[{"surah":6,"verses":[101]}],"verseLabel":"الأنعام: 101","question":"ما بديع الختام بقوله تعالى: ﴿وهو بكل شيء عليم﴾؟","answer":"أتمت الفاصلة دليل القدرة بالعلم الشامل، فقررت كمال الله واستغناءه وأبطلت نسبة الولد والصاحبة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص521، تحت عنوان «بديع الختام بالفاصلة»","url":""}]},{"id":"s6-1299","number":1299,"surah":6,"verses":[101],"references":[{"surah":6,"verses":[101]}],"verseLabel":"الأنعام: 101","question":"ما بلاغة الاستئناف في قوله تعالى: ﴿وهو بكل شيء عليم﴾؟","answer":"جاءت الجملة مستقلة لتقرير أصل جامع: إحاطة علمه بكل شيء، فكانت تعليلًا لما سبق وتثبيتًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص521–522، تحت عنوان «بلاغة الاستئناف في الفاصلة»","url":""}]},{"id":"s6-751","number":751,"surah":6,"verses":[102],"references":[{"surah":6,"verses":[102]}],"verseLabel":"الأنعام: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلكم الله ربكم﴾ باسم الإشارة للبعيد؟","answer":"الإشارة للبعيد للتعظيم، وتعود إلى الموصوف بالخلق والإبداع والعلم في الآيات السابقة؛ أي ذلك المتفرد بهذه الصفات العظيمة هو الله ربكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص525–526، تحت «فائدة استعمال اسم الإشارة في ذلكم الله ربكم»","url":""}]},{"id":"s6-752","number":752,"surah":6,"verses":[102],"references":[{"surah":6,"verses":[102]}],"verseLabel":"الأنعام: 102","question":"ما فائدة الإخبار بلفظ ﴿ربكم﴾ بعد اسم الله في قوله تعالى: ﴿ذلكم الله ربكم﴾؟","answer":"انتقل من الاسم الجامع للألوهية إلى وصف الرعاية والتدبير المتصل بالمخاطبين، فأقام موجب عبادته عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص527، تحت عنوان «فائدة الإخبار بقول ربكم بعد الإخبار باسم الله الأحسن»","url":""}]},{"id":"s6-1300","number":1300,"surah":6,"verses":[102],"references":[{"surah":6,"verses":[102]}],"verseLabel":"الأنعام: 102","question":"ما براعة ترتيب قوله تعالى: ﴿ذلكم الله ربكم لا إله إلا هو خالق كل شيء﴾؟","answer":"رتب المعاني من تعيين المعبود الحق، إلى ربوبيته، ثم نفي الشريك، ثم برهان الخلق؛ فتكامل تقرير التوحيد والحجة عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص528–529، تحت عنوان «براعة الترتيب في ذلكم الله ربكم لا إله إلا هو خالق كل شيء»","url":""}]},{"id":"s6-753","number":753,"surah":6,"verses":[102],"references":[{"surah":6,"verses":[102]}],"verseLabel":"الأنعام: 102","question":"لماذا فُرعت العبادة بالفاء: ﴿فاعبدوه﴾؟","answer":"الفاء تفيد أن العبادة نتيجة لازمة لما ثبت من وحدانيته وربوبيته وخلقه كل شيء؛ فمن كان كذلك استحق أن يعبد وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص529–530، تحت «دلالة الفاء في فاعبدوه»","url":""}]},{"id":"s6-754","number":754,"surah":6,"verses":[102],"references":[{"surah":6,"verses":[102]}],"verseLabel":"الأنعام: 102","question":"ما مناسبة ختم الأمر بالعبادة بقوله ﴿وهو على كل شيء وكيل﴾؟","answer":"الوكيل هنا القائم على الخلق بالحفظ والرعاية؛ فذكره يبين أن عنايته بهم مستمرة، ويعلل استحقاقه العبادة وحده، إذ لا يستغنون عن حفظه وتدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص532، تحت «سر اختيار اسم الله الوكيل»","url":""}]},{"id":"s6-755","number":755,"surah":6,"verses":[103],"references":[{"surah":6,"verses":[103]}],"verseLabel":"الأنعام: 103","question":"ما سر استعمال مفردة ﴿تدركه﴾ في قوله تعالى: ﴿لا تدركه الأبصار﴾؟","answer":"الإدراك بلوغ الشيء والإحاطة به، فنفت الآية إحاطة الأبصار بالله، وهو معنى أخص من مطلق الرؤية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص534–535، تحت عنوان «سر استعمال مفردة تدركه»","url":""}]},{"id":"s6-1301","number":1301,"surah":6,"verses":[103],"references":[{"surah":6,"verses":[103]}],"verseLabel":"الأنعام: 103","question":"ما دلالة استعمال ﴿تدركه﴾ مع الأبصار؟","answer":"أسند الإدراك إلى الأبصار ليعم نفي إحاطتها به في جميع الأوقات، مع بقاء الفرق بين نفي الإحاطة ونفي أصل الرؤية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص535–536، تحت عنوان «دلالة استعمال مفردة تدركه مع الأبصار»","url":""}]},{"id":"s6-756","number":756,"surah":6,"verses":[103],"references":[{"surah":6,"verses":[103]}],"verseLabel":"الأنعام: 103","question":"لماذا جُمعت ﴿الأبصار﴾؟","answer":"جُمعت الأبصار لاستغراق أبصار الخلق كلها؛ فلا يحيط به بصر مهما تعدد أصحابه أو اختلفت قواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص536، تحت «دلالة الجمع ودخول أل في الأبصار»","url":""}]},{"id":"s6-757","number":757,"surah":6,"verses":[103],"references":[{"surah":6,"verses":[103]}],"verseLabel":"الأنعام: 103","question":"ما بلاغة المقابلة بين ﴿لا تدركه الأبصار﴾ و﴿هو يدرك الأبصار﴾؟","answer":"أظهرت المقابلة كمال إحاطته وقصور خلقه: أبصارهم لا تحيط به، وهو يحيط بها وبما تبصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص537، تحت عنوان «بلاغة المقابلة بين لا تدركه الأبصار وهو يدرك الأبصار»","url":""}]},{"id":"s6-1302","number":1302,"surah":6,"verses":[103],"references":[{"surah":6,"verses":[103]}],"verseLabel":"الأنعام: 103","question":"ما بلاغة المجاز بالحذف في قوله تعالى: ﴿وهو يدرك الأبصار﴾؟","answer":"أطلق الأبصار وأريد أصحابها وما يتعلق بها، فدل الكلام بإيجازه على إحاطته بالبصر والمبصر والباصرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص538، تحت عنوان «بلاغة المجاز بالحذف»","url":""}]},{"id":"s6-758","number":758,"surah":6,"verses":[103],"references":[{"surah":6,"verses":[103]}],"verseLabel":"الأنعام: 103","question":"كيف أثر اشتقاق اسم الله ﴿اللطيف﴾ في تنوع معناه البلاغي؟","answer":"احتمل معنى التنزه عن إدراك الأبصار لدقة شأنه، واحتمل معنى الرفق والإحسان؛ فتسع دلالته للسياقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص539، تحت عنوان «أثر اشتقاق اسم الله اللطيف في التنوع البلاغي»","url":""}]},{"id":"s6-1303","number":1303,"surah":6,"verses":[103],"references":[{"surah":6,"verses":[103]}],"verseLabel":"الأنعام: 103","question":"ما نكتة اللف والنشر في قوله تعالى: ﴿وهو اللطيف الخبير﴾؟","answer":"ناسب ﴿اللطيف﴾ نفي إحاطة الأبصار به، وناسب ﴿الخبير﴾ إحاطته بالأبصار وأصحابها، فجاءت الخاتمة موزعة على طرفي الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص540، تحت عنوان «نكتة اللف والنشر»","url":""}]},{"id":"s6-759","number":759,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]}],"verseLabel":"الأنعام: 104","question":"ما غرض الجناس بين البصائر والأبصار في سياق الآيتين؟","answer":"قارب اللفظان واختلف المعنى، فربط دلائل القلب بأداة النظر الحسي ونبه إلى أن المقصود إبصار الحق لا مجرد رؤية العين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص544، تحت عنوان «غرض الجناس بين البصائر والأبصار»","url":""}]},{"id":"s6-1304","number":1304,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]}],"verseLabel":"الأنعام: 104","question":"ما بلاغة الاستعارة المكنية في لفظ ﴿بصائر﴾؟","answer":"صُورت الحجج والهدايات بوسائل إبصار للقلوب تكشف بها مواقع الحق، فاشتق لها اسم البصيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص544–545، تحت عنوان «الاستعارة المكنية في بصائر»","url":""}]},{"id":"s6-760","number":760,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]}],"verseLabel":"الأنعام: 104","question":"لماذا جُمعت ﴿بصائر﴾ مع وحدة القرآن؟","answer":"جُمعت لتعدد الآيات والحجج ووجوه الدلالة التي جاء بها القرآن، وإن كان الكتاب واحدًا؛ فكل حجة بصيرة تهدي إلى الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص545، تحت «نكتة جمع البصائر في قد جاءكم بصائر»","url":""}]},{"id":"s6-761","number":761,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]}],"verseLabel":"الأنعام: 104","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿فمن أبصر فلنفسه﴾؟","answer":"استعير الإبصار لقبول الحجة والاهتداء بها، لأن المهتدي يرى الحق بقلبه كما يرى المبصر الطريق بعينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص547، تحت عنوان «الاستعارة في فمن أبصر»","url":""}]},{"id":"s6-1305","number":1305,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]}],"verseLabel":"الأنعام: 104","question":"ما بلاغة الاستعارة التصريحية في قوله تعالى: ﴿ومن عمي فعليها﴾؟","answer":"صرح بالعمى بدل الإعراض والضلال، فصور المعرض فاقدًا لبصيرة تهديه مع قيام الدليل أمامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص548–549، تحت عنوان «بلاغة الاستعارة التصريحية في عمي»","url":""}]},{"id":"s6-1306","number":1306,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]}],"verseLabel":"الأنعام: 104","question":"ما بلاغة المقابلة بين ﴿فمن أبصر﴾ و﴿ومن عمي﴾؟","answer":"قابل الهدى بالعمى والنفع بالضرر، فبين أن ثمرة الاختيار تعود إلى صاحبه وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص550، تحت عنوان «بلاغة المقابلة»","url":""}]},{"id":"s6-762","number":762,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]}],"verseLabel":"الأنعام: 104","question":"ما بلاغة الاستعارة التبعية في اللام من قوله تعالى: ﴿فلنفسه﴾؟","answer":"استعملت اللام للاختصاص والنفع، فدلّت على أن ثمرة الإبصار راجعة إلى صاحبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص547، تحت عنوان «الاستعارة التبعية في حرف اللام»","url":""}]},{"id":"s6-1307","number":1307,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]}],"verseLabel":"الأنعام: 104","question":"ما بلاغة استعمال حرف الاستعلاء ﴿على﴾ في قوله تعالى: ﴿فعليها﴾؟","answer":"صور ضرر العمى وتبعته حملًا واقعًا على النفس، فناسب حرف الاستعلاء معنى الثقل والضرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص548–549، تحت عنوان «بلاغة استعمال حرف الاستعلاء على»","url":""}]},{"id":"s6-763","number":763,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]},{"surah":11,"verses":[86]}],"verseLabel":"الأنعام: 104؛ هود: 86","question":"ما غرض التتميم في قوله تعالى: ﴿وما أنا عليكم بحفيظ﴾ في الأنعام؟","answer":"أتمت الجملة المعنى بنفي أن يكون الرسول رقيبًا يحفظ أعمالهم أو يتحمل تبعتها؛ فوظيفته البلاغ، ونفع الهدى وضرر الضلال عائدان إلى صاحبهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص551، تحت «غرض فن التتميم»","url":""}]},{"id":"s6-1408","number":1408,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]},{"surah":11,"verses":[86]}],"verseLabel":"الأنعام: 104؛ هود: 86","question":"ما بلاغة ختم موعظة شعيب بقوله: ﴿وما أنا عليكم بحفيظ﴾؟","answer":"يلائم الختم مقام النصح بعد بيان الحلال والحرام؛ فهو يقرر أن شعيبًا ناصح مبلِّغ، وأن تبعة الاختيار والحساب على المخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص518، تحت «بلاغة الختم: ﴿وما أنا عليكم بحفيظ﴾»","url":""}]},{"id":"s6-1409","number":1409,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]},{"surah":11,"verses":[86]}],"verseLabel":"الأنعام: 104؛ هود: 86","question":"ما دلالة النفي في قول شعيب: ﴿وما أنا عليكم بحفيظ﴾؟","answer":"ينفي أن يكون متسلطًا عليهم أو موكَّلًا بإحصاء أعمالهم ومجازاتهم؛ فلا يبقى بعد البلاغ إلا مسؤوليتهم أمام الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص518–519، تحت «دلالة النفي في: ﴿وما أنا عليكم بحفيظ﴾»","url":""}]},{"id":"s6-1410","number":1410,"surah":6,"verses":[104],"references":[{"surah":6,"verses":[104]},{"surah":11,"verses":[86]}],"verseLabel":"الأنعام: 104؛ هود: 86","question":"ما نكتة اختيار لفظ ﴿حفيظ﴾ في قول شعيب؟","answer":"يجمع لفظ ﴿حفيظ﴾ معنى الإحصاء والمراقبة ومعنى المنع والحراسة؛ فنفى عن نفسه كلا المعنيين ليخلص مقامه للنصح والبلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص519، تحت «نكتة اختيار التعبير بـ﴿حفيظ﴾»","url":""}]},{"id":"s6-764","number":764,"surah":6,"verses":[105],"references":[{"surah":6,"verses":[105]}],"verseLabel":"الأنعام: 105","question":"ما الذي يفيده لفظ ﴿نصرف الآيات﴾ زيادة على مجرد بيانها؟","answer":"التصريف تنويع وجوه البيان؛ فتُعرض الحجة مرة في مثال، ومرة في قصة أو غيرهما، وتُنقل من وجه إلى وجه حتى تبلغ الفهم. فاللفظ يجمع البيان وتعدد طرائقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص557–558، تحت «سر استعمال مفردة نصرف بدلًا من نفصل أو نبين»","url":""}]},{"id":"s6-765","number":765,"surah":6,"verses":[105],"references":[{"surah":6,"verses":[105]}],"verseLabel":"الأنعام: 105","question":"ما سرّ التعبير في قوله تعالى: ﴿وليقولوا درست﴾، فجعل قول المعاندين غاية لتصريف الآيات؟","answer":"اللام للعاقبة لا لأن قولهم غرض محبوب؛ فتصريف الآيات يؤدي، مع عنادهم، إلى أن يقولوا ﴿درست﴾، بينما يؤدي عند أهل العلم إلى البيان والهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص559–560، تحت «معنى اللام في وليقولوا درست»","url":""}]},{"id":"s6-766","number":766,"surah":6,"verses":[105],"references":[{"surah":6,"verses":[105]}],"verseLabel":"الأنعام: 105","question":"ما بلاغة التعبير بمفردة ﴿درست﴾؟","answer":"حكت اللفظة شبهة المعاندين بأن النبي قرأ الأخبار وتعلمها من غيره، فجاءت قصيرة كاشفة لطبيعة اتهامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص561، تحت عنوان «بلاغة التعبير بمفردة درس»","url":""}]},{"id":"s6-1308","number":1308,"surah":6,"verses":[105],"references":[{"surah":6,"verses":[105]}],"verseLabel":"الأنعام: 105","question":"كيف توجه القراءات القرآنية في لفظ ﴿درست﴾؟","answer":"قراءة ﴿دَرَسْتَ﴾ تعني قرأت وتعلمت، و﴿دارست﴾ تعني ذاكرت غيرك، و﴿دَرَسَتْ﴾ تعني قدمت وعفت آثارها؛ فتكشف وجوه شبهتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص561–562، تحت عنوان «توجيه القراءات القرآنية في درست»","url":""}]},{"id":"s6-767","number":767,"surah":6,"verses":[105],"references":[{"surah":6,"verses":[105]}],"verseLabel":"الأنعام: 105","question":"ما موقع جملة ﴿وليقولوا درست﴾ بين ما قبلها وما بعدها؟","answer":"جاءت بين تصريف الآيات وبيانها لتكشف أن مادة واحدة تقيم الحجة للمنصف، ويتخذها المعاند شبهة يصرف بها الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص562، تحت عنوان «موقع جملة وليقولوا درست بين السابقة واللاحقة»","url":""}]},{"id":"s6-1309","number":1309,"surah":6,"verses":[105],"references":[{"surah":6,"verses":[105]}],"verseLabel":"الأنعام: 105","question":"ما معنى اللام، وما الفرق بينها في ﴿وليقولوا درست﴾ و﴿ولنبينه لقوم يعلمون﴾؟","answer":"الأولى لام العاقبة أو التعليل بحسب التوجيه، فقولهم نتيجة عنادهم، والثانية لام الغرض الصريح؛ إذ المقصود بيان الآيات لأهل العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص562–563، تحت عنوان «معنى اللام والتفريق بينهما في الموضعين»","url":""}]},{"id":"s6-768","number":768,"surah":6,"verses":[106],"references":[{"surah":6,"verses":[106]}],"verseLabel":"الأنعام: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿اتبع ما أوحي إليك﴾، دون أن يقال: اتبع القرآن؟","answer":"الوحي أعم من اسم القرآن من جهة ما يبلغه الله لنبيه، وفي التعبير تأكيد مصدر التكليف ووجوب اتباع كل ما أوحاه ربه، لا التعامل معه بوصفه كلامًا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص573، تحت «نكتة إيثار لفظ الإيحاء على الإنزال»","url":""}]},{"id":"s6-769","number":769,"surah":6,"verses":[106],"references":[{"surah":6,"verses":[106]}],"verseLabel":"الأنعام: 106","question":"ما وظيفة جملة ﴿لا إله إلا هو﴾ بين الأمر باتباع الوحي والأمر بالإعراض عن المشركين؟","answer":"هي اعتراض يؤكد الوحدانية ويزيد تقريرها؛ فالمعبود الحق واحد، ووحيه هو المتبع. وإيرادها بين الأمرين يرسخ اتباع الوحي والإعراض عما يناقض التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص574، تحت «غرض إيراد لا إله إلا هو بين الأمرين»","url":""}]},{"id":"s6-770","number":770,"surah":6,"verses":[106],"references":[{"surah":6,"verses":[106]}],"verseLabel":"الأنعام: 106","question":"ما غرض الأمر في قوله تعالى: ﴿وأعرض عن المشركين﴾؟","answer":"الغرض تثبيت الرسول على الوحي وترك الالتفات إلى عناد المشركين ومطالبهم التعنتية بعد قيام البيان، لا ترك دعوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص575، تحت عنوان «غرض الأمر في وأعرض»","url":""}]},{"id":"s6-1310","number":1310,"surah":6,"verses":[106],"references":[{"surah":6,"verses":[106]}],"verseLabel":"الأنعام: 106","question":"ما بلاغة إيثار الأمر بالإعراض بدل النهي عن طاعة المشركين؟","answer":"الأمر بالإعراض أبلغ في قطع الالتفات إلى شبهاتهم وأذاهم، ويصور المضي في طريق الوحي دون اشتغال بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص575–576، تحت عنوان «بلاغة إيثار الأمر بالإعراض دون النهي عن طاعة المشركين»","url":""}]},{"id":"s6-771","number":771,"surah":6,"verses":[107],"references":[{"surah":6,"verses":[107]}],"verseLabel":"الأنعام: 107","question":"ما المعنى الإجمالي لقوله تعالى: ﴿ولو شاء الله ما أشركوا﴾؟","answer":"الله قادر على منع الشرك لو شاء أن يخلقهم مجبرين على الإيمان، لكنه كلفهم مع الاختيار؛ فوقع شركهم باختيارهم تحت مشيئته الكونية.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص578، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s6-1311","number":1311,"surah":6,"verses":[107],"references":[{"surah":6,"verses":[107]}],"verseLabel":"الأنعام: 107","question":"ما مقصد عطف ﴿ولو شاء الله ما أشركوا﴾ على الأمر بالإعراض؟","answer":"سلّى الرسول بأن الله قادر على منع شركهم، وأن مهمته البلاغ لا حملهم على الإيمان قهرًا، فليمض في اتباع الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص579، تحت عنوان «مقصد عطف ولو شاء الله ما أشركوا على الأمر بالإعراض»","url":""}]},{"id":"s6-772","number":772,"surah":6,"verses":[107],"references":[{"surah":6,"verses":[107]}],"verseLabel":"الأنعام: 107","question":"ما الفرق بين الحفيظ والوكيل؟","answer":"الحفيظ يراقب ويحفظ من المخالفة، والوكيل يتولى شؤون غيره ومصالحه؛ ولكل لفظ جهة خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص552–553، تحت عنوان «الفروق المعجمية: الحفيظ والوكيل»","url":""}]},{"id":"s6-1312","number":1312,"surah":6,"verses":[107],"references":[{"surah":6,"verses":[107]}],"verseLabel":"الأنعام: 107","question":"ما سر الجمع بين نفي كون الرسول حفيظًا ووكيلًا؟","answer":"نفى أن يكون رقيبًا يجبرهم أو متوليًا لنتائج اختيارهم؛ فوظيفته البلاغ، وكل نفس تتحمل عملها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص584، تحت عنوان «سر الجمع بين نفي كونه حفيظًا ووكيلًا»","url":""}]},{"id":"s6-773","number":773,"surah":6,"verses":[107],"references":[{"surah":6,"verses":[107]}],"verseLabel":"الأنعام: 107","question":"لماذا تكرر ﴿عليهم﴾ في الجملتين؟","answer":"تكرار ﴿عليهم﴾ يثبت استقلال النفيين ويقوي تعلق كل من الحفظ والوكالة بالمشركين؛ فلا هو حفيظ عليهم، ولا هو وكيل عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص583، تحت «نكتة تكرار وما وعليهم للتوكيد»","url":""}]},{"id":"s6-774","number":774,"surah":6,"verses":[108],"references":[{"surah":6,"verses":[108]}],"verseLabel":"الأنعام: 108","question":"ما المعنى الإجمالي للنهي عن سب معبودات المشركين؟","answer":"نهي المسلمون عن سبها لأن ذلك يفضي إلى مفسدة أعظم، وهي سب المشركين لله بجهل وعدوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص586–587، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s6-1313","number":1313,"surah":6,"verses":[108],"references":[{"surah":6,"verses":[108]}],"verseLabel":"الأنعام: 108","question":"ما أغراض النهي في قوله تعالى: ﴿ولا تسبوا﴾؟","answer":"جاء للإرشاد الملزم إلى مراعاة المآلات وسد الذريعة، وتهذيب خطاب الدعوة حتى لا يقود إلى زيادة المنكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص588–589، تحت عنوان «أغراض النهي في ولا تسبوا»","url":""}]},{"id":"s6-775","number":775,"surah":6,"verses":[108],"references":[{"surah":6,"verses":[108]}],"verseLabel":"الأنعام: 108","question":"ما فائدة استعمال الاسم الموصول في قوله تعالى: ﴿الذين يدعون من دون الله﴾؟","answer":"جمع كل ما اتخذوه معبودًا من دون الله ولم يقصر النهي على صنف بعينه، وعرّفهم بفعل عابديهم الذي هو موطن الإنكار.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص591–592، تحت عنوان «فائدة استعمال الاسم الموصول»","url":""}]},{"id":"s6-1314","number":1314,"surah":6,"verses":[108],"references":[{"surah":6,"verses":[108]}],"verseLabel":"الأنعام: 108","question":"ما دلالة حذف مفعول ﴿يدعون﴾؟","answer":"أفاد الحذف العموم، ويقدر العائد: الذين يدعونهم؛ فشمل كل ما يدعونه من دون الله مع إيجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص592–593، تحت عنوان «دلالة حذف مفعول يدعون»","url":""}]},{"id":"s6-776","number":776,"surah":6,"verses":[108],"references":[{"surah":6,"verses":[108]}],"verseLabel":"الأنعام: 108","question":"لماذا كانت النتيجة: ﴿فيسبوا الله عدوًا بغير علم﴾؟","answer":"الفاء تبين سببية المفسدة وترتبها: إذا سُبت معبوداتهم حملهم التعصب والجهل على مقابلة السب بسب الله، فالنهي يسد هذا الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص593، تحت «دلالة الفاء في فيسبوا»","url":""}]},{"id":"s6-777","number":777,"surah":6,"verses":[108],"references":[{"surah":6,"verses":[108]}],"verseLabel":"الأنعام: 108","question":"ما الذي يضيفه وصف السب بأنه ﴿عدوًا﴾ في ﴿فيسبوا الله عدوًا بغير علم﴾؟","answer":"﴿عدوًا﴾ مصدر يدل على تجاوز الحد من الحق إلى الباطل؛ فوصف به سبهم ليكشف أنه اعتداء وجور، وليس ردًا يملكون به حقًا. وفيه تقبيح لفعلهم وتعريض بفساد موقفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص594–595، تحت «فن التعريض في عدوًا»","url":""}]},{"id":"s6-778","number":778,"surah":6,"verses":[108],"references":[{"surah":6,"verses":[108]}],"verseLabel":"الأنعام: 108","question":"ما دلالة إسناد فعل التزيين إلى الضمير العائد على الله تعالى؟","answer":"الإسناد إلى سنته ومشيئته في الخلق؛ فقد خلق في النفوس الاستحسان وترك المعاندين لاختيارهم بعد قيام الحجة، ولا يعني أنه أمر بالباطل أو رضي به.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص596–597، تحت عنوان «دلالة إسناد فعل التزيين إلى الضمير العائد على الله تعالى»","url":""}]},{"id":"s6-1315","number":1315,"surah":6,"verses":[108],"references":[{"surah":6,"verses":[108]}],"verseLabel":"الأنعام: 108","question":"ما مفهوم الأمم بين خصوص الكافرين والعموم في قوله تعالى: ﴿لكل أمة عملهم﴾؟","answer":"يشمل اللفظ الأمم من حيث خضوعها لسنة استحسان ما ألفته، والسياق يخص الكافرين بالذم لأنهم استمروا على الباطل بعد البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص597–598، تحت عنوان «مفهوم الأمم بين خصوص الكافرين والعموم»","url":""}]},{"id":"s6-779","number":779,"surah":6,"verses":[108],"references":[{"surah":6,"verses":[108]}],"verseLabel":"الأنعام: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم إلى ربهم مرجعهم﴾ بتقديم ﴿إلى ربهم﴾؟","answer":"تقديم ﴿إلى ربهم﴾ يفيد الاختصاص والتهديد: لا مرجع لهم في النهاية إلا إلى ربهم الذي يعلم أعمالهم ويحكم بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص600، تحت «نكتة تقديم الجار والمجرور على المسند إليه»","url":""}]},{"id":"s6-780","number":780,"surah":6,"verses":[108],"references":[{"surah":6,"verses":[108]}],"verseLabel":"الأنعام: 108","question":"ما دلالة استعمال ﴿فينبئهم﴾ دون مرادفاته في قوله تعالى: ﴿فينبئهم بما كانوا يعملون﴾؟","answer":"الإنباء إخبار بأمر عظيم الشأن تظهر به حقيقة ما عملوه وعاقبته؛ فليس مجرد إعلام، بل كشفٌ مقرون بالتقريع والجزاء يوم الرجوع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص602، تحت عنوان «دلالة استعمال مفردة (الإنباء) دون مرادفاتها»","url":""}]},{"id":"s6-1316","number":1316,"surah":6,"verses":[108],"references":[{"surah":6,"verses":[108]}],"verseLabel":"الأنعام: 108","question":"لماذا قيل ﴿بما كانوا يعملون﴾ ولم يقل: «بأعمالهم»؟","answer":"أبرز الموصولُ والفعلُ أعمالهم مفصلةً متجددة، ودلت ﴿كانوا﴾ على رسوخها واستمرارها؛ فالتعبير أبلغ في إحاطة العلم بها وفي إقامة الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص603، تحت عنوان «نكتة التعبير بقوله ﴿بما كانوا يعملون﴾ دون (بأعمالهم)»","url":""}]},{"id":"s6-781","number":781,"surah":6,"verses":[109],"references":[{"surah":6,"verses":[109]}],"verseLabel":"الأنعام: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿وأقسموا بالله جهد أيمانهم﴾، وما صورة بذل الجهد في اليمين؟","answer":"الجهد غاية الطاقة والمبالغة؛ أي بالغوا في توكيد أيمانهم حتى بذلوا أقصى ما يعرفونه من الحلف، مع أن امتناعهم لم يكن لنقص الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص608–609، تحت «فن الإطناب في جهد أيمانهم»","url":""}]},{"id":"s6-782","number":782,"surah":6,"verses":[109],"references":[{"surah":6,"verses":[109]}],"verseLabel":"الأنعام: 109","question":"ما بلاغة تقييد الإيمان بالآية في قوله تعالى: ﴿ليؤمنن بها﴾؟","answer":"قيّدوا الإيمان بالآية المقترحة بعينها، لا بمطلق دلائل الله؛ فكشف القيد أن دعواهم معلقة على طلب مخصوص، لا ناشئة عن تجرد لاتباع الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص611، تحت عنوان «بلاغة تقييد الإيمان بالآية»","url":""}]},{"id":"s6-783","number":783,"surah":6,"verses":[109],"references":[{"surah":6,"verses":[109]}],"verseLabel":"الأنعام: 109","question":"ما غرض القصر في قوله تعالى: ﴿إنما الآيات عند الله﴾؟","answer":"قصر أمر الآيات على الله وحده؛ فهو الذي يملك إنزالها ويختارها بحكمته، وليس للنبي ولا للمقترحين التحكم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص611، تحت عنوان «غرض القصر في إنما الآيات»","url":""}]},{"id":"s6-1317","number":1317,"surah":6,"verses":[109],"references":[{"surah":6,"verses":[109]}],"verseLabel":"الأنعام: 109","question":"ما بلاغة المجاز المرسل في قوله تعالى: ﴿الآيات عند الله﴾؟","answer":"ليست العندية مكانية، وإنما هي مجاز عن الاختصاص والاستئثار بالقدرة والعلم؛ أي إن أمر الآيات وإنزالها مختص بالله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص612، تحت عنوان «بلاغة المجاز المرسل في الآيات عند الله»","url":""}]},{"id":"s6-784","number":784,"surah":6,"verses":[109],"references":[{"surah":6,"verses":[109]}],"verseLabel":"الأنعام: 109","question":"ما سرّ التعبير بالشعور في ﴿وما يشعركم﴾؟","answer":"الإشعار إعلام بأمر خفي دقيق؛ والآية تكشف ما تخفيه نفوس المقترحين من العناد وراء ظاهر أيمانهم. فناسب الشعورُ أمرًا لا يطلع عليه الناس من سرائرهم، وإنما يعلمه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص613، تحت «سر التعبير بالشعور في يشعركم»","url":""}]},{"id":"s6-785","number":785,"surah":6,"verses":[109],"references":[{"surah":6,"verses":[109]}],"verseLabel":"الأنعام: 109","question":"لماذا قيل ﴿إذا جاءت لا يؤمنون﴾ بعد حكاية قولهم ﴿لئن جاءتهم آية ليؤمنن بها﴾؟","answer":"حُكي اقتراحهم بـ﴿إن﴾ التي تعرض المجيء على وجه الاحتمال، ثم جاء الرد بـ﴿إذا﴾؛ فحتى مع فرض تحقق مجيء الآية لا يؤمنون. وبذلك يقطع تعلقهم باحتمال نزول الآية ذريعة لتأخير الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص614، تحت «نكتة استعمال إذا دون إن»","url":""}]},{"id":"s6-786","number":786,"surah":6,"verses":[110],"references":[{"surah":6,"verses":[110]}],"verseLabel":"الأنعام: 110","question":"ما المعنى الإجمالي لقوله تعالى: ﴿ونقلب أفئدتهم وأبصارهم كما لم يؤمنوا به أول مرة﴾؟","answer":"يبين السياق أن المعاندين، لما أعرضوا عن الإيمان أول مرة، يعاقبون بصرف قلوبهم وأبصارهم عن الانتفاع بالحق، ويتركون في طغيانهم مترددين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص621، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s6-1318","number":1318,"surah":6,"verses":[110],"references":[{"surah":6,"verses":[110]}],"verseLabel":"الأنعام: 110","question":"ما بلاغة المجاز في قوله تعالى: ﴿ونقلب أفئدتهم وأبصارهم﴾؟","answer":"صوّر صرف القلوب والأبصار عن إدراك الحق بالتقليب؛ فاستحضر اضطرابهم وتحولهم من حال إلى حال من غير استقرار على هدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص622–623، تحت عنوان «بلاغة المجاز في ونقلب أفئدتهم وأبصارهم»","url":""}]},{"id":"s6-787","number":787,"surah":6,"verses":[110],"references":[{"surah":6,"verses":[110]}],"verseLabel":"الأنعام: 110","question":"ما سرّ تقديم الأفئدة على الأبصار؟","answer":"قُدّمت الأفئدة لأنها محل الفهم والقصد والتصديق، ثم الأبصار لأنها طريق مشاهدة الآيات؛ ففساد الباطن أصلٌ في عدم الانتفاع بالمشاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص622–623، تحت «نكتة تقديم الأفئدة على الأبصار»","url":""}]},{"id":"s6-788","number":788,"surah":6,"verses":[110],"references":[{"surah":6,"verses":[110]}],"verseLabel":"الأنعام: 110","question":"لماذا أُضمر ما لم يؤمنوا به في ﴿كما لم يؤمنوا به أول مرة﴾ بدل التصريح باسمه؟","answer":"المقصود القرآن، وهو معلوم حاضر في الكلام وعظيم الشأن فلا يخفى المراد بالإشارة إليه. وفي الإضمار توبيخ لهم: أعرضوا عن الدليل الذي كان ينبغي أن يبادروا إلى الإيمان به من أول سماعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص624–625، تحت «بلاغة إضمار التصريح بالمؤمن به»","url":""}]},{"id":"s6-789","number":789,"surah":6,"verses":[110],"references":[{"surah":6,"verses":[110]}],"verseLabel":"الأنعام: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿ونذرهم في طغيانهم يعمهون﴾، فجعل الطغيان ظرفًا؟","answer":"جُعل الطغيان ظرفًا محيطًا بهم لتصوير استغراقهم فيه، فهم متروكون داخله يتحيرون لا يهتدون إلى مخرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص626–627، تحت «بلاغة المجاز في استعمال حرف في»","url":""}]},{"id":"s6-790","number":790,"surah":6,"verses":[110],"references":[{"surah":6,"verses":[110]}],"verseLabel":"الأنعام: 110","question":"ما العلاقة بين الطغيان والعمه، وما أثرها في تصوير تمكن ضلال المشركين؟","answer":"الطغيان تجاوز الحد والإمعان في العصيان، والعمه حيرة البصيرة الناشئة عنه؛ فجمعهما يصور سبب الضلال وأثره، مع استمرارهم مترددين فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص627–628، تحت عنوان «العلاقة بين الطغيان والعمه وأثرها في تصوير تمكن ضلال المشركين»","url":""}]},{"id":"s6-1319","number":1319,"surah":6,"verses":[110],"references":[{"surah":6,"verses":[110]}],"verseLabel":"الأنعام: 110","question":"ما الفرق بين العمه والحيرة؟","answer":"العمه حيرة في البصيرة والرأي تجعل صاحبها يتردد في الضلال، والحيرة أعم من ذلك؛ فاختير العمه لتصوير عمى القلب واضطراب صاحبه عن الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص628–629، تحت عنوان «الفروق المعجمية: العمه والحيرة»","url":""}]},{"id":"s6-791","number":791,"surah":6,"verses":[111],"references":[{"surah":6,"verses":[111]}],"verseLabel":"الأنعام: 111","question":"لماذا ترتبت الآيات المفترضة من نزول الملائكة إلى كلام الموتى ثم حشر كل شيء؟","answer":"جاء الترتيب في تصاعد: فنزول الملائكة آية عظيمة، ثم كلام الموتى الذين يعرفونهم أبلغ في المشافهة، ثم حشر كل شيء يجمع أقصى ما يتصورونه من الشواهد. ومع هذا الفرض البالغ يبقى عنادهم مانعًا من الإيمان إلا أن يشاء الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص642–643، تحت «بلاغة ترتيب الجمل الثلاث في الآية»","url":""}]},{"id":"s6-792","number":792,"surah":6,"verses":[111],"references":[{"surah":6,"verses":[111]}],"verseLabel":"الأنعام: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿نزلنا إليهم الملائكة﴾ بتشديد الفعل؟","answer":"التشديد في ﴿نزّلنا﴾ يفيد التكثير أو التدرج؛ أي لو أنزلت الملائكة إنزالًا ظاهرًا متكررًا كما اقترحوا، لما حملهم ذلك على الإيمان مع عنادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص637، تحت «سر التعبير بصيغة التنزيل لا الإنزال»","url":""}]},{"id":"s6-793","number":793,"surah":6,"verses":[111],"references":[{"surah":6,"verses":[111]}],"verseLabel":"الأنعام: 111","question":"لماذا أُسند التكليم إلى الموتى في ﴿وكلمهم الموتى﴾ مع إسناد التنزيل والحشر إلى الله؟","answer":"لأن مقترحهم كان أن يشافههم أموات يعرفونهم ويشهدوا لهم بصدق الرسول؛ فأبرز إسناد التكليم إلى الموتى نفس الصورة التي طلبوها، بدل الاكتفاء بذكر إحيائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص638–639، تحت «سر إسناد التكليم إلى الموتى لا إلى الله»","url":""}]},{"id":"s6-794","number":794,"surah":6,"verses":[111],"references":[{"surah":6,"verses":[111]}],"verseLabel":"الأنعام: 111","question":"ما سر التعبير بالحشر لا بالجمع في قوله تعالى: ﴿وحشرنا عليهم كل شيء﴾؟","answer":"الحشر جمعٌ مع سوق وإزعاج إلى جهة واحدة، فهو أبلغ من مطلق الجمع في تصوير إحضار كل شيء عليهم وإحاطته بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص640–641، تحت عنوان «سر التعبير بالحشر لا بالجمع»","url":""}]},{"id":"s6-1320","number":1320,"surah":6,"verses":[111],"references":[{"surah":6,"verses":[111]}],"verseLabel":"الأنعام: 111","question":"ما دلالة تعدية فعل الحشر بحرف ﴿على﴾؟","answer":"أفادت ﴿على﴾ الاستعلاء والإحاطة؛ فكأن المحشورات تتوارد عليهم من فوق وتحيط بهم، وفي ذلك تقوية لصورة العجز عن الإفلات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص641، تحت عنوان «دلالة تعدية فعل الحشر بحرف على»","url":""}]},{"id":"s6-1321","number":1321,"surah":6,"verses":[111],"references":[{"surah":6,"verses":[111]}],"verseLabel":"الأنعام: 111","question":"كيف توجَّه القراءات القرآنية في قوله تعالى: ﴿قُبُلًا﴾؟","answer":"تتنوع دلالة القراءة بين المقابلة والمعاينة، وبين معنى الجماعات أو الكفلاء؛ فتلتقي الوجوه في تصوير مجيء الأشياء مواجهةً لهم وعلى أتم أنحاء الشهادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص644، تحت عنوان «توجيه القراءات القرآنية»","url":""}]},{"id":"s6-1322","number":1322,"surah":6,"verses":[111],"references":[{"surah":6,"verses":[111]}],"verseLabel":"الأنعام: 111","question":"ما بلاغة اختيار مفردة ﴿قُبُلًا﴾ في الدلالة على المقصود؟","answer":"اختيرت لتصور حضور الأشياء قبالتهم وعيانًا، فلا يبقى عذر ناشئ عن خفاء الدليل أو بعده، ومع ذلك لا يقع إيمانهم إلا بمشيئة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص644–645، تحت عنوان «بلاغة اختيار مفردة قبلا»","url":""}]},{"id":"s6-795","number":795,"surah":6,"verses":[111],"references":[{"surah":6,"verses":[111]}],"verseLabel":"الأنعام: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿ما كانوا ليؤمنوا﴾ باللام؟","answer":"لام الجحود بعد ﴿ما كانوا﴾ تفيد شدة انتفاء الإيمان وعدم استقامتِه منهم مع رسوخ العناد؛ أي لم يكن من شأنهم أن يؤمنوا بهذه المقترحات إلا أن يشاء الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص645، تحت «فائدة التعبير بقوله تعالى: ﴿ما كانوا ليومنوا﴾»","url":""}]},{"id":"s6-796","number":796,"surah":6,"verses":[111],"references":[{"surah":6,"verses":[111]}],"verseLabel":"الأنعام: 111","question":"لماذا استثنى: ﴿إلا أن يشاء الله﴾؟","answer":"الاستثناء يرد الأمر كله إلى مشيئة الله النافذة؛ فنفي إيمانهم معلق بحال عنادهم، ولا يعجز الله أن يخلق الإيمان فيهم أو يوفق من يشاء منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص646–647، تحت «معنى الاستثناء في إلا أن يشاء الله»","url":""}]},{"id":"s6-797","number":797,"surah":6,"verses":[111],"references":[{"surah":6,"verses":[111]}],"verseLabel":"الأنعام: 111","question":"ما الجهل الذي تكشفه خاتمة ﴿ولكن أكثرهم يجهلون﴾ مع كثرة ما يقترحونه من الآيات؟","answer":"هو الجهل بحقيقة الهداية وبالله وقدرته وحكمته؛ فلا تنفع كثرة المقترحات من لا يعرف هذه الحقيقة. وقد يكون الإنسان عالمًا بأمور الدنيا مع بقائه جاهلًا بما يوصله إلى الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص650–651، تحت «غرض التعبير بمفردة يجهلون»","url":""}]},{"id":"s6-798","number":798,"surah":6,"verses":[112],"references":[{"surah":6,"verses":[112]}],"verseLabel":"الأنعام: 112","question":"ما المعنى الإجمالي لقوله تعالى: ﴿وكذلك جعلنا لكل نبي عدوًا شياطين الإنس والجن﴾؟","answer":"تقرر الآية سنة الابتلاء: يكون لكل نبي أعداء من مردة الإنس والجن، يزيّن بعضهم لبعض القول الباطل؛ وفي ذلك تسلية للنبي وتثبيت له.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص654، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s6-799","number":799,"surah":6,"verses":[112],"references":[{"surah":6,"verses":[112]}],"verseLabel":"الأنعام: 112","question":"ما بلاغة استعمال مفردة ﴿عدوًّا﴾ دون «أعداء»؟","answer":"جاء ﴿عدوًّا﴾ مفردًا على إرادة الجنس، فشمل كل صور العداوة وأهلها، وصوّرهم مع كثرتهم كأنهم كتلة واحدة في معاداة الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص657، تحت عنوان «بلاغة استعمال مفردة عدوا دون أعداء»","url":""}]},{"id":"s6-1323","number":1323,"surah":6,"verses":[112],"references":[{"surah":6,"verses":[112]}],"verseLabel":"الأنعام: 112","question":"ما سر إفراد لفظ ﴿عدوًّا﴾ ومجيء ﴿شياطين﴾ جمعًا؟","answer":"وحّد الإفراد حقيقة العداوة وغايتها، بينما كشف جمع ﴿شياطين﴾ كثرة أفرادها وتنوعهم من الإنس والجن؛ فاتحد المقصد وتعدد القائمون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص658، تحت عنوان «سر إفراد لفظ عدوا ومجيء شياطين جمعا»","url":""}]},{"id":"s6-800","number":800,"surah":6,"verses":[112],"references":[{"surah":6,"verses":[112]}],"verseLabel":"الأنعام: 112","question":"ما سرّ تقديم شياطين الإنس على الجن؟","answer":"قُدّم شياطين الإنس لأن عداوتهم أشد ظهورًا ومباشرةً للرسل، ولأن السياق يتحدث عن مجرمي البشر الذين يصدون عن الدعوة، ثم أُلحق بهم شياطين الجن.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص659، تحت «نكتة تقديم الإنس على الجن»","url":""}]},{"id":"s6-801","number":801,"surah":6,"verses":[112],"references":[{"surah":6,"verses":[112]}],"verseLabel":"الأنعام: 112","question":"لماذا عبّر عن تواصلهم بقوله: ﴿يوحي بعضهم إلى بعض﴾؟","answer":"الوحي إلقاء خفي سريع؛ فاستعير لتناقلهم الباطل سرًا، بعضهم يمد بعضًا بوسائل التضليل كما يوحى الكلام الخفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص660–661، تحت «بلاغة اختيار مفردة يوحي»","url":""}]},{"id":"s6-802","number":802,"surah":6,"verses":[112],"references":[{"surah":6,"verses":[112]}],"verseLabel":"الأنعام: 112","question":"ما بلاغة التعبير المجازي في قوله تعالى: ﴿زخرف القول﴾؟","answer":"نقل الزخرف من تزيين الأجسام إلى تزيين الكلام؛ فدل على قول يلمع ظاهره ويستحسن لفظه، مع فساد حقيقته ومقصده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص661–662، تحت عنوان «بلاغة التعبير المجازي»","url":""}]},{"id":"s6-1324","number":1324,"surah":6,"verses":[112],"references":[{"surah":6,"verses":[112]}],"verseLabel":"الأنعام: 112","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿زخرف القول﴾؟","answer":"شُبّه القول الباطل بشيء مزخرف حسن الظاهر يخفي رداءة باطنه، فصورت الاستعارة طريقة الشياطين في تمويه الباطل وإغرائه للسامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص662–663، تحت عنوان «بلاغة الاستعارة في زخرف القول»","url":""}]},{"id":"s6-803","number":803,"surah":6,"verses":[112],"references":[{"surah":6,"verses":[112]}],"verseLabel":"الأنعام: 112","question":"ما الذي يكشفه لفظ ﴿غرورًا﴾ عن غاية ﴿زخرف القول﴾؟","answer":"يكشف أن تزيين القول وسيلة للخداع؛ فإما أن المعنى أنهم يوحي بعضهم إلى بعض ليغروا الناس، وإما أنه إيحاء قائم على التغرير. وفي الوجهين لا تنفصل الزينة الظاهرة عن قصد الإضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص663، تحت «إعراب غرورا وأثره في بيان المعنى»","url":""}]},{"id":"s6-804","number":804,"surah":6,"verses":[112],"references":[{"surah":6,"verses":[112]}],"verseLabel":"الأنعام: 112","question":"ما نكتة المجيء بعنوان الربوبية دون الألوهية في قوله تعالى: ﴿ولو شاء ربك﴾؟","answer":"ناسبت الربوبية مقام التسلية والرعاية؛ فهي تذكّر النبي بأن ربه يتولاه بالتربية والحفظ، وأن ما يقع من العداوة جارٍ بحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص664، تحت عنوان «نكتة المجيء بعنوان الربوبية دون الألوهية»","url":""}]},{"id":"s6-1325","number":1325,"surah":6,"verses":[112],"references":[{"surah":6,"verses":[112]}],"verseLabel":"الأنعام: 112","question":"ما غرض إضافة الرب إلى ضمير المخاطب في قوله تعالى: ﴿ربك﴾؟","answer":"الإضافة تشريف وتطمين وإظهار لعناية خاصة بالنبي؛ فربه الذي يرعاه قادر على منع أعدائه، وإنما يمهلهم لحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص665، تحت عنوان «غرض إضافة الرب إلى ضمير المخاطب»","url":""}]},{"id":"s6-805","number":805,"surah":6,"verses":[112],"references":[{"surah":6,"verses":[112]}],"verseLabel":"الأنعام: 112","question":"ما غرض الأمر في قوله تعالى: ﴿فذرهم﴾؟","answer":"ليس أمرًا بترك دعوتهم مطلقًا، بل هو تهديد وإعراض عن جدال المعاندين بعد البلاغ، مع تفويض أمرهم وجزائهم إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص667، تحت عنوان «غرض الأمر»","url":""}]},{"id":"s6-806","number":806,"surah":6,"verses":[113],"references":[{"surah":6,"verses":[113]}],"verseLabel":"الأنعام: 113","question":"ما سرّ التعبير في قوله تعالى: ﴿ولتصغى إليه أفئدة﴾، فصوّر القلوب تميل؟","answer":"أصل الصغو الميل؛ فصوّر القلوب مائلة نحو زخرف القول لاستحسانه وقبوله، وفي الصورة كشف لانحرافها عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص674–675، تحت «سر التعبير بمفردة ولتصغى»","url":""}]},{"id":"s6-807","number":807,"surah":6,"verses":[113],"references":[{"surah":6,"verses":[113]}],"verseLabel":"الأنعام: 113","question":"ما معنى ﴿أفئدة﴾ في قوله تعالى: ﴿ولتصغى إليه أفئدة الذين لا يؤمنون بالآخرة﴾؟","answer":"الأفئدة جمع فؤاد، وهو القلب من جهة تأثره وتوقد مشاعره؛ والمقصود هنا قلوبهم التي تميل إلى زخرف القول وتقبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص671–672، تحت عنوان «شرح المفردات: أفئدة»","url":""}]},{"id":"s6-1326","number":1326,"surah":6,"verses":[113],"references":[{"surah":6,"verses":[113]}],"verseLabel":"الأنعام: 113","question":"ما الفرق بين الفؤاد والقلب؟","answer":"يبرز الفؤاد جانب المشاعر والوجدان المتوقد، بينما يبرز القلب جهة التقلب والإدراك والتفكير؛ فاختير الفؤاد هنا لميلهم النفسي إلى القول المزخرف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص681، تحت عنوان «الفروق المعجمية: الفؤاد والقلب»","url":""}]},{"id":"s6-808","number":808,"surah":6,"verses":[113],"references":[{"surah":6,"verses":[113]}],"verseLabel":"الأنعام: 113","question":"لماذا قُيدوا بـ﴿الذين لا يؤمنون بالآخرة﴾؟","answer":"خُصوا لأن الإيمان بالآخرة يردع القلب عن الاغترار بالباطل خوف الحساب؛ فمن أنكرها خلا من هذا الرادع فمال إلى الزخرف.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص677–678، تحت «فائدة ذكر قيد بالآخرة والاقتصار عليه»","url":""}]},{"id":"s6-809","number":809,"surah":6,"verses":[113],"references":[{"surah":6,"verses":[113]}],"verseLabel":"الأنعام: 113","question":"لماذا ترتبت الأفعال: ﴿لتصغى... وليرضوه... وليقترفوا﴾ بهذا الترتيب؟","answer":"التدرج يرسم طريق الضلال: تميل القلوب أولًا إلى الزخرف، ثم ترضاه بعد الميل، ثم تتحول القناعة إلى اقتراف فعلي للذنوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص675–676، تحت «دلالة ترتيب الأفعال»","url":""}]},{"id":"s6-810","number":810,"surah":6,"verses":[113],"references":[{"surah":6,"verses":[113]}],"verseLabel":"الأنعام: 113","question":"ما نكتة التعبير بالجملة الاسمية في قوله تعالى: ﴿هم مقترفون﴾؟","answer":"أفادت الجملة الاسمية ثبوت الاقتراف ورسوخه فيهم، لا وقوع فعل عابر؛ فناسبت إصرارهم على اكتساب الإثم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص679، تحت عنوان «نكتة التعبير بالجملة الاسمية»","url":""}]},{"id":"s6-1327","number":1327,"surah":6,"verses":[113],"references":[{"surah":6,"verses":[113]}],"verseLabel":"الأنعام: 113","question":"ما بلاغة جناس الاشتقاق بين ﴿ليقترفوا﴾ و﴿مقترفون﴾؟","answer":"جمع اللفظين أصل اشتقاقي واحد، فربط الغاية بالفعل المتحقق منهم، وأكّد بتآلف الصوت والمعنى أنهم ماضون في اقتراف ما اختاروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص680، تحت عنوان «جناس الاشتقاق»","url":""}]},{"id":"s6-811","number":811,"surah":6,"verses":[114],"references":[{"surah":6,"verses":[114]}],"verseLabel":"الأنعام: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿أفغير الله أبتغي حكمًا﴾ بتقديم ﴿غير الله﴾؟","answer":"قُدّم ﴿غير الله﴾ ليقع عليه الإنكار والحصر: أأطلب سواه حكمًا؟ فالمقصود نفي التحاكم إلى غيره مع قيام الدليل على انفراده بالحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص686–687، تحت «نكتة تقديم أفغير على الفعل أبتغي»","url":""}]},{"id":"s6-812","number":812,"surah":6,"verses":[114],"references":[{"surah":6,"verses":[114]}],"verseLabel":"الأنعام: 114","question":"لماذا اختير ﴿حكمًا﴾، لا: حاكمًا؟","answer":"الحَكَم أبلغ من الحاكم، إذ يدل على من يصلح أن يُرجع إليه في الفصل ويرضى بحكمه، ويقتضي العدل؛ أما الحاكم فقد يعدل وقد يجور. فناسب المقام الذي يقرر انفراد الله بالحكم الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص687–688، تحت «سر التعبير بصيغة حكما لا حاكما»","url":""}]},{"id":"s6-813","number":813,"surah":6,"verses":[114],"references":[{"surah":6,"verses":[114]}],"verseLabel":"الأنعام: 114","question":"ما معنى ﴿مفصلًا﴾ في قوله تعالى: ﴿وهو الذي أنزل إليكم الكتاب مفصلًا﴾؟","answer":"أي مبينًا مميزًا بعضه من بعض، فُصلت فيه الأحكام والدلائل والحق من الباطل بما يغني عن طلب حكم غير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص683–684، تحت عنوان «شرح المفردات: مفصلا»","url":""}]},{"id":"s6-1328","number":1328,"surah":6,"verses":[114],"references":[{"surah":6,"verses":[114]}],"verseLabel":"الأنعام: 114","question":"ما المعنى الإجمالي لقوله تعالى: ﴿أفغير الله أبتغي حكمًا وهو الذي أنزل إليكم الكتاب مفصلًا﴾؟","answer":"ينكر أن يطلب النبي حكمًا غير الله، وقد أنزل الكتاب واضحًا مفصلًا، وأهل الكتاب يعلمون أنه منزل بالحق؛ فلا موضع للارتياب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص685، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s6-814","number":814,"surah":6,"verses":[114],"references":[{"surah":6,"verses":[114]}],"verseLabel":"الأنعام: 114","question":"ما غرض التأكيد في قوله تعالى: ﴿أنه منزل من ربك بالحق﴾؟","answer":"أكد الخبر بـ﴿أن﴾ لمواجهة الإنكار وتثبيت أن مصدر الكتاب هو الله وأن نزوله ملتبس بالحق، مع قيام شهادة أهل الكتاب بذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص695، تحت عنوان «غرض التأكيد أنه منزل»","url":""}]},{"id":"s6-815","number":815,"surah":6,"verses":[114],"references":[{"surah":6,"verses":[114]}],"verseLabel":"الأنعام: 114","question":"ما دلالة الالتفات في قوله تعالى: ﴿فلا تكونن من الممترين﴾؟","answer":"انتقل من الحديث عن أهل الكتاب إلى خطاب النبي مباشرة، فجدّد نشاط السامع وقوى معنى التثبيت واليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص697، تحت عنوان «دلالة الالتفات»","url":""}]},{"id":"s6-1329","number":1329,"surah":6,"verses":[114],"references":[{"surah":6,"verses":[114]}],"verseLabel":"الأنعام: 114","question":"ما غرض النهي في قوله تعالى: ﴿فلا تكونن من الممترين﴾؟","answer":"النهي للتثبيت والدوام على اليقين، لا لوقوع الشك من النبي؛ وفيه تقوية للحجة بعد شهادة أهل الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص698، تحت عنوان «غرض النهي»","url":""}]},{"id":"s6-1330","number":1330,"surah":6,"verses":[114],"references":[{"surah":6,"verses":[114]}],"verseLabel":"الأنعام: 114","question":"ما بلاغة التعريض في قوله تعالى: ﴿فلا تكونن من الممترين﴾؟","answer":"وُجه الخطاب إلى النبي وهو منزّه عن الشك، والمراد التعريض بالممترين وتحذير غيره؛ فإذا نُهي الكامل كان غيره أولى بالحذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص699، تحت عنوان «بلاغة التعريض»","url":""}]},{"id":"s6-816","number":816,"surah":6,"verses":[114],"references":[{"surah":6,"verses":[114]}],"verseLabel":"الأنعام: 114","question":"ما فائدة نون التوكيد في ﴿فلا تكونن من الممترين﴾ بعد شهادة أهل الكتاب بصدق التنزيل؟","answer":"جاء التوكيد لتثبيت الخبر السابق: أنهم يعلمون أنه منزل من الله بالحق؛ فثبوت هذه الحقيقة يقتضي القطع بها وترك الامتراء. ويقوى بذلك التعريض بمن يجادل في القرآن مع وضوح حجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص700، تحت «دلالة التوكيد في قوله تعالى: فلا تكونن من الممترين»","url":""}]},{"id":"s6-817","number":817,"surah":6,"verses":[115],"references":[{"surah":6,"verses":[115]}],"verseLabel":"الأنعام: 115","question":"ما المعنى الإجمالي لقوله تعالى: ﴿وتمت كلمة ربك صدقًا وعدلًا﴾؟","answer":"بلغ كلام الله غايته في الصدق فيما أخبر ووعد، وفي العدل فيما حكم وأمر؛ فلا مبدل لكلماته وهو السميع العليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص703، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s6-1331","number":1331,"surah":6,"verses":[115],"references":[{"surah":6,"verses":[115]}],"verseLabel":"الأنعام: 115","question":"ما سر استعمال ﴿وتمت﴾ دون «كملت»؟","answer":"كلمة الله كاملة في ذاتها أزلًا، ثم تواصل نزولها حتى تم إبلاغها للناس بلا انقطاع؛ فاختير التمام لبلوغ الغاية واتصال النزول، لا لإفادة زوال نقص سابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص704، تحت عنوان «سر استعمال وتمت دون كملت»","url":""}]},{"id":"s6-1332","number":1332,"surah":6,"verses":[115],"references":[{"surah":6,"verses":[115]}],"verseLabel":"الأنعام: 115","question":"ما معنى ﴿وتمت﴾ بين الحقيقة والمجاز؟","answer":"يستعمل التمام حقيقةً في وفرة أجزاء الشيء وبلوغها حدها، ويستعار لتحقق الوعد وظهور صدقه؛ فتدل الآية على استيفاء الكلمة كمالها ووقوع مضمونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص705، تحت عنوان «معنى وتمت بين الحقيقة والمجاز»","url":""}]},{"id":"s6-818","number":818,"surah":6,"verses":[115],"references":[{"surah":6,"verses":[115]}],"verseLabel":"الأنعام: 115","question":"ما توجيه المخصوص بالذكر في قوله تعالى: ﴿صدقًا وعدلًا﴾؟","answer":"خص الصدق والعدل لأن كلام الله يدور على الأخبار والمواعيد وهي صدق، وعلى الأحكام والأوامر وهي عدل؛ فاستوعب الوصفان مقاصد الكلمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص707، تحت عنوان «توجيه المخصوص بالذكر في قوله تعالى: صدقًا وعدلًا»","url":""}]},{"id":"s6-1333","number":1333,"surah":6,"verses":[115],"references":[{"surah":6,"verses":[115]}],"verseLabel":"الأنعام: 115","question":"ما بلاغة مراعاة النظير بين لفظي ﴿صدقًا﴾ و﴿عدلًا﴾؟","answer":"قرن اللفظان المتناسبان؛ فالصدق كمال الخبر، والعدل كمال الحكم، فجمعهما في نسق واحد يبرز تمام كلمة الله في جانبيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص707–708، تحت عنوان «مراعاة النظير بين لفظي صدقا وعدلا»","url":""}]},{"id":"s6-819","number":819,"surah":6,"verses":[115],"references":[{"surah":6,"verses":[115]}],"verseLabel":"الأنعام: 115","question":"ما سرّ تقديم الصدق على العدل؟","answer":"لأن الاقتناع بالحجة يسبق العمل بالحكم؛ فإذا ثبت صدق القرآن وأنه من عند الله، ثبتت عدالة أحكامه. فجاء الصدق أولًا لبناء اليقين الذي يُقبل به التشريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص708، تحت «نكتة تقديم الصدق على العدل»","url":""}]},{"id":"s6-820","number":820,"surah":6,"verses":[115],"references":[{"surah":6,"verses":[115]}],"verseLabel":"الأنعام: 115","question":"ما نكتة إفراد ﴿الكلمة﴾ في قوله تعالى: ﴿وتمت كلمة ربك﴾؟","answer":"أفاد الإفراد أن كلمات الله، على كثرتها، تنتظم في وحدة لا تناقض فيها، وتصدر عن أمر واحد محكم؛ فكأنها كلمة واحدة في الاتساق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص705–706، تحت عنوان «نكتة إفراد الكلمة»","url":""}]},{"id":"s6-1334","number":1334,"surah":6,"verses":[115],"references":[{"surah":6,"verses":[115]}],"verseLabel":"الأنعام: 115","question":"كيف توجَّه القراءات القرآنية في قوله تعالى: ﴿كلمة﴾؟","answer":"قراءة الإفراد تحمل الكلمة على الجنس أو الوحدة الجامعة، وقراءة الجمع تراعي تعدد كلمات الله؛ والمعنيان يلتقيان في تمامها وصدقها وعدلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص706، تحت عنوان «توجيه القراءات القرآنية في قوله تعالى: كلمت»","url":""}]},{"id":"s6-821","number":821,"surah":6,"verses":[115],"references":[{"surah":6,"verses":[115]}],"verseLabel":"الأنعام: 115","question":"لماذا خُتمت بـ﴿وهو السميع العليم﴾؟","answer":"﴿السميع﴾ يناسب أقوال المكذبين ومحاولات التحريف، و﴿العليم﴾ يحيط بأحوالهم ونياتهم وبصدق كلماته؛ فلا يخفى عليه قول ولا باعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص712–713، تحت «بلاغة جملة التذييل: وهو السميع العليم»","url":""}]},{"id":"s6-822","number":822,"surah":6,"verses":[116],"references":[{"surah":6,"verses":[116]}],"verseLabel":"الأنعام: 116","question":"لماذا حذّر من طاعة ﴿أكثر من في الأرض﴾؟","answer":"حذّر من الأكثرية لأن كثرة أهل الأرض ليست معيارًا للحق؛ فالغالب يومئذ يتبع الشرك والعادات، وطاعته تصرف عن سبيل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص719–720، تحت «دلالة ذكر الأكثرية»","url":""}]},{"id":"s6-823","number":823,"surah":6,"verses":[116],"references":[{"surah":6,"verses":[116]}],"verseLabel":"الأنعام: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿يضلوك عن سبيل الله﴾، فعُدّي الإضلال بـ﴿عن﴾؟","answer":"تعدية الإضلال بـ﴿عن﴾ تفيد الصرف والإبعاد؛ فكأن سبيل الله طريق مستقيم يحاولون تحويل السائر عنه إلى جهة أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص723–724، تحت «بلاغة التمثيل في قوله تعالى: يضلوك عن سبيل الله»","url":""}]},{"id":"s6-824","number":824,"surah":6,"verses":[116],"references":[{"surah":6,"verses":[116]}],"verseLabel":"الأنعام: 116","question":"ما غرض القصر في قوله تعالى: ﴿إن يتبعون إلا الظن﴾؟","answer":"قصر اتباعهم على الظن بطريق النفي والاستثناء، فنفى أن يكون لهم علم أو حجة، وشدد في كشف فساد مصدر اعتقادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص725، تحت عنوان «غرض القصر في قوله تعالى: إن يتبعون إلا الظن»","url":""}]},{"id":"s6-825","number":825,"surah":6,"verses":[116],"references":[{"surah":6,"verses":[116]}],"verseLabel":"الأنعام: 116","question":"ما غرض القصر في قوله تعالى: ﴿وإن هم إلا يخرصون﴾؟","answer":"حصر حالهم في الخرص، أي القول بالتخمين من غير علم؛ فليس ما يصدر عنهم تحقيقًا ولا حجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص726، تحت عنوان «غرض القصر في وإن هم إلا يخرصون»","url":""}]},{"id":"s6-826","number":826,"surah":6,"verses":[116],"references":[{"surah":6,"verses":[116]}],"verseLabel":"الأنعام: 116","question":"ما سر التعبير بمفردة الخرص وبالفعل المضارع في قوله تعالى: ﴿يخرصون﴾؟","answer":"الخرص قول مبني على الظن والتقدير لا على العلم، والمضارع يصور تجدده واستمرارهم فيه كلما تكلموا في الدين بغير حجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص726–727، تحت عنوان «سر التعبير بمفردة الخرص وبالفعل المضارع»","url":""}]},{"id":"s6-1335","number":1335,"surah":6,"verses":[116],"references":[{"surah":6,"verses":[116]}],"verseLabel":"الأنعام: 116","question":"ما الفرق بين الخرص والكذب؟","answer":"الخرص حكم بالتخمين من غير علم، فقد يوافق الواقع اتفاقًا أو يخالفه، أما الكذب فهو الإخبار بخلاف الواقع؛ ولما كان قولهم بلا بينة أطلق عليه الخرص.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص728–729، تحت عنوان «الفروق المعجمية: الخرص والكذب»","url":""}]},{"id":"s6-827","number":827,"surah":6,"verses":[117],"references":[{"surah":6,"verses":[117]}],"verseLabel":"الأنعام: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿إن ربك هو أعلم من يضل﴾ بضمير الفصل؟","answer":"ضمير الفصل ﴿هو﴾ يقصر كمال العلم على الله ويؤكد أن الحكم على الضال والمهتدي ليس للأكثرية ولا للظنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص732، تحت «نكتة استعمال ضمير الفصل هو»","url":""}]},{"id":"s6-828","number":828,"surah":6,"verses":[117],"references":[{"surah":6,"verses":[117]}],"verseLabel":"الأنعام: 117","question":"لماذا قُدّم ذكر علم الله بمن يضل على ذكر علمه بالمهتدين؟","answer":"لأن السياق يعالج الضلال ويحذر من اتباع أهله؛ فجاء البدء بهم أنسب بالمقام. ثم ذُكر المهتدون ليكتمل بيان إحاطة علم الله بالفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص733، تحت «بلاغة تقديم علمه بمن يضل عن سبيله على علمه بالمهتدين»","url":""}]},{"id":"s6-829","number":829,"surah":6,"verses":[117],"references":[{"surah":6,"verses":[117]}],"verseLabel":"الأنعام: 117","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿من يضل عن سبيله﴾؟","answer":"استعير السبيل للدين الحق، وصُوّر الضال بمسافر حاد عن الطريق الواضح؛ فحوّل الضلال المعنوي إلى مشهد محسوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص733، تحت عنوان «بلاغة الاستعارة في قوله تعالى: من يضل عن سبيله»","url":""}]},{"id":"s6-1336","number":1336,"surah":6,"verses":[117],"references":[{"surah":6,"verses":[117]}],"verseLabel":"الأنعام: 117","question":"ما بلاغة اختلاف المقابلة بين جملتي ﴿أعلم من يضل﴾ و﴿أعلم بالمهتدين﴾؟","answer":"جاء الضلال فعلًا مضارعًا مفردًا لتجدد طرائقه، وجاءت الهداية اسمًا مجموعًا لثبات أهلها؛ وذُكر السبيل مع الضلال لكثرة سبله، بينما سبيل الهدى واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص734، تحت عنوان «بلاغة اختلاف المقابلة بين جملتي أعلم من يضل وأعلم بالمهتدين»","url":""}]},{"id":"s6-830","number":830,"surah":6,"verses":[117],"references":[{"surah":6,"verses":[117]}],"verseLabel":"الأنعام: 117","question":"لماذا عُدّي العلم في الأولى بلا باء وفي الثانية ﴿بالمهتدين﴾؟","answer":"يذكر المصدر أن في ﴿أعلم من يضل﴾ إيجازًا بالحذف: إما حذف الباء، أي أعلم بمن يضل، وإما تقدير فعل يعلم تعلق به ﴿من يضل﴾. ثم جاء ﴿بالمهتدين﴾ مصرحًا بالباء؛ فاختلف التعبير مع بقاء إحاطة العلم بالفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص732–733، تحت «بلاغة الإيجاز بالحذف في قوله تعالى: أعلم من يضل»","url":""}]},{"id":"s6-831","number":831,"surah":6,"verses":[118],"references":[{"surah":6,"verses":[118]}],"verseLabel":"الأنعام: 118","question":"لماذا فُرع الأمر بالأكل بالفاء: ﴿فكلوا مما ذكر اسم الله عليه﴾؟","answer":"الفاء تفرع الأمر على ثبوت علم الله بالمهتدين وعلى إبطال ظنون المشركين؛ فإذا كان حكمه هو الحق فكلوا مما أباحه وذُكر اسمه عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص737، تحت «معنى الفاء في قوله تعالى: ﴿فكلوا﴾»","url":""}]},{"id":"s6-832","number":832,"surah":6,"verses":[118],"references":[{"surah":6,"verses":[118]}],"verseLabel":"الأنعام: 118","question":"لماذا عُبّر عن الذبائح بـ﴿ما ذُكر اسم الله عليه﴾ بدل تسميتها مباشرة؟","answer":"لإبراز الوصف المقصود في مقام الرد على المشركين: ذكر اسم الله عليها، وفيه تشريف وتعريض بما يذبحونه على غير اسمه. فالتعبير بالموصول يجعل هذه الصفة موضع الانتباه، بدل مجرد اسم المأكول.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص739، تحت «نكتة استعمال الموصول في قوله تعالى: مما ذكر اسم الله عليه»","url":""}]},{"id":"s6-833","number":833,"surah":6,"verses":[118],"references":[{"surah":6,"verses":[118]}],"verseLabel":"الأنعام: 118","question":"لماذا قُيّد الإيمان بـ﴿بآياته﴾ في ﴿إن كنتم بآياته مؤمنين﴾؟","answer":"لأن السياق في آيات الله وحججه وكتابه المفصل؛ فجاء القيد ليربط امتثال الحكم بالإيمان بتلك الآيات. فمن صدقها أخذ بما بيّنته، ولم يجعل ظنون المشركين مرجعًا لحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص741، تحت «نكتة ذكر قيد بآياته»","url":""}]},{"id":"s6-834","number":834,"surah":6,"verses":[119],"references":[{"surah":6,"verses":[119]}],"verseLabel":"الأنعام: 119","question":"ما بلاغة التركيب في قوله تعالى: ﴿وما لكم ألا تأكلوا﴾ وغرضه البياني؟","answer":"سأل عن الشيء الثابت لهم الذي يمنعهم من الأكل، بدل النهي المباشر عن الترك؛ فكان أبلغ في نفي كل مسوغ وفي تقريعهم على الامتناع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص745–746، تحت عنوان «بلاغة التركيب في قوله وما لكم ألا تأكلوا وغرضه البياني»","url":""}]},{"id":"s6-835","number":835,"surah":6,"verses":[119],"references":[{"surah":6,"verses":[119]}],"verseLabel":"الأنعام: 119","question":"ما أثر البناء للمجهول في قراءة ﴿وقد فُصِّل لكم ما حُرِّم عليكم﴾؟","answer":"يوجه العناية إلى حصول البيان وعموم ما فُصِّل، بينما تبرز قراءة البناء للفاعل الامتنان بإسناد التفصيل إلى الله. فتتكامل القراءتان في بيان النعمة وشمول البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص750، تحت «توجيه القراءات القرآنية في قوله: ﴿وقد فصل لكم ما حرم عليكم﴾»","url":""}]},{"id":"s6-836","number":836,"surah":6,"verses":[119],"references":[{"surah":6,"verses":[119]}],"verseLabel":"الأنعام: 119","question":"لماذا ذُكر استثناء الاضطرار في سياق الإنكار على من يمتنع عن الحلال؟","answer":"يزيد الاستثناء معنى الإباحة وضوحًا: فالمحرّم نفسه يباح عند الاضطرار، فكيف يُترك ما أباحه الله في حال الاختيار؟ وفي هذا إبراز لسعة الرحمة وقطع لشبهة الامتناع عن الحلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص751–752، تحت «دلالة إلا الاستثنائية في قوله: إلا ما اضطررتم إليه»","url":""}]},{"id":"s6-837","number":837,"surah":6,"verses":[119],"references":[{"surah":6,"verses":[119]}],"verseLabel":"الأنعام: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿ليضلون بأهوائهم بغير علم﴾، فجمع الأهواء؟","answer":"جُمعت الأهواء لتعدد شهواتهم ومذاهبهم الباطلة في التحليل والتحريم، وكلها صادرة بلا علم ولا وحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص756–757، تحت «دلالة جمع الهوى في قوله تعالى: بأهوائهم»","url":""}]},{"id":"s6-838","number":838,"surah":6,"verses":[119],"references":[{"surah":6,"verses":[119]}],"verseLabel":"الأنعام: 119","question":"ما دلالة تذييل الآية بقوله تعالى: ﴿إن ربك هو أعلم بالمعتدين﴾؟","answer":"ذيلت الآية بحكم عام يقرر إحاطة علم الله بمن يتجاوز حدوده؛ وفيه وعيد لمن يضل الناس أو يحرم بغير سلطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص757–758، تحت عنوان «دلالة تذييل الآية بقوله إن ربك هو أعلم بالمعتدين»","url":""}]},{"id":"s6-1337","number":1337,"surah":6,"verses":[119],"references":[{"surah":6,"verses":[119]}],"verseLabel":"الأنعام: 119","question":"ما غرض التوكيد في قوله تعالى: ﴿إن ربك هو أعلم بالمعتدين﴾؟","answer":"أكد الخبر بـ﴿إن﴾ وضمير الفصل ﴿هو﴾ لتثبيت كمال علم الله بالمعتدين واختصاصه بالإحاطة التامة بحالهم وجزائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص757–758، تحت عنوان «غرض التوكيد»","url":""}]},{"id":"s6-1338","number":1338,"surah":6,"verses":[119],"references":[{"surah":6,"verses":[119]}],"verseLabel":"الأنعام: 119","question":"ما دلالة استعمال وصف ﴿المعتدين﴾ دون غيره؟","answer":"وصفهم بالاعتداء لأنهم تجاوزوا حدود الله في التشريع والعمل والإضلال؛ فجمع الوصف صور تجاوزهم وربط الوعيد بسبب استحقاقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص758–759، تحت عنوان «دلالة استعمال وصف المعتدين دون غيره»","url":""}]},{"id":"s6-839","number":839,"surah":6,"verses":[120],"references":[{"surah":6,"verses":[120]}],"verseLabel":"الأنعام: 120","question":"ما معنى التعريف في لفظ ﴿الإثم﴾ في قوله تعالى: ﴿وذروا ظاهر الإثم وباطنه﴾؟","answer":"التعريف للجنس والاستغراق، فيشمل كل ما يصدق عليه اسم الإثم، ظاهرًا كان أو باطنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص765، تحت عنوان «معنى التعريف في لفظ الإثم»","url":""}]},{"id":"s6-1339","number":1339,"surah":6,"verses":[120],"references":[{"surah":6,"verses":[120]}],"verseLabel":"الأنعام: 120","question":"ما بلاغة الاستعارة في مقابلة ظاهر الإثم بباطنه؟","answer":"صُوّر الإثم بشيء له ظاهر يبدو وباطن يخفى، فاستوعبت المقابلة أفعال الجوارح وما تستتر به القلوب والنيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص766، تحت عنوان «بلاغة الاستعارة في مقابلة ظاهر الإثم بباطنه»","url":""}]},{"id":"s6-840","number":840,"surah":6,"verses":[120],"references":[{"surah":6,"verses":[120]}],"verseLabel":"الأنعام: 120","question":"ما سرّ تقديم ظاهر الإثم على باطنه؟","answer":"لأن التخلص مما ظهر من الإثم بداية عملية للتدرج إلى ترك باطنه؛ فالظاهر أشد انتشارًا وتأثيرًا في النفس والمجتمع، وتركه يعين على إصلاح الداخل. وجمعهما في الأمر يمنع الاكتفاء بإصلاح الظاهر وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص764–765، تحت «حكمة تقديم لفظ ظاهر على باطنه»","url":""}]},{"id":"s6-841","number":841,"surah":6,"verses":[120],"references":[{"surah":6,"verses":[120]}],"verseLabel":"الأنعام: 120","question":"لماذا جاء اكتساب الإثم بصيغة المضارع في ﴿إن الذين يكسبون الإثم﴾؟","answer":"يصور المضارع تجدّد اكتساب الإثم واستمراره، فيربط الوعيد بالفعل الذي يزاولونه. وفيه تنبيه إلى أن الإثم قد يتدرج ويتكرر حتى يستحكم، فينبغي قطعه من بدايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص767، تحت «نكتة التعبير بالفعل المضارع في إن الذين يكسبون الإثم»","url":""}]},{"id":"s6-842","number":842,"surah":6,"verses":[120],"references":[{"surah":6,"verses":[120]}],"verseLabel":"الأنعام: 120","question":"ما سرّ التعبير في قوله تعالى في الجزاء: ﴿بما كانوا يقترفون﴾، لا: بما كانوا يكسبون؟","answer":"الكسب يستعمل في الخير والشر، أما الاقتراف فيغلب في اكتساب السيئات، وفي صيغته مبالغة تلائم ذم الفعل. فناسب ذكره في الجزاء أن يبرز قبح ما اكتسبوه ومخالفتهم للفطرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص769، تحت «سر استعمال يقترفون بدلا من يكسبون»","url":""}]},{"id":"s6-843","number":843,"surah":6,"verses":[121],"references":[{"surah":6,"verses":[121]}],"verseLabel":"الأنعام: 121","question":"لماذا قال ﴿لم يُذكر اسم الله عليه﴾ ولم يقل: ذُكر عليه غير اسم الله؟","answer":"لأن النهي يبرز ترك اسم الله، فلا يقتصر على التصريح باسم غيره. أما التعبير بذكر اسم آخر فقد يوهم خروج ما تُركت تسميته أصلًا من الكلام. وبهذا يظهر الفرق الذي قرره المصدر بين العبارتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص774–775، تحت «سر النفي بقوله لم يذكر دون غيره من التعبيرات»","url":""}]},{"id":"s6-844","number":844,"surah":6,"verses":[121],"references":[{"surah":6,"verses":[121]}],"verseLabel":"الأنعام: 121","question":"لماذا أكد: ﴿وإنه لفسق﴾؟","answer":"اجتمع ﴿إن﴾ واللام لتقرير وصف الفسق بقوة وتنفير المخاطب من الإقدام عليه. فالتوكيد يحسم التردد ويجعل النهي أشد وقعًا من خبر يلقى بلا توكيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص776، تحت «بلاغة التوكيد في قوله تعالى: وإنه لفسق»","url":""}]},{"id":"s6-845","number":845,"surah":6,"verses":[121],"references":[{"surah":6,"verses":[121]}],"verseLabel":"الأنعام: 121","question":"إلى ماذا يعود الضمير في ﴿وإنه لفسق﴾؟","answer":"الضمير يعود إلى الأكل المفهوم من النهي، أو إلى ما لم يذكر اسم الله عليه؛ والمعنى في الوجهين أن تناول هذه الذبيحة فسق.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص776، تحت «تعيين مرجع الضمير في قوله تعالى: وإنه لفسق»","url":""}]},{"id":"s6-846","number":846,"surah":6,"verses":[121],"references":[{"surah":6,"verses":[121]}],"verseLabel":"الأنعام: 121","question":"لماذا وصف وسوسة الشياطين بأنها ﴿يوحون إلى أوليائهم﴾؟","answer":"سميت وسوستهم وحيًا لأنها إلقاء خفي سريع إلى أوليائهم، يمدونهم بحجج باطلة ليجادلوا المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص778، تحت «سر استعمال الإيحاء دون مرادفاته»","url":""}]},{"id":"s6-847","number":847,"surah":6,"verses":[121],"references":[{"surah":6,"verses":[121]}],"verseLabel":"الأنعام: 121","question":"ما نكتة استعمال المجادلة في قوله تعالى: ﴿ليجادلوكم﴾؟","answer":"المجادلة محاولة فتل الخصم عن رأيه وردّه عنه بالحجاج؛ فدل اللفظ على أنهم لا يطلبون الحق، بل يريدون التمويه وإرجاع المؤمنين عن حكم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص779، تحت عنوان «نكتة استعمال المجادلة في قوله تعالى: ليجادلوكم»","url":""}]},{"id":"s6-1340","number":1340,"surah":6,"verses":[121],"references":[{"surah":6,"verses":[121]}],"verseLabel":"الأنعام: 121","question":"ما الفرق بين الجدال والمراء؟","answer":"الجدال مراجعة الخصم بقوة بقصد رده عن رأيه، وأصله من شدة الفتل؛ والمراء مخاصمة في الحق بعد ظهوره ناشئة عن اللجاج والشك.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص781، تحت عنوان «الفروق المعجمية: الجدال والمراء»","url":""}]},{"id":"s6-848","number":848,"surah":6,"verses":[121],"references":[{"surah":6,"verses":[121]}],"verseLabel":"الأنعام: 121","question":"ما غرض حذف متعلق فعل الشرط في قوله تعالى: ﴿وإن أطعتموهم﴾؟","answer":"حذف المتعلق اعتمادًا على السياق، أي إن أطعتموهم في استحلال ما حرمه الله؛ وفي الحذف إيجاز وتركيز على خطورة أصل الطاعة في هذا التشريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص780، تحت عنوان «غرض حذف متعلق فعل الشرط وإن أطعتموهم»","url":""}]},{"id":"s6-1341","number":1341,"surah":6,"verses":[121],"references":[{"surah":6,"verses":[121]}],"verseLabel":"الأنعام: 121","question":"ما بلاغة التوكيد في جملة ﴿إنكم لمشركون﴾؟","answer":"أكد جواب الشرط بـ﴿إن﴾ واللام لأن تحريم الإسلام أو تحليله على خلاف حكم الله يساوي الشرك، وهو حكم شديد يحتاج إلى تثبيت وقطع للالتباس.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص781، تحت عنوان «بلاغة التوكيد في جملة إنكم لمشركون»","url":""}]},{"id":"s6-849","number":849,"surah":6,"verses":[122],"references":[{"surah":6,"verses":[122]}],"verseLabel":"الأنعام: 122","question":"لماذا شبّه الكافر بالميت والمؤمن بمن أحياه الله؟","answer":"شُبه الكفر بالموت لأنه يعطل القلب عن إدراك الحق والانتفاع به، وشُبه الإيمان بالإحياء لأنه يعيد إليه البصيرة والحركة في طريق الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص784–785، تحت «براعة الاستعارة في استعمال لفظ الموت والإحياء»","url":""}]},{"id":"s6-850","number":850,"surah":6,"verses":[122],"references":[{"surah":6,"verses":[122]}],"verseLabel":"الأنعام: 122","question":"ما بلاغة الإطناب في جملة ﴿وجعلنا له نورًا يمشي به في الناس﴾؟","answer":"فصلت الجملة أثر الإحياء بعد الموت، فبينت أن المهتدي مُنح نور الإيمان والوحي وصار يعمل به بين الناس؛ فزاد التفصيل صورة الهداية وضوحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص785، تحت عنوان «بلاغة الإطناب في جملة وجعلنا له نورا يمشي به في الناس»","url":""}]},{"id":"s6-1342","number":1342,"surah":6,"verses":[122],"references":[{"surah":6,"verses":[122]}],"verseLabel":"الأنعام: 122","question":"ما بلاغة الاستعارة في استعمال ﴿يمشي﴾؟","answer":"استعير المشي للتصرف في الحياة على بصيرة؛ فالمؤمن ينتقل في أعماله ومعاملاته مستضيئًا بنور الإيمان كما يمشي المرء بضوء محسوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص786، تحت عنوان «بلاغة الاستعارة في استعمال يمشي»","url":""}]},{"id":"s6-1343","number":1343,"surah":6,"verses":[122],"references":[{"surah":6,"verses":[122]}],"verseLabel":"الأنعام: 122","question":"ما دلالة استعمال حرف الظرفية في قوله تعالى: ﴿في الناس﴾؟","answer":"صورت ﴿في﴾ صاحب النور منغمسًا في مجتمع الناس مؤثرًا فيهم؛ ولو قيل «بين الناس» لأفاد مجرد الحركة في وسطهم دون هذه الدلالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص787، تحت عنوان «دلالة استعمال حرف الظرفية في الناس»","url":""}]},{"id":"s6-851","number":851,"surah":6,"verses":[122],"references":[{"surah":6,"verses":[122]}],"verseLabel":"الأنعام: 122","question":"لماذا عُدّي المشي بالنور بالباء؟","answer":"الباء سببية؛ أي إن النور الذي جعله الله له كان سبب هدايته المعبر عنها بالمشي بين الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص786، تحت «معنى حرف الباء الداخل على الضمير به»","url":""}]},{"id":"s6-852","number":852,"surah":6,"verses":[122],"references":[{"surah":6,"verses":[122]}],"verseLabel":"الأنعام: 122","question":"ما براعة التمثيل في قوله تعالى: ﴿كمن مثله في الظلمات﴾؟","answer":"قابل التمثيل هيئة من أحياه الله وجعل له نورًا بهيئة مشرك باق في ظلمات لا يخرج منها، فنفى الاستفهام الإنكاري مساواة الحالين في صورة محسوسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص787، تحت عنوان «براعة التمثيل في قوله تعالى: كمن مثله في الظلمات»","url":""}]},{"id":"s6-1344","number":1344,"surah":6,"verses":[122],"references":[{"surah":6,"verses":[122]}],"verseLabel":"الأنعام: 122","question":"ما بلاغة المجاز بالحذف في قوله تعالى: ﴿كمن مثله في الظلمات﴾؟","answer":"حذف المشبه وقدّر: «كمن مثله مثل ميت»؛ لأن الفريقين اشتركا أولًا في حال الشرك، ثم أحيا الله أحدهما بالإيمان وبقي الآخر في الظلمات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص787، تحت عنوان «بلاغة المجاز بالحذف في قوله تعالى: كمن مثله في الظلمات»","url":""}]},{"id":"s6-853","number":853,"surah":6,"verses":[122],"references":[{"surah":6,"verses":[122]}],"verseLabel":"الأنعام: 122","question":"لماذا جُمعت ﴿الظلمات﴾ وأُفرد ﴿نورًا﴾؟","answer":"أُفرد النور لأن الحق واحد متسق، وجُمعت الظلمات لتعدد طرق الكفر والجهل والشهوة والشبهات.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص788، تحت «نكتة إفراد نورا وجمع الظلمات»","url":""}]},{"id":"s6-854","number":854,"surah":6,"verses":[122],"references":[{"surah":6,"verses":[122]}],"verseLabel":"الأنعام: 122","question":"لماذا قوبل ﴿فأحييناه﴾ بقوله ﴿ليس بخارج منها﴾؟","answer":"كلاهما كان في ضلال، لكن الأول انتقل منه إلى حياة الإيمان بإنقاذ الله له، والثاني بقي غارقًا في الظلمات. فتبرز المقابلة الفرق بين نعمة الانتقال إلى الهدى وشدة البقاء في الضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص788–789، تحت «فائدة مقابلة فأحييناه بقوله ليس بخارج منها»","url":""}]},{"id":"s6-855","number":855,"surah":6,"verses":[123],"references":[{"surah":6,"verses":[123]}],"verseLabel":"الأنعام: 123","question":"ما وجه التشبيه في ﴿وكذلك جعلنا في كل قرية أكابر مجرميها﴾؟","answer":"يربط حال أكابر المجرمين في مكة بنظرائهم في القرى الأخرى؛ فما يلقاه الرسول من تصدرهم للصد والمكر قد واجهته دعوات الرسل قبله. وفي هذا تسلية له وتحذير لهم من مآل من سبقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص795، تحت «بلاغة التشبيه وتعيين المشار إليه باسم الإشارة في قوله كذلك»","url":""}]},{"id":"s6-856","number":856,"surah":6,"verses":[123],"references":[{"surah":6,"verses":[123]}],"verseLabel":"الأنعام: 123","question":"ما سرّ تقديم ﴿في كل قرية﴾ على ﴿أكابر مجرميها﴾؟","answer":"قُدّم الظرف لإفادة العموم والاهتمام بانتشار السنة: في كل قرية يوجد هذا الصنف، لا في قرية مخصوصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص796، تحت «نكتة تقديم في كل قرية على أكابر مجرميها»","url":""}]},{"id":"s6-857","number":857,"surah":6,"verses":[123],"references":[{"surah":6,"verses":[123]}],"verseLabel":"الأنعام: 123","question":"ما معنى الجعل ودلالة إسناده إلى ضمير العظمة في قوله تعالى: ﴿وكذلك جعلنا في كل قرية أكابر مجرميها﴾؟","answer":"الجعل هنا تصيير بحسب سنن الابتلاء والاجتماع، وإسناده إلى ضمير العظمة يبرز نفاذ القدرة والحكمة في تدبير أحوال القرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص795–796، تحت عنوان «معنى الجعل ودلالة إسناده إلى ضمير العظمة»","url":""}]},{"id":"s6-1345","number":1345,"surah":6,"verses":[123],"references":[{"surah":6,"verses":[123]}],"verseLabel":"الأنعام: 123","question":"لماذا خُص الأكابر بالذكر دون الأصاغر في قوله تعالى: ﴿أكابر مجرميها﴾؟","answer":"لأن الأكابر أقدر بمالهم ونفوذهم على تدبير المكر، وأشد حرصًا على بقاء رئاستهم، والأصاغر تبع لهم؛ فكان أثر فسادهم أوسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص796–797، تحت عنوان «توجيه تخصيص الأكابر بالذكر دون الأصاغر»","url":""}]},{"id":"s6-858","number":858,"surah":6,"verses":[123],"references":[{"surah":6,"verses":[123]}],"verseLabel":"الأنعام: 123","question":"ما سرّ التعبير في قوله تعالى: ﴿ليمكروا فيها﴾، فجعل المكر غاية لمكانتهم؟","answer":"من وجوهها أنها لام العاقبة: آل ما أُعطوه من مكانة إلى المكر بسبب اختيارهم. ويذكر المصدر وجه التعليل ضمن حكمة الابتلاء والصراع الذي يظهر به الحق، ولا يلزم منه حصر حكمة الجعل في المكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص798–799، تحت «نوع اللام في قوله تعالى: ليمكروا فيها»","url":""}]},{"id":"s6-859","number":859,"surah":6,"verses":[123],"references":[{"surah":6,"verses":[123]}],"verseLabel":"الأنعام: 123","question":"ما سرّ التعبير في قوله تعالى: ﴿وما يمكرون إلا بأنفسهم﴾ بطريق القصر؟","answer":"القصر يقلب أثر المكر عليهم: يظنون أنهم يضرون الدعوة، والحقيقة أن وباله وعقوبته لا يعودان إلا إلى أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج11، ص799–800، تحت «دلالة القصر وبلاغته في قوله تعالى: وما يمكرون إلا بأنفسهم»","url":""}]},{"id":"s6-861","number":861,"surah":6,"verses":[124],"references":[{"surah":6,"verses":[124]}],"verseLabel":"الأنعام: 124","question":"ما دلالة بناء الفعل للمجهول في قولهم: ﴿لن نؤمن حتى نؤتى مثل ما أوتي رسل الله﴾؟","answer":"البناء للمجهول يعكس قصر نظرهم على نيل العطاء الحسي والمنزلة، دون التفكر في واهب الرسالة وحكمته؛ فجعلوا غايتهم أن يُؤتوا مثل الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص14–15، تحت «نكتة إسناد الفعل إلى المفعول في قوله تعالى حتى نؤتى؛ نكتة إسناد الفعل إلى المفعول في مثل ما أوتي رسل الله»","url":""}]},{"id":"s6-862","number":862,"surah":6,"verses":[124],"references":[{"surah":6,"verses":[124]}],"verseLabel":"الأنعام: 124","question":"ما دلالة الرد بقوله تعالى: ﴿الله أعلم حيث يجعل رسالته﴾؟","answer":"الرد يبين أن الرسالة اصطفاء إلهي قائم على العلم بمن يصلح لحملها، لا مرتبة تُنال بالزعامة أو المال أو الحسد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص17–18، تحت «بلاغة البدء بلفظ الجلالة في قوله تعالى الله أعلم حيث يجعل رسالته»","url":""}]},{"id":"s6-863","number":863,"surah":6,"verses":[124],"references":[{"surah":6,"verses":[124]}],"verseLabel":"الأنعام: 124","question":"لماذا اختير لفظ ﴿صغار﴾ لعقوبة المستكبرين؟","answer":"الصغار ذلّ يصحبه إقرار بالهوان واستسلام له؛ فناسب من تكبروا وطلبوا منزلة الرسل أن يكون جزاؤهم ذلةً تهدم استعلاءهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص21، تحت عنوان «سر استعمال لفظ صغار دون مرادفاته»","url":""}]},{"id":"s6-1346","number":1346,"surah":6,"verses":[124],"references":[{"surah":6,"verses":[124]}],"verseLabel":"الأنعام: 124","question":"ما الفرق بين الصغار والذلة؟","answer":"الذلة انقياد وقهر قد يقعان من غير اعتراف، أما الصغار فيضم إلى الذل اعتراف صاحبه به وإظهاره صغيرًا حقيرًا؛ لذلك كان أشد في تقريع المستكبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص24، تحت عنوان «الفروق المعجمية: الصغار والذلة»","url":""}]},{"id":"s6-864","number":864,"surah":6,"verses":[124],"references":[{"surah":6,"verses":[124]}],"verseLabel":"الأنعام: 124","question":"ما دلالة ﴿كانوا﴾ في قوله تعالى: ﴿بما كانوا يمكرون﴾؟","answer":"دل الفعل الماضي الناقص على أن مكرهم لم يكن عارضًا، بل حالًا مستمرةً مستقرةً فيهم؛ فاستحقوا العقاب على ما داوموا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص23، تحت عنوان «بلاغة ذكر كانوا»","url":""}]},{"id":"s6-1347","number":1347,"surah":6,"verses":[124],"references":[{"surah":6,"verses":[124]}],"verseLabel":"الأنعام: 124","question":"لماذا عبّر عن عملهم بالمكر لا بمجرد الإجرام؟","answer":"لأن المكر يكشف تدبير الشر في خفاء، ويصور حيلهم لصد الناس عن الحق وإيذاء الدعوة؛ فهو أخص بحالهم وأشد كشفًا لخطرهم من لفظ الإجرام العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص23، تحت عنوان «بلاغة التعبير بالمكر دون يجرمون»","url":""}]},{"id":"s6-865","number":865,"surah":6,"verses":[125],"references":[{"surah":6,"verses":[125]}],"verseLabel":"الأنعام: 125","question":"ما الصورة التي يرسمها قوله تعالى: ﴿يشرح صدره للإسلام﴾؟","answer":"صوّر تهيئة القلب لقبول الإيمان بانشراح جسم يتسع بعد ضيق؛ فاستحضر ما يجده المهتدي من قبول وطمأنينة ورغبة في الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص29، تحت عنوان «بلاغة الاستعارة التمثيلية في جملة يشرح صدره»","url":""}]},{"id":"s6-866","number":866,"surah":6,"verses":[125],"references":[{"surah":6,"verses":[125]}],"verseLabel":"الأنعام: 125","question":"لماذا أُتبع وصف الصدر بالضيق بوصفه ﴿حرجًا﴾؟","answer":"لأن الحرج غاية الضيق، فجاء بعد الضيق ليؤكده ويزيده حتى يصور صدرًا لا يجد الإيمان فيه منفذًا ولا متسعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص32، تحت عنوان «نكتة إتباع وصف الضيق بالحرج»","url":""}]},{"id":"s6-1348","number":1348,"surah":6,"verses":[125],"references":[{"surah":6,"verses":[125]}],"verseLabel":"الأنعام: 125","question":"ما الصورة التي يرسمها وصف الصدر بأنه ﴿حرج﴾؟","answer":"استُعير الحرج من الشجر الكثيف المتشابك الذي لا يُوصل إليه، فصوّر قلب المعرض منغلقًا لا يتسع للإيمان ولا يستقر فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص33، تحت عنوان «بلاغة الاستعارة في لفظ حرجا»","url":""}]},{"id":"s6-867","number":867,"surah":6,"verses":[125],"references":[{"surah":6,"verses":[125]}],"verseLabel":"الأنعام: 125","question":"ما بلاغة تشبيه الضال بمن ﴿يصعد في السماء﴾؟","answer":"حوّل التشبيه نفوره من الإيمان وضيق صدره به إلى مشهد إنسان يتكلف صعود السماء فيعجز ويشتد نفسه؛ فصار الضيق المعنوي عناءً محسوسًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص33، تحت عنوان «بلاغة التشبيه في قوله تعالى كأنما يصعد»","url":""}]},{"id":"s6-1349","number":1349,"surah":6,"verses":[125],"references":[{"surah":6,"verses":[125]}],"verseLabel":"الأنعام: 125","question":"ما أثر التضعيف في قراءة ﴿يصّعّد﴾؟","answer":"زاد التضعيف معنى التكلف والمبالغة وتكرر المحاولة؛ فصوّر صعودًا شاقًا ممتنعًا، وشدد بذلك صورة نفور الكافر وعجزه عن قبول الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص33–34، تحت عنوان «فائدة التضعيف في يصعد»","url":""}]},{"id":"s6-868","number":868,"surah":6,"verses":[125],"references":[{"surah":6,"verses":[125]}],"verseLabel":"الأنعام: 125","question":"لماذا أوثر لفظ ﴿الرجس﴾ على لفظ العذاب؟","answer":"الرجس ما تستقذره النفوس، فيجمع معنى العقوبة مع الخبث والنفور؛ فاختياره يصور ما يلابسهم من ضلال وعذاب شيئًا مستقذرًا يناسب إصرارهم على الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص38، تحت عنوان «نكتة إيثار لفظ الرجس على العذاب»","url":""}]},{"id":"s6-1350","number":1350,"surah":6,"verses":[125],"references":[{"surah":6,"verses":[125]}],"verseLabel":"الأنعام: 125","question":"ما الصورة التي أفادها حرف ﴿على﴾ في قوله تعالى: ﴿يجعل الله الرجس على الذين لا يؤمنون﴾؟","answer":"أفاد الاستعلاء والتمكن، فكأن الرجس قد علاهم وأحاط بهم واستقر فوقهم؛ فاشتدت صورة لزوم العقوبة وغلبتها لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص38، تحت عنوان «بلاغة المجاز في حرف الاستعلاء»","url":""}]},{"id":"s6-869","number":869,"surah":6,"verses":[126],"references":[{"surah":6,"verses":[126]}],"verseLabel":"الأنعام: 126","question":"ما فائدة ﴿مستقيمًا﴾ بعد إضافة الصراط إلى الرب في ﴿وهذا صراط ربك مستقيمًا﴾؟","answer":"هي حال مؤكدة؛ فإضافة الصراط إلى الله تقتضي استقامته، ثم صُرّح بها تثبيتًا لهذا المعنى. وليست استقامة عارضة تزول، بل صفة ثابتة للطريق الذي يهدي إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص46، تحت «بيان التعبير بالحال المؤكدة»","url":""}]},{"id":"s6-870","number":870,"surah":6,"verses":[126],"references":[{"surah":6,"verses":[126]}],"verseLabel":"الأنعام: 126","question":"لماذا ناسب لفظ الربوبية الحديث عن الهداية في قوله تعالى: ﴿صراط ربك﴾؟","answer":"لأن الربوبية تتضمن التربية والرعاية والإنعام؛ والهداية إلى الصراط المستقيم من أعظم آثار هذه العناية، فناسبها اسم الرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص45، تحت عنوان «نكتة اصطفاء الربوبية دون غيرها»","url":""}]},{"id":"s6-871","number":871,"surah":6,"verses":[126],"references":[{"surah":6,"verses":[126]}],"verseLabel":"الأنعام: 126","question":"لماذا خُتمت بـ﴿لقوم يذكرون﴾؟","answer":"لأنهم المنتفعون بالتفصيل: يتأملون الحجج ويتذكرونها ويقبلون الموعظة، فتثمر فيهم هداية. فتخصيصهم لا يعني حجب البيان عن غيرهم، بل إبراز من يستفيد منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص49، تحت «نكتة تخصيص القوم بالذكر»","url":""}]},{"id":"s6-872","number":872,"surah":6,"verses":[127],"references":[{"surah":6,"verses":[127]}],"verseLabel":"الأنعام: 127","question":"ما دلالة إضافة الدار إلى اسم الله ﴿السلام﴾؟","answer":"إذا كان السلام اسمًا لله فإضافة الدار إليه تشريف وتعظيم، وتدل على أنها في حفظه ورعايته وقربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص53، تحت عنوان «إضافة الدار إلى اسم الله السلام»","url":""}]},{"id":"s6-1351","number":1351,"surah":6,"verses":[127],"references":[{"surah":6,"verses":[127]}],"verseLabel":"الأنعام: 127","question":"لماذا أوثر اسم ﴿السلام﴾ في قوله تعالى: ﴿لهم دار السلام﴾؟","answer":"لأنه يجمع سلامة الجنة من الفناء والآفات، وسلام أهلها بعضهم على بعض، وما فيها من تحية الملائكة؛ فكان أوسع من مجرد الأمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص53، تحت عنوان «علة إيثار اسم السلام على غيره»","url":""}]},{"id":"s6-873","number":873,"surah":6,"verses":[127],"references":[{"surah":6,"verses":[127]}],"verseLabel":"الأنعام: 127","question":"ما سر التعبير بقوله تعالى: ﴿عند ربهم﴾؟","answer":"ليست العندية مكانية، بل تفيد قرب التكريم وعلو المنزلة وضمان الجزاء؛ فدار السلام ثابتة لهم في جوار رحمة ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص54، تحت عنوان «بديع التعبير بلفظ العندية»","url":""}]},{"id":"s6-874","number":874,"surah":6,"verses":[127],"references":[{"surah":6,"verses":[127]}],"verseLabel":"الأنعام: 127","question":"ما دلالة الإخبار بأن الله ﴿وليهم﴾؟","answer":"دل على أنه يتولى حفظهم ونصرهم وإيصال الخير ودفع الآفات عنهم؛ فالولاية قرب ورعاية وتشريف، لا مجرد جزاء عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص56، تحت عنوان «نكتة الإخبار بكونه تعالى ﴿وليهم﴾»","url":""}]},{"id":"s6-875","number":875,"surah":6,"verses":[128],"references":[{"surah":6,"verses":[128]}],"verseLabel":"الأنعام: 128","question":"لماذا نادى الجن وحدهم أولًا: ﴿يا معشر الجن قد استكثرتم من الإنس﴾؟","answer":"بدأ بالجن لأنهم أصل الإغواء في هذا السياق، ولأن الخطاب السابق تناول استكثارهم من إضلال الإنس الذين اتخذوهم أولياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص65، تحت «دلالة نداء المعشر»","url":""}]},{"id":"s6-876","number":876,"surah":6,"verses":[128],"references":[{"surah":6,"verses":[128]}],"verseLabel":"الأنعام: 128","question":"لماذا عبّر عن علاقة الجن والإنس بلفظ ﴿الاستمتاع﴾؟","answer":"لأن الاستمتاع يدل على طلب المنفعة واللذة؛ فكشف أن ما جمع الفريقين لم يكن حقًا ولا هداية، بل مصالح وشهوات عاجلة انتهت إلى الحسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص71، تحت عنوان «قصدية التعبير بلفظ الاستمتاع»","url":""}]},{"id":"s6-1352","number":1352,"surah":6,"verses":[128],"references":[{"surah":6,"verses":[128]}],"verseLabel":"الأنعام: 128","question":"ما فائدة قوله: ﴿استمتع بعضنا ببعض﴾؟","answer":"أظهر التبادل بين الفريقين: انتفع الجن بطاعة الإنس وتعظيمهم، وانتفع الإنس بما توهموه من حماية وخبر وقضاء شهوة؛ فاشتركا في علاقة الإضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص71، تحت عنوان «فائدة التعبير باستمتاع بعضهم ببعض»","url":""}]},{"id":"s6-877","number":877,"surah":6,"verses":[128],"references":[{"surah":6,"verses":[128]}],"verseLabel":"الأنعام: 128","question":"ما وجه البلاغة في الكناية في وبلغنا أجلنا في قوله تعالى: ﴿وبلغنا أجلنا﴾؟","answer":"كَنَوا به عن بلوغ وقت البعث والحساب، وفي اعترافهم حسرة على زمن الدنيا الذي استنفدوه في الاستمتاع والضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص72، تحت عنوان «بلاغة الكناية في وبلغنا أجلنا»","url":""}]},{"id":"s6-878","number":878,"surah":6,"verses":[128],"references":[{"surah":6,"verses":[128]}],"verseLabel":"الأنعام: 128","question":"ما سرّ التعبير في قوله تعالى: ﴿النار مثواكم﴾، لا: مأواكم؟","answer":"المثوى مقام الإقامة الطويلة المستقرة، وهو أنسب بخلودهم في النار من لفظ المأوى الذي قد يطلق على مجرد موضع اللجوء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص78–79، تحت «الفروق المعجمية: المثوى والمآل والمقام والمنزل والمصير والمقر»","url":""}]},{"id":"s6-879","number":879,"surah":6,"verses":[128],"references":[{"surah":6,"verses":[128]},{"surah":11,"verses":[107]}],"verseLabel":"الأنعام: 128؛ هود: 107","question":"ما دلالة الاستثناء في قوله: ﴿إلا ما شاء الله﴾ بعد ذكر الخلود في الأنعام؟","answer":"يبين أن الخلود جارٍ بمشيئة الله ولا يخرج عن قدرته، ويحتمل استثناء من شاء الله من عصاة أهل الإيمان فلا يخلدون خلود الكافرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص75، تحت «دلالة الاستثناء، وفائدته»","url":""}]},{"id":"s6-1411","number":1411,"surah":6,"verses":[128],"references":[{"surah":6,"verses":[128]},{"surah":11,"verses":[107]}],"verseLabel":"الأنعام: 128؛ هود: 107","question":"عمَّ تكني جملة الاستثناء ﴿إلا ما شاء الله﴾ في سياق الخلود؟","answer":"تكني عن دوام سلطان الله ونفوذ مشيئته؛ فالخلود ليس أمرًا خارجًا عن قدرته، وإنما يقع ويستمر بإرادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص76، تحت «بلاغة الكناية في جملة الاستثناء»","url":""}]},{"id":"s6-1412","number":1412,"surah":6,"verses":[128],"references":[{"surah":6,"verses":[128]},{"surah":11,"verses":[107]}],"verseLabel":"الأنعام: 128؛ هود: 107","question":"ما معنى الاستثناء في قوله: ﴿إلا ما شاء ربك﴾ في سورة هود؟","answer":"يُحمل على استثناء عصاة الموحّدين الذين يعذبون مدة ثم تدركهم رحمة الله، فلا تكون إقامتهم في النار أبدية كإقامة الكافرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص727، تحت «معنى الاستثناء»","url":""}]},{"id":"s6-1413","number":1413,"surah":6,"verses":[128],"references":[{"surah":6,"verses":[128]},{"surah":11,"verses":[107]}],"verseLabel":"الأنعام: 128؛ هود: 107","question":"ما بلاغة الاستئناف بقوله: ﴿إن ربك فعال لما يريد﴾ بعد الاستثناء؟","answer":"جاء جوابًا عما قد يثيره الاستثناء من سؤال، فقرر أن الحكم كله تابع لإرادة الله النافذة، وأنه يفعل في عباده ما تقتضيه حكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص727–728، تحت «بلاغة الاستئناف البياني»","url":""}]}]);
